window.USUL_DATA={"site_title":"الحیات مرکز علوم اسلامیہ (اصول فقہ)","units":[{"id":1,"name":"یونٹ اول","title":"تعارف، دائرۂ کار اور تاریخی ارتقا","start":1,"end":4},{"id":2,"name":"یونٹ دوم","title":"حکم شرعی اور اہلیت","start":5,"end":10},{"id":3,"name":"یونٹ سوم","title":"ادلۂ شرعیہ اور مصادر شریعت","start":11,"end":16},{"id":4,"name":"یونٹ چہارم","title":"مختلف فیہ اور تکمیلی مصادر","start":17,"end":24},{"id":5,"name":"یونٹ پنجم","title":"مقاصد شریعت","start":25,"end":28},{"id":6,"name":"یونٹ ششم","title":"مباحث الفاظ کی بنیادیں","start":29,"end":35},{"id":7,"name":"یونٹ ہفتم","title":"دلالات نصوص اور اصولی مناہج","start":36,"end":40},{"id":8,"name":"یونٹ ہشتم","title":"بیان، نسخ، تعارض اور ترجیح","start":41,"end":44},{"id":9,"name":"یونٹ نہم","title":"اجتہاد، تقلید، افتاء اور اختلاف","start":45,"end":49},{"id":10,"name":"یونٹ دہم","title":"فقہی مذاہب اور اصولی مناہج","start":50,"end":54},{"id":11,"name":"یونٹ یازدہم","title":"اصول، فروع اور قواعد فقہیہ","start":55,"end":57},{"id":12,"name":"یونٹ دوازدہم","title":"معاصر اصول فقہ اور عملی تطبیقات","start":58,"end":64}],"interview_questions":[{"number":1,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":1,"chapter_title":"فقہ اور اصول فقہ کا بنیادی تعارف","question":"اگر آپ سے انٹرویو میں اصولِ فقہ کی جامع تعریف پوچھی جائے تو آپ اس کے موضوع، غرض اور بنیادی اجزا کو کیسے بیان کریں گے؟","answer":["اصول فقہ شرعی دلائل سے عملی احکام اخذ کرنے کے قواعد، دلائل کی حجیت اور مجتہد کی اہلیت کا علم ہے۔ اس کا موضوع کسی ایک عبادت یا معاملے کا حکم نہیں، بلکہ حکم تک پہنچنے کا معتبر طریقہ ہے۔ مثلاً نماز کی فرضیت فقہی مسئلہ ہے، جبکہ صیغۂ امر سے وجوب سمجھنا اصولی بحث ہے۔ اس علم کا مقصد استنباط کو منضبط بنانا اور نص پر بے دلیل معنی مسلط کرنے سے بچانا ہے۔","اصول فقہ وہ علم ہے جو تین بنیادی سوالات کا جواب دیتا ہے۔ شرعی حکم کے معتبر دلائل کون سے ہیں؟ ان دلائل سے حکم کس طریقے سے سمجھا جائے؟ اور حکم اخذ کرنے والا شخص کن علمی شرائط کا حامل ہو؟","پہلا حصہ اجمالی دلائل سے متعلق ہے۔ قرآن، سنت، اجماع اور قیاس کی حجیت اسی میں زیر بحث آتی ہے۔ یہاں کسی ایک جزوی مسئلے کا حکم مقصود نہیں ہوتا۔ بحث یہ ہوتی ہے کہ کوئی ماخذ اصولی طور پر دلیل کیوں ہے اور اس کی حجیت کی حدود کیا ہیں۔","دوسرا حصہ دلیل سے فائدہ اٹھانے کے طریقے کا ہے۔ عام و خاص، مطلق و مقید، امر و نہی، منطوق و مفہوم، تعارض و ترجیح اور نسخ جیسے مباحث اسی سوال کو واضح کرتے ہیں کہ نص اپنے حکم پر کیسے دلالت کرتی ہے۔","تیسرا حصہ مستفید، یعنی مجتہد، سے متعلق ہے۔ ہر شخص کو دلائل سے براہ راست حکم نکالنے کا حق نہیں۔ اس کے لیے قرآن، سنت، عربی زبان، فقہی ذخیرے، اصولی قواعد اور حالات واقعہ کا مناسب علم ضروری ہے۔","اس طرح اصول فقہ محض چند قواعد کا مجموعہ نہیں۔ یہ دلیل، دلالت، استدلال اور مجتہد کو ایک مربوط علمی نظام میں جمع کرتا ہے۔","فقہ کے اجمالی دلائل، ان سے فائدہ اٹھانے کے طریقے اور ان سے حکم اخذ کرنے والے شخص کے حال کو جاننا۔","دلائل فقہ اجمالاً سے کلی مصادر اور عمومی قواعد مراد ہیں۔ کیفیت استفادہ سے دلالات، تعارض اور ترجیح کا منہج مراد ہے۔ حال المستفید سے مجتہد کی اہلیت، اجتہاد اور تقلید کے مباحث مراد ہیں۔"],"definitions":[{"studyQuestion":1,"term":"فقہ: امام ابو حنیفہؒ کی تعریف","arabic":"أَبُو حَنِيفَةَ ﵀ أَطْلَقَ الْفِقْهَ عَلَى الْعِلْمِ بِمَا لَهَا وَعَلَيْهَا","translation":"امام ابو حنیفہؒ نے فقہ کا اطلاق اُس علم پر کیا جو نفس کے حقوق و ذمہ داریوں (ما لها وما عليها) کا احاطہ کرے۔","explanation":"تلویح کے مطابق یہ تعریف اعتقادی، وجدانی اور عملی تینوں پہلو شامل کرتی ہے، اسی لیے علمِ کلام کو «فقہِ اکبر» بھی کہا گیا۔ اصطلاحی فقہ (صرف عملیات) کے لیے «عملاً» کی قید بڑھائی جاتی ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"تعريف الفقه","url":"https://shamela.ws/book/9508/17"},"kind":"definition","originalStudyQuestion":1}],"originalNumber":1},{"number":2,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":2,"chapter_title":"شریعت فقہ اور اسلامی قانون","question":"فقہ، شریعت، دین اور اسلامی قانون میں بنیادی فرق کیا ہے، اور ایک فقہی رائے کو شریعت کہنے میں کیا احتیاط ضروری ہے؟","answer":["دین اللہ تعالیٰ کی ہدایت کا جامع عنوان ہے؛ عقیدہ، عبادت، اخلاق اور معاملات اس میں شامل ہیں۔ شریعت اس ہدایت کے مقرر کردہ احکام اور راستے کو کہتے ہیں، جبکہ فقہ عملی احکام کا انسانی علمی فہم ہے۔ اسلامی قانون معاصر استعمال میں فقہی احکام کی قانونی تنظیم، تقنین اور نفاذ کے لیے بھی بولا جاتا ہے۔ ہر اجتہادی رائے کو قطعی شریعت کہنا درست نہیں، لیکن فقہ کے ثابت اور اجماعی احکام کو محض ذاتی رائے کہنا بھی غلط ہے۔","شریعت اور فقہ کا تعلق اصل اور فہمِ اصل کا ہے۔ مثال کے طور پر نماز کا وجوب شریعت کا حکم ہے جو قطعی اور غیرمتغیر ہے، مگر نماز کے بعض جزئی مسائل، مثلاً قصر کی مسافت کی تحدید یا سجدہ سہو کے مواقع، فقہاء کے اجتہاد کا نتیجہ ہیں۔ اس طرح شریعت وہ اصل الٰہی حکم ہے جو براہِ راست نازل ہوا، جبکہ فقہ اس حکم کی تفہیم، تفصیل اور اطلاقی صورتوں پر مشتمل انسانی علمی کاوش ہے، جس میں غلطی کا امکان بھی موجود رہتا ہے۔","شریعت سے مراد وہ الٰہی ہدایت ہے جو اللہ تعالیٰ نے انسان کی انفرادی اور اجتماعی زندگی کے لیے مقرر فرمائی۔ اس میں عقیدہ، عبادت، اخلاق، معاملات، معاشرت اور عدل کے بنیادی احکام سب شامل ہیں۔ اس لیے شریعت کو صرف عدالت یا تعزیرات کے قوانین تک محدود کرنا درست نہیں۔","لغت میں شریعت اس واضح راستے کو کہتے ہیں جو پانی کے سرچشمے تک لے جائے۔ اس مفہوم میں زندگی اور رہنمائی دونوں پائے جاتے ہیں۔ دینی اصطلاح میں شریعت وہ سیدھا راستہ ہے جو انسان کو اپنے رب کی رضا اور ایک پاکیزہ زندگی تک پہنچاتا ہے۔","قرآنی دلیل: ﴿ثُمَّ جَعَلْنَاكَ عَلَىٰ شَرِيعَةٍ مِنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ﴾ (الجاثیۃ: 18)","پھر ہم نے آپ کو دین کے معاملے میں ایک واضح شریعت پر قائم کیا، لہٰذا آپ اسی کی پیروی کریں اور نادان لوگوں کی خواہشات کی پیروی نہ کریں۔","آیت شریعت کو خواہش انسانی کے مقابل ایک الٰہی اور منضبط راستہ قرار دیتی ہے۔ اس راستے کے کچھ احکام قطعی اور مستقل ہیں۔ کچھ امور میں اصول دیے گئے ہیں جن کی روشنی میں اجتہاد کے ذریعے نئی صورتوں کا حکم معلوم کیا جاتا ہے۔"],"definitions":[{"studyQuestion":2,"term":"الفقه: تعریفِ شافعیہ","arabic":"الْعِلْمُ بِالْأَحْكَامِ الشَّرْعِيَّةِ الْعَمَلِيَّةِ مِنْ أَدِلَّتِهَا التَّفْصِيلِيَّةِ","translation":"عملی شرعی احکام کا اُن کی تفصیلی دلیلوں سے حاصل ہونے والا علم۔","explanation":"تلویح اسے اصحابِ شافعیؒ کی تعریف بتاتی ہے۔ «شرعیہ» سے عقلی و حسی احکام، «عملیہ» سے اعتقادی احکام اور «تفصیلیہ» سے مقلّد کا علم خارج ہو جاتا ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"تعريف الفقه","url":"https://shamela.ws/book/9508/18"},"kind":"definition","originalStudyQuestion":2}],"originalNumber":2},{"number":3,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":1,"chapter_title":"فقہ اور اصول فقہ کا بنیادی تعارف","question":"فقہ اور اصولِ فقہ کا باہمی تعلق کیا ہے، اور دونوں کے موضوع و منہج میں بنیادی فرق کیسے واضح کریں گے؟","answer":["فقہ کا مرکزی سوال ہے کہ مکلف کے کسی عمل کا شرعی حکم کیا ہے؛ اصول فقہ کا سوال ہے کہ یہ حکم کس دلیل اور کس طریقۂ استنباط سے معلوم ہوا۔ مثال کے طور پر سود کی حرمت فقہی حکم ہے، جبکہ نہی کی دلالت اور علتِ ربا کی تعیین اصولی مباحث ہیں۔ اس فرق سے دلیل، قاعدہ اور نتیجہ الگ پہچانے جاتے ہیں۔ فقہی حکم بیان کرتے وقت اس کی دلیل کی نوعیت اور اجتہادی درجے کی وضاحت علمی جواب کو مضبوط کرتی ہے۔","فقہ اور اصول فقہ میں بنیادی فرق نتیجے اور طریقۂ استنباط کا ہے۔ فقہ عملی شرعی احکام بیان کرتا ہے۔ اصول فقہ یہ واضح کرتا ہے کہ ان احکام تک پہنچنے کے لیے دلائل کو کس طرح سمجھا اور استعمال کیا جائے۔","مثلاً فقہ بتاتا ہے کہ نماز فرض ہے، سود حرام ہے اور صحیح خرید و فروخت کے لیے باہمی رضامندی ضروری ہے۔ اصول فقہ یہ دیکھتا ہے کہ امر وجوب پر کب دلالت کرتا ہے، نہی سے حرمت کیسے ثابت ہوتی ہے اور کسی عام یا مطلق نص کا دائرہ کس اصول سے متعین ہوگا۔","دونوں کے موضوع میں بھی فرق ہے۔ فقہ کا تعلق مکلف کے اعمال اور ان کے احکام سے ہے۔ اصول فقہ کا تعلق شرعی دلائل، ان کی دلالت اور استنباط کے طریقے سے ہے۔ فقہ زیادہ تر جزئی مسائل پیش کرتا ہے، جبکہ اصول فقہ کلی ضابطے فراہم کرتا ہے۔","اس فرق کے باوجود دونوں ایک دوسرے سے جدا نہیں۔ اصول کے بغیر فقہ بے ضابطہ ہوسکتا ہے، اور فقہی مثالوں کے بغیر اصول محض نظری بحث بن سکتا ہے۔ کامل فقہی فہم وہ ہے جس میں حکم بھی معلوم ہو اور اس حکم تک پہنچنے کی اصولی بنیاد بھی واضح ہو۔"],"definitions":[],"originalNumber":3},{"number":4,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":1,"chapter_title":"فقہ اور اصول فقہ کا بنیادی تعارف","question":"شرعی نصوص موجود ہونے کے باوجود اصولِ فقہ کی ضرورت کیوں پیش آتی ہے؟","answer":["نص کا موجود ہونا اور اس سے درست حکم اخذ کرنا دو مختلف باتیں ہیں۔ روایت کی صحت، لفظ کی دلالت، خطاب کا سیاق اور دوسری نصوص سے اس کا تعلق الگ تحقیق چاہتے ہیں۔ مثلاً کسی امر کو ہر جگہ فرض سمجھ لینا درست نہیں؛ قرینہ اسے استحباب یا اباحت کی طرف لے جاسکتا ہے۔ اصول فقہ ان امکانات کو منظم کرتا ہے اور واضح کرتا ہے کہ کس دلیل سے کون سا نتیجہ نکل سکتا ہے۔","قرآن و سنت ہدایت کے بنیادی سرچشمے ہیں، لیکن ان سے حکم اخذ کرنا ایک باقاعدہ علمی عمل ہے۔ پہلے یہ دیکھا جاتا ہے کہ دلیل ثابت ہے یا نہیں۔ پھر اس کے الفاظ، سیاق، مقصد اور دائرۂ اطلاق کو سمجھا جاتا ہے۔ اصول فقہ اسی پورے عمل کو ترتیب دیتا ہے۔","ایک آیت عام ہوسکتی ہے، مگر دوسری دلیل اس کے بعض افراد کو خارج کردیتی ہے۔ ایک حکم مطلق ہوسکتا ہے، مگر دوسری نص اسے کسی شرط کے ساتھ مقید کردیتی ہے۔ ایک صحیح حدیث کسی خاص موقع، شخص یا حالت سے متعلق ہوسکتی ہے۔ اگر یہ فرق نظر انداز ہوجائیں تو نص موجود ہونے کے باوجود نتیجہ غلط ہوسکتا ہے۔","نئے مسائل میں یہ ضرورت اور بڑھ جاتی ہے۔ جدید مالی معاملات، طبی طریقے اور ڈیجیٹل صورتیں قدیم کتابوں میں انہی ناموں سے موجود نہیں۔ پہلے مسئلے کی حقیقت سمجھی جاتی ہے۔ پھر اس کی فقہی نوعیت متعین کی جاتی ہے۔ اس کے بعد متعلقہ نصوص، علل، قواعد اور مقاصد کا اطلاق کیا جاتا ہے۔","اصول فقہ انسان کو اپنی رائے پر شریعت کا نام لگانے سے روکتا ہے۔ یہ بتاتا ہے کہ دلیل کیا ہے، اس کی حد کیا ہے اور نتیجہ کس درجے کا ہے۔ اسی لیے اصول فقہ فہم شریعت کا آلہ بھی ہے اور بے اصول استدلال سے حفاظت کا ذریعہ بھی۔","قرآنی رہنمائی: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ﴾ (النحل: 43)","اگر تم نہیں جانتے تو اہل علم سے پوچھو۔","یہ آیت علم میں اہلیت اور تخصص کی ضرورت واضح کرتی ہے۔ شرعی استنباط میں بھی صرف ترجمہ دیکھ لینا کافی نہیں، بلکہ دلائل، زبان، سنت اور اصولی منہج کا علم ضروری ہے۔"],"definitions":[],"originalNumber":4},{"number":5,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":4,"chapter_title":"اصول فقہ کے بڑے مناہج","question":"اصولِ فقہ، قواعدِ فقہیہ اور مقاصدِ شریعت میں بنیادی فرق اور باہمی تعلق کیا ہے؟","answer":["اصولی قاعدہ دلیل سے حکم اخذ کرنے کا طریقہ بتاتا ہے، فقہی قاعدہ متعدد عملی مسائل کے مشترک حکم کو سمیٹتا ہے، اور مقصدِ شریعت احکام کی معتبر غایت واضح کرتا ہے۔ امر کی اصل دلالت وجوب ہونا اصولی قاعدہ، ضرر کا ازالہ فقہی قاعدہ، اور جان کا تحفظ مقصد ہے۔ یہ تینوں مربوط ہیں، مگر مترادف نہیں۔ ہر فقہی قاعدہ صرف مقصد کی ترجمانی نہیں کرتا؛ بعض قواعد ثبوت، نیت اور سابق حالت کے اعتبار کو منظم کرتے ہیں۔","قواعدِ اصولیہ وہ کلی قواعد ہیں جن کا تعلق نصوص کی تعبیر اور استنباط کے طریقے سے ہے، جیسے 'الامر یقتضی الوجوب'۔ ان کا اطلاق زبان و دلالت پر ہوتا ہے۔ قواعدِ فقہیہ وہ کلی اصول ہیں جو متعدد فقہی فروع کے مشترکہ مقصد یا علت سے اخذ کیے جاتے ہیں، جیسے 'الضرر یزال'۔ ان کا اطلاق براہِ راست فقہی احکام پر ہوتا ہے۔ فرق یہ ہے کہ قواعدِ اصولیہ استنباط کا ذریعہ ہیں جبکہ قواعدِ فقہیہ استنباط کا نتیجہ اور خلاصہ ہیں۔"],"definitions":[],"originalNumber":5},{"number":6,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":3,"chapter_title":"اصول فقہ کا تاریخی ارتقا","question":"فقہ اور اصولِ فقہ کے تاریخی ارتقا کو آپ کن اہم ادوار میں تقسیم کریں گے؟","answer":["تاریخی ارتقا میں عہدِ نبوی، عہدِ صحابہ، تابعین کے علمی مراکز، ائمہ و تدوین کا دور، اصولی مناہج کی پختگی، اور بعد کی شرح و تخریج اور معاصر تحقیق کے ادوار نمایاں ہیں۔ ابتدا میں استنباط عملی صورت میں موجود تھا؛ بعد میں قواعد مستقل کتابوں میں مرتب ہوئے۔ الرسالہ اولین محفوظ منظم اصولی تصانیف میں نمایاں مقام رکھتی ہے۔ اس سے یہ مراد نہیں کہ امام شافعیؒ سے پہلے اصولی فکر یا فقہی استدلال موجود نہ تھا۔","اصولِ فقہ بطور مستقل مدون علم امام شافعی رحمہ اللہ کی کاوش سے وجود میں آیا، جنہوں نے اپنی کتاب الرسالۃ میں پہلی بار اصولِ استنباط کو منظم اور مستقل شکل میں پیش کیا۔ اس سے پہلے اصولی مباحث فقہی جزئیات کے اندر بکھرے ہوئے تھے، بغیر کسی مستقل نظم کے۔ امام شافعی نے قرآن، سنت، اجماع اور قیاس کی حجیت، ترتیب اور ان کے استعمال کے قواعد کو پہلی بار ایک مربوط کتاب کی صورت میں جمع کیا، اسی لیے انہیں 'واضعِ علمِ اصول' یا 'اصولِ فقہ کا بانی' کہا جاتا ہے۔","فقہ کی باقاعدہ تدوین دوسری صدی ہجری میں، عباسی دور کے اوائل میں شروع ہوئی، جب امام ابوحنیفہ، امام مالک اور بعد میں امام شافعی اور امام احمد بن حنبل جیسے ائمہ مجتہدین نے اپنے فقہی مسائل کو منظم انداز میں مدون کیا۔ اس دور میں امام مالک کی مؤطا اور امام محمد بن حسن شیبانی کی کتب (الجامع الصغیر، الجامع الکبیر) فقہی تدوین کی ابتدائی نمایاں مثالیں ہیں۔ یہی دور فقہ کے 'عصرِ ائمہ' یا 'عصرِ تدوین' کے نام سے مشہور ہے۔"],"definitions":[],"originalNumber":6},{"number":7,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":3,"chapter_title":"اصول فقہ کا تاریخی ارتقا","question":"عہدِ صحابہؓ میں نئے مسائل کے حل اور اجتہاد کا منہج کیا تھا؟","answer":["صحابہؓ پہلے متعلقہ نص اور نبوی عمل تلاش کرتے، روایت کی تحقیق کرتے اور نئے واقعے کی حقیقت سمجھتے تھے۔ جہاں واضح حکم نہ ملتا وہاں مشاورت اور اجتہاد سے کام لیتے۔ اجتماعی مشورہ بذات خود اجماع نہیں؛ اجماع کے لیے متعلقہ اہلِ اجتہاد کا ثابت اتفاق ضروری ہے۔ حضرت عمرؓ کے انتظامی فیصلوں کو سمجھتے وقت اصل شرعی حکم، اس کی شرائط اور بدلتے ہوئے حالات الگ رکھنا چاہیے؛ انہیں نصوص کی منسوخی کہنا درست نہیں۔","نبی کریم ﷺ کی وفات کے بعد وحی کا سلسلہ منقطع ہو گیا، جس سے صحابہ کرام کو نئے پیش آمدہ مسائل پر خود اجتہاد کرنا پڑا۔ اس دور میں خلفائے راشدین، خصوصاً حضرت عمر رضی اللہ عنہ، نے کئی نئے مسائل پر قرآن و سنت کی روشنی میں اجتہادی فیصلے کیے۔ اسی دور میں 'مکتبِ اہلِ حدیث' (مدینہ) اور 'مکتبِ اہلِ رائے' (کوفہ) کے ابتدائی رجحانات نمایاں ہونے لگے، جو بعد میں فقہی مذاہب کی بنیاد بنے۔ فقہائے صحابہ میں عبداللہ بن مسعود، عبداللہ بن عباس، زید بن ثابت اور عائشہ صدیقہ رضی اللہ عنہم نمایاں تھے۔","رسول اللہ ﷺ کی وفات کے بعد وحی کا سلسلہ ختم ہوگیا، مگر زندگی کے مسائل بڑھتے رہے۔ اسلامی ریاست وسیع ہوئی۔ نئے علاقوں، اقوام، تجارتی صورتوں اور انتظامی ضرورتوں نے ایسے سوالات پیدا کیے جن کا نام لے کر حکم پہلے موجود نہ تھا۔","صحابہ پہلے قرآن میں رہنمائی تلاش کرتے۔ پھر سنت معلوم کرتے۔ اگر صریح نص نہ ملتی تو باہمی مشورہ، اجماع، قیاس، مصلحت اور واقعے کی صحیح سمجھ سے حکم تک پہنچتے۔ کسی حدیث کا علم ایک صحابی کو ہوتا اور دوسرے کو نہ ہوتا، اس لیے تحقیق اور روایت کی تصدیق بھی ضروری تھی۔","قرآنی تعبیر: ﴿لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ﴾ (النساء: 83)","تو ان میں سے وہ لوگ اسے جان لیتے جو اس سے صحیح نتیجہ اخذ کرنے کی صلاحیت رکھتے ہیں۔","اجتہاد کی ضرورت صرف نئی صورتوں کی وجہ سے نہیں تھی۔ کبھی نص کے مفہوم، عموم، تخصیص یا اطلاق میں غور درکار ہوتا۔ کبھی دو دلائل میں ظاہری تعارض محسوس ہوتا۔ کبھی اجتماعی مصلحت کے لیے انتظامی فیصلہ کرنا پڑتا۔ ان حالات نے فقہی استنباط کے ابتدائی اصولوں کو عملی صورت دی۔","صحابہ کے منہج کی پہلی خصوصیت نص سے گہری وابستگی تھی۔ وہ قرآن کو بنیاد بناتے اور سنت کی تلاش کرتے۔ حدیث قبول کرتے وقت راوی، واقعہ اور مفہوم کی تحقیق بھی کرتے۔ ان کے لیے نص محض عبارت نہیں تھی؛ وہ شان نزول، نبوی عمل اور عربی ماحول سے بھی واقف تھے۔","دوسری خصوصیت مسئلے کی حقیقت کو سمجھنا تھی۔ وہ حکم لگانے سے پہلے دیکھتے کہ واقعہ کیا ہے اور اس کا تعلق کس اصل سے بنتا ہے۔ تیسری خصوصیت مشاورت تھی۔ اہم اجتماعی مسائل میں اہل علم صحابہ کو جمع کیا جاتا۔ اس سے انفرادی رائے کی کمزوری کم ہوتی اور اجتماعی بصیرت سامنے آتی۔","چوتھی خصوصیت مقاصد اور نتائج کا لحاظ تھا۔ حضرت عمر رضی اللہ عنہ کے کئی انتظامی فیصلے اس بات کی مثال ہیں کہ نص کی پابندی کے ساتھ حالات، عدل اور اجتماعی مصلحت کو سمجھا گیا۔ اس کا مطلب نص سے آزادی نہیں، بلکہ نص کے مقصد کی ذمہ دار تطبیق ہے۔","پانچویں خصوصیت علمی احتیاط تھی۔ وہ اپنی رائے کو وحی کا درجہ نہیں دیتے تھے۔ اختلاف کے باوجود ایک دوسرے کی دیانت اور اجتہاد کا احترام کرتے۔ یہی طرز بعد کے اصول فقہ کے لیے بنیادی سرمایہ بنا۔"],"definitions":[],"originalNumber":7},{"number":8,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":3,"chapter_title":"اصول فقہ کا تاریخی ارتقا","question":"اہلِ حدیث اور اہلِ رائے کے مناہج میں بنیادی فرق کیوں پیدا ہوا، اور اس اختلاف کا فقہی روایت پر کیا اثر پڑا؟","answer":["اہلِ حدیث اور اہلِ رائے تاریخی علمی رجحانات ہیں؛ ان کے عنوانات کو موجودہ جماعتی شناختوں پر خودکار طور پر منطبق نہیں کرنا چاہیے۔ دونوں سنت کی حجیت مانتے تھے، مگر روایات تک رسائی، قبولِ خبر کے معیارات اور نئے مسائل میں استدلال کی ترجیحات مختلف تھیں۔ اہلِ رائے سے بے دلیل رائے اور اہلِ حدیث سے اجتہاد کی نفی مراد نہیں۔ یہ تقسیم تدریجی اور نسبی تھی، اور دونوں حلقوں کے اندر بھی علمی تنوع موجود تھا۔","اہل حدیث اور اہل رائے دونوں قرآن و سنت کو بنیادی حجت مانتے تھے۔ فرق اصل ماخذ میں نہیں، بلکہ دستیاب مواد، روایت کی جانچ، نئے مسائل کی کثرت اور استدلال کی ترجیحات میں تھا۔ اس لیے دونوں کو نص اور عقل کی مکمل ضد سمجھنا تاریخی طور پر درست نہیں۔","حجاز میں حدیث و آثار کا ذخیرہ زیادہ قریب اور وسیع تھا۔ وہاں معاشرتی تسلسل بھی نسبتاً مستحکم تھا۔ عراق میں نئے مسائل، سیاسی اضطراب اور روایت کے نام پر غلط بیانی کے خدشات زیادہ تھے۔ اس ماحول نے عراقی فقہاء کو سند کی سخت جانچ اور قیاس کی منظم توسیع کی طرف مائل کیا۔","اہل حدیث نص اور اثر کو مقدم رکھتے اور غیر واقع شدہ سوالات سے احتراز کرتے۔ اہل رائے بھی نص کو مقدم رکھتے، مگر نص نہ ملنے یا نئی صورت میں علت، قیاس اور فقہی اصولوں سے زیادہ کام لیتے۔ دونوں حلقوں کے اندر بھی متعدد درجے اور رجحانات تھے۔","بعد میں امام شافعی اور دوسرے ائمہ کی علمی کوششوں نے حدیث اور فقہی استدلال کے درمیان مضبوط ربط پیدا کیا۔ یوں یہ تقسیم مطلق نہ رہی۔ اسلامی فقہ کی پختگی اسی وقت سامنے آئی جب روایت کی حفاظت اور اجتہاد کی ضرورت دونوں کو جمع کیا گیا۔"],"definitions":[],"originalNumber":8},{"number":9,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":3,"chapter_title":"اصول فقہ کا تاریخی ارتقا","question":"امام شافعیؒ نے اصولِ فقہ کی تدوین میں کیا کردار ادا کیا، اور الرسالہ کی علمی اہمیت کیا ہے؟","answer":["الرسالہ کی اہمیت صرف سنت کی حجیت تک محدود نہیں۔ اس میں بیان، عام و خاص، کتاب و سنت کا تعلق، خبرِ واحد، اجماع، قیاس اور اختلافِ استدلال جیسے مباحث مربوط انداز میں سامنے آتے ہیں۔ امام شافعیؒ کی نمایاں خدمت پہلے سے جاری فقہی استنباط کو ایک واضح تحریری منہج دینا ہے۔ اس لیے انہیں تدوینِ اصول کا اہم پیش رو کہنا زیادہ محتاط تعبیر ہے؛ تمام اصولی فکر کا آغاز صرف انہی سے قرار دینا تاریخی اختصار ہوگا۔","الرسالہ نے سنت کو قرآن کے مقابل ایک ثانوی انسانی روایت نہیں سمجھا، بلکہ رسول اللہ ﷺ کی ثابت رہنمائی کے طور پر اس کی شرعی حجیت واضح کی۔ امام شافعی نے بتایا کہ سنت قرآن کی تائید، تشریح اور بعض امور میں مستقل حکم بیان کرتی ہے۔","قرآنی دلیل: ﴿مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ﴾ (النساء: 80)","جس نے رسول کی اطاعت کی، اس نے اللہ کی اطاعت کی۔","انہوں نے خبر واحد کی قبولیت کو راوی کی ثقاہت، اتصال اور روایت کی صحت جیسے علمی معیاروں سے جوڑا۔ اس طرح ہر منقول بات کو سنت قرار دینے اور صحیح روایت کو محض ظن کہہ کر چھوڑ دینے، دونوں انتہاؤں سے بچنے کی کوشش کی۔","استدلال کے باب میں انہوں نے واضح کیا کہ رائے نص سے آزاد نہیں ہوسکتی۔ اجماع اور قیاس بھی علم کے معتبر راستے ہیں، مگر قیاس کسی منصوص اصل، مشترک معنی اور علمی اہلیت کے ساتھ ہوگا۔","یوں الرسالہ نے سنت کی حجیت اور عقل کے استعمال دونوں کو ضبط دیا۔ اس نے روایت کو قانونی معنی سے اور قیاس کو نصی بنیاد سے جوڑا۔ یہی توازن اصول فقہ کی آئندہ تشکیل میں فیصلہ کن ثابت ہوا۔","الرسالۃ امام شافعی کی وہ کتاب ہے جسے اصولِ فقہ کی پہلی مستقل اور منظم تصنیف تسلیم کیا جاتا ہے۔ اس میں انہوں نے قرآن کی حجیت، بیان کی اقسام، سنت کی حیثیت، ناسخ و منسوخ، اجماع، قیاس اور اجتہاد جیسے موضوعات کو منظم انداز میں بیان کیا۔ اس کتاب کی اہمیت اس بات میں ہے کہ اس نے بعد کے تمام اصولیین کے لیے ایک بنیادی نمونہ فراہم کیا، اور آج بھی اسے اصولِ فقہ کے مآخذ میں بنیادی حیثیت حاصل ہے۔"],"definitions":[],"originalNumber":9},{"number":10,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":4,"chapter_title":"اصول فقہ کے بڑے مناہج","question":"منہجِ متکلمین، منہجِ فقہاء اور منہجِ جمع بین الطریقتین کی نمایاں خصوصیات کیا ہیں؟","answer":["طریقۂ متکلمین قواعد کو لسانی اور استدلالی دلائل سے قائم کرنے پر زیادہ زور دیتا ہے؛ طریقۂ فقہاء، بالخصوص حنفی روایت، منقول فروع اور قواعد کے باہمی تعلق کو نمایاں کرتا ہے۔ طریقۂ جمع دونوں کی خصوصیات یکجا کرتا ہے۔ یہ غالب رجحانات ہیں، قطعی تقسیم نہیں۔ متکلمین کی ہر کتاب شافعی نہیں اور ہر حنفی تصنیف صرف فروع کی توجیہ نہیں۔ بدیع النظام اور التوضیح میں مشترک منہج کی مثالیں ملتی ہیں۔","دونوں مناہج کا مقصد شرعی استنباط کو منظم کرنا ہے، مگر ان کا نقطۂ آغاز مختلف ہے۔ طریقۂ فقہاء میں منقول فروع سے قواعد کی طرف سفر ہوتا ہے۔ طریقۂ متکلمین میں نظری دلیل سے قاعدہ قائم کرکے فروع کی طرف بڑھا جاتا ہے۔","طریقۂ فقہاء میں فقہی مثالیں زیادہ اور مذہبی فروع سے تعلق گہرا ہوتا ہے۔ قاعدے کی عملی معنویت فوراً سامنے آتی ہے۔ طریقۂ متکلمین میں تعریفات، عقلی تقسیم، لسانی دلالت اور دلائل کا تنقیدی جائزہ زیادہ نمایاں ہوتا ہے۔","پہلے منہج میں یہ خطرہ ہوسکتا ہے کہ اصول پہلے سے موجود فروع کی توجیہ بن جائے۔ دوسرے میں یہ امکان ہوتا ہے کہ اصول بہت تجریدی ہوجائے اور فقہی عمل سے فاصلے پر چلا جائے۔ بڑے مصنفین نے ان کمزوریوں سے بچنے کی کوشش کی۔","یہ فرق مطلق نہیں۔ حنفی اصولیین نے نظری دلیل سے کام لیا اور متکلمین نے فقہی مثالیں پیش کیں۔ اصل فرق غالب رجحان، ترتیب اور علمی ترجیح کا ہے۔ دونوں نے اصول فقہ کی تعمیر میں اہم اور تکمیلی کردار ادا کیا۔","طریقۂ جمع بین الطریقتین وہ منہج ہے جس میں بعد کے اصولیین نے متکلمین کی نظری دقت اور فقہاء کی اطلاقی افادیت دونوں کو یکجا کرنے کی کوشش کی۔ یہ منہج اس لیے وجود میں آیا کیونکہ محض نظری اصول عملی فقہ سے کٹ کر رہ جاتے تھے، جبکہ محض فروع پر انحصار اصولی مباحث کی گہرائی کو کمزور کر دیتا تھا۔ اس منہج کی نمایاں کتابوں میں صدر الشریعہ کی التوضیح اور ابن الساعاتی کی بدیع النظام شامل ہیں، جو دونوں طریقوں کے فوائد کو ایک ساتھ پیش کرتی ہیں۔"],"definitions":[],"originalNumber":10},{"number":11,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":4,"chapter_title":"اصول فقہ کے بڑے مناہج","question":"تخریج الفروع علی الاصول اور تخریج الاصول من الفروع میں کیا فرق ہے، اور یہ فرق اصولی مناہج کو سمجھنے میں کیوں اہم ہے؟","answer":["تخریج الفروع علی الاصول میں معلوم اصولی قاعدے سے کسی فرعی حکم کا تعلق واضح کیا جاتا ہے؛ تخریج الاصول من الفروع میں متعدد منقول احکام کے مطالعے سے ان کے پیچھے کارفرما قاعدہ دریافت کیا جاتا ہے۔ پہلی حرکت قاعدے سے مسئلے کی طرف اور دوسری مسائل سے قاعدے کی طرف ہے۔ ایک دو مثالوں سے پورے مذہب کا اصول طے نہیں ہوتا؛ مخالف فروع، استثنا اور امام یا اصحاب کی صریح عبارات بھی دیکھی جاتی ہیں۔","اصولیین کے مناہج کا اختلاف بالواسطہ طور پر فقہی فروع پر بھی اثرانداز ہوتا ہے، کیونکہ مختلف مناہج نصوص کی تعبیر، دلالت اور ترجیح کے مختلف اصول اپناتے ہیں۔ مثال کے طور پر خبرِ واحد کی قطعیت یا ظنیت کے بارے میں مختلف مناہج کا نقطہ نظر اس بات پر اثرانداز ہوتا ہے کہ کسی خاص حدیث کی بنیاد پر فرض یا واجب کا حکم لگایا جائے یا نہیں۔ یہی وجہ ہے کہ اصولی اختلاف کو فقہی اختلاف کی جڑ سمجھا جاتا ہے، اور اصول کے بغیر فروع کے اختلاف کی گہرائی کو سمجھنا ممکن نہیں۔","تخریج الفروع علی الاصول وہ علم و طریقہ ہے جس میں فقہی جزئیات کو ان اصولی قواعد سے مربوط کیا جاتا ہے جن سے وہ اخذ ہوئی ہوں یا علمی طور پر مربوط ہوسکتی ہوں۔ اس سے معلوم ہوتا ہے کہ کسی فرعی اختلاف کے پیچھے دلالت، خبر، قیاس یا ترجیح کا کون سا اصول کام کر رہا ہے۔","مثلاً عام لفظ کی دلالت قطعی یا ظنی ماننے کا فرق خبرِ واحد سے تخصیص کے مسائل پر اثر ڈال سکتا ہے۔ تخریج محض حکم یاد نہیں کراتی؛ وہ حکم کی استدلالی ساخت دکھاتی ہے۔","تخریج الفروع علی الاصول فقہی فروع اور ان کے پسِ پشت اصولی قواعد کے تعلق کو واضح کرتی ہے۔ اس سے معلوم ہوتا ہے کہ ایک مذہب کے مختلف احکام محض منتشر فیصلے نہیں بلکہ اکثر مشترک اصولی بنیاد سے مربوط ہوتے ہیں۔","تحقیق میں تاریخی نسبت اور منطقی نسبت الگ رکھنا ضروری ہے: ہر بعد میں مدون قاعدہ لازماً پہلے فقیہ کے شعوری لفظی اصول کی نمائندگی نہیں کرتا، لیکن وہ اس کے فروع میں کارفرما منہج کی مناسب توضیح ہوسکتا ہے۔"],"definitions":[],"originalNumber":11},{"number":12,"unit_id":1,"unit_name":"یونٹ اول","unit_title":"تعارف، دائرۂ کار اور تاریخی ارتقا","chapter_number":3,"chapter_title":"اصول فقہ کا تاریخی ارتقا","question":"اصولِ فقہ کی بنیادی کلاسیکی کتب کون سی ہیں، اور ایک یونیورسٹی امیدوار کو ان کی علمی نسبت کیوں معلوم ہونی چاہیے؟","answer":["بنیادی مطالعے میں الرسالہ، اصول السرخسی، اصول البزدوی، المستصفیٰ، الإحکام اور الموافقات مختلف مناہج سمجھنے میں مدد دیتی ہیں۔ حنفی اصطلاحات کی ابتدائی گرفت کے لیے اصول الشاشی اور نور الأنوار فی شرح المنار اہم ہیں۔ نور الأنوار ملا جیون کی شرح ہے، جبکہ اس کا متن منار الأنوار امام نسفی کا ہے۔ متن کی عبارت، شرح کی توضیح اور حاشیے کی رائے کو الگ پہچاننا درست علمی نسبت کے لیے ضروری ہے۔","اصولِ فقہ کی بنیادی کتب میں امام شافعی کی الرسالۃ (اصولِ فقہ کی پہلی مستقل تصنیف)، امام غزالی کی المستصفیٰ (طریقۂ متکلمین کی نمائندہ کتاب)، امام سرخسی کی اصول السرخسی اور امام بزدوی کی اصول البزدوی (طریقۂ فقہاء کی نمائندہ کتب) شامل ہیں۔ یہ تمام کتب مختلف مناہج کی نمائندگی کرتی ہیں اور آج بھی اصولِ فقہ کے طالب علموں کے لیے بنیادی حوالہ سمجھی جاتی ہیں۔","اصول السرخسی (امام سرخسی) اور اصول البزدوی (امام بزدوی) حنفی مکتب کی طریقۂ فقہاء پر مبنی سب سے مستند اور بنیادی اصولی کتب ہیں، جو حنفی مذہب کے استنباطی طریقۂ کار کو نہایت تفصیل سے بیان کرتی ہیں۔ بعد کے حنفی اصولیین، جیسے علاء الدین بخاری، نے انہی کتب کی شرح و توضیح پر اپنی محنت مرکوز رکھی، اور آج بھی یہ کتب حنفی مدارس میں اعلیٰ نصاب کا حصہ ہیں۔","المستصفیٰ فی علم الاصول امام غزالی کی وہ نمایاں تصنیف ہے جس نے طریقۂ متکلمین کو نہایت دقیق، منظم اور منطقی اسلوب میں مرتب کیا۔ اس کتاب کی خصوصیت اس کی فلسفیانہ گہرائی اور تنظیم ہے، خصوصاً حکمِ شرعی، مقاصدِ شریعت اور قیاس کے مباحث میں، اور اسی کتاب سے متاثر ہو کر بعد کے کئی اصولیین نے اپنی تصانیف مرتب کیں۔","امام شاطبی کی الموافقات فی اصول الشریعۃ مقاصدِ شریعت کے موضوع کی سب سے اہم اور جامع تصنیف سمجھی جاتی ہے، جس میں انہوں نے کلیاتِ خمسہ، ضروریات و حاجیات و تحسینیات، اور استقرائی طریقۂ کار کو نہایت گہرائی سے بیان کیا۔ یہ کتاب معاصر مقاصدی فقہ کی بنیاد سمجھی جاتی ہے، اور بیسویں صدی میں اس کے دوبارہ احیاء نے مقاصدِ شریعت کے علم کو نئی زندگی دی۔"],"definitions":[],"originalNumber":12},{"number":13,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":5,"chapter_title":"حکم شرعی کا بنیادی تصور","question":"حکمِ شرعی کی جامع تعریف کیا ہے، اور اس کے بنیادی اجزا کون سے ہیں؟","answer":["حکمِ شرعی میں طلبِ جازم اور دلیلِ قطعی کو خلط نہیں کرنا چاہیے۔ طلبِ جازم کا مطلب کسی فعل کے کرنے یا چھوڑنے کا لازم مطالبہ ہے؛ یہ لازم مطالبہ بعض صورتوں میں ظنی دلیل سے بھی ثابت ہوسکتا ہے۔ وجوب و حرمت مطالبے کی شدت بتاتے ہیں، جبکہ قطعیت و ظنیت دلیل کا درجہ بتاتی ہیں۔ حکم، حاکم، محکوم فیہ اور محکوم علیہ اس بحث کے اہم عنوانات ہیں؛ انہیں ایک ہی نوع کے تین ارکان کہنا پوری بحث کو مختصر کردیتا ہے۔","حکمِ شرعی کو جمہور اصولیین اللہ تعالیٰ کا وہ خطاب کہتے ہیں جو مکلف کے افعال سے طلب، اختیار یا وضع کے لحاظ سے متعلق ہو۔ بعض حنفی تعبیرات میں حکم اس خطاب کا اثر ہے؛ مثلاً نماز پڑھنے کا فرمان دلیل ہے اور اس سے ثابت وجوب حکم۔ اقتضاء لازم یا غیر لازم مطالبہ، تخییر کرنے اور چھوڑنے کی اجازت، اور وضع سبب و شرط وغیرہ کی تعیین ہے۔ حاکم حقیقی اللہ تعالیٰ ہے؛ رسول اللہ ﷺ اس کے حکم کے مبلغ اور مجاز شارح ہیں۔","حسن و قبح کی بحث میں عقلی پہچان، شرعی الزام اور اخروی مؤاخذہ الگ سوال ہیں۔ عقل بعض فوائد اور نقصانات پہچان سکتی ہے، مگر اس سے ہر عمل کا شرعی حکم اور ثواب و عذاب خودبخود متعین نہیں ہوتا۔ اشعری، ماتریدی اور معتزلی مناہج کی تفصیلات مختلف ہیں؛ سب کو ایک ہی مختصر موقف میں جمع کرنا مناسب نہیں۔ انٹرویو میں یہ فرق بیان کرنا بنیادی فہم ظاہر کرتا ہے۔"],"definitions":[{"studyQuestion":13,"term":"حکمِ شرعی: مکلّف کے فعل کی صفت","arabic":"الْأُمُورُ الْمَذْكُورَةُ مِنْ الْوَاجِبِ وَالْحَرَامِ وَغَيْرِهِمَا ... مِنْ صِفَاتِ فِعْلِ الْمُكَلَّفِ خَاصَّةً","translation":"واجب، حرام وغیرہ احکام در حقیقت مکلّف کے فعل کی صفات ہیں۔","explanation":"تلویح بتاتی ہے کہ احکام کی یہ اقسام فعل اور ترک دونوں کے لحاظ سے بارہ بنتی ہیں؛ کبھی ترک پر بھی یہ صفت بولی جاتی ہے، جیسے حرام کا ترک واجب ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"أقسام الأحكام","url":"https://shamela.ws/book/9508/17"},"kind":"definition","originalStudyQuestion":13}],"originalNumber":13},{"number":14,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":5,"chapter_title":"حکم شرعی کا بنیادی تصور","question":"حکمِ تکلیفی اور حکمِ وضعی میں بنیادی فرق کیا ہے؟","answer":["حکمِ تکلیفی عمل کے کرنے، چھوڑنے یا اختیار کا مطالبہ بیان کرتا ہے؛ حکمِ وضعی وہ شرعی تعلق بتاتا ہے جس سے حکم کا سبب، شرط یا مانع متعین ہو۔ دونوں کا دائرہ مکمل طور پر یکساں نہیں۔ بچے سے کسی کا مال تلف ہوجائے تو اسے بالغ کی طرح گناہ کا مکلف نہیں کہا جائے گا، مگر مالی ضمان ثابت ہوسکتا ہے۔ اس مثال سے معلوم ہوتا ہے کہ تکلیفی مؤاخذہ نہ ہونے کا مطلب تمام قانونی آثار کا ختم ہونا نہیں۔","حکم تکلیفی مکلف کے عمل سے براہِ راست طلب یا اختیار کے انداز میں متعلق ہوتا ہے۔ وہ بتاتا ہے کہ کوئی کام کرنا لازم، پسندیدہ، جائز، ناپسندیدہ یا ممنوع ہے۔ اس کی معروف اقسام وجوب، ندب، اباحت، کراہت اور حرمت ہیں۔","حکم وضعی کسی چیز کو دوسرے حکم کے وجود، نفاذ یا زوال سے جوڑتا ہے۔ شارع کسی وصف کو سبب، شرط یا مانع قرار دیتا ہے؛ یا عمل کی صحت، بطلان، رخصت اور عزیمت کا بیان کرتا ہے۔ مثلاً سورج ڈھلنا ظہر کی نماز کے وجوب کا سبب، وضو نماز کی صحت کی شرط اور حیض نماز کی ادائیگی کا مانع ہے۔","تکلیفی حکم کسی کام کا مطالبہ یا اختیار ہے، جبکہ وضعی حکم ایک چیز کو کسی حکم کا سبب، شرط، مانع یا اس نوع کا شرعی رابطہ قرار دیتا ہے۔","دونوں ایک دوسرے سے کٹے ہوئے نہیں۔ وضعی حکم وہ قانونی ساخت مہیا کرتا ہے جس کے اندر تکلیفی حکم نافذ ہوتا ہے۔ وقت آنے سے وجوب متوجہ ہوتا ہے، شرط پوری ہونے سے عمل درست ہوتا ہے اور مانع پائے جانے سے حکم رک جاتا ہے۔ اسی تعلق کو سمجھنے سے شریعت کی عملی تنظیم واضح ہوتی ہے۔","صحت کا تعلق مطلوب شرعی اثر کے معتبر طور پر قائم ہونے سے ہے۔ حنفی معاملات میں باطل عموماً اصل انعقاد کی خرابی اور فاسد وصف یا شرط کی خرابی کو ظاہر کرتا ہے؛ بعض آثار میں دونوں کا فرق ہوتا ہے۔ عبادات میں یہ امتیاز اسی انداز سے جاری نہیں ہوتا اور جمہور بھی فاسد و باطل کو عموماً مترادف برتتے ہیں۔ کسی خاص عقد کی مثال میں اس باب کا حکم دیکھنا ضروری ہے۔"],"definitions":[],"originalNumber":14},{"number":15,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":6,"chapter_title":"حکم تکلیفی","question":"فرض، واجب، سنت، مندوب، مباح، مکروہ اور حرام کی درجہ بندی میں فقہی مذاہب کے ہاں کیا اہم فرق پایا جاتا ہے؟","answer":["جمہور کے ہاں فرض و واجب عمومی طور پر مترادف ہیں؛ احناف دلیل کے درجے کی بنیاد پر فرق کرتے ہیں۔ مکروہِ تحریمی سے اجتناب حنفی فقہ میں لازم ہے، جبکہ مکروہِ تنزیہی کا ترک پسندیدہ ہے۔ مندوب کے تحت سنت اور مستحب جیسے عنوانات آتے ہیں، مگر سنتِ مؤکدہ کے مسلسل ترک کا حکم ہر معمولی مستحب کے ترک جیسا نہیں۔ انکارِ فرض کا اعتقادی حکم بھی علم، ثبوت اور دیگر شرائط کے بغیر کسی فرد پر فوراً نہیں لگایا جاتا۔","جمہور اصولیین کے نزدیک حکمِ تکلیفی کی پانچ بنیادی اقسام ہیں: وجوب، ندب (استحباب)، حرمت، کراہت اور اباحت۔ حنفی مکتب ان میں فرض اور واجب کے فرق کی بنا پر، اور مکروہِ تحریمی و تنزیہی کے فرق کی بنا پر، اس تعداد کو سات تک بڑھا دیتا ہے: فرض، واجب، مندوب، حرام، مکروہِ تحریمی، مکروہِ تنزیہی اور مباح۔ یہ درجہ بندی حکم کی شدت اور اس کے ترک یا فعل پر مرتب ہونے والے شرعی نتائج کے اعتبار سے کی جاتی ہے۔","عام اصولی مفہوم میں فرض یا واجب وہ فعل ہے جس کے کرنے کا شارع نے لازمی مطالبہ کیا ہو۔ اسے ادا کرنے والا اطاعت کی وجہ سے اجر پاتا ہے، جبکہ بلاعذر ترک کرنے والا گناہ گار اور مؤاخذے کا مستحق ہوتا ہے۔","واجب وہ کام ہے جس کے کرنے کا شارع نے قطعی اور لازم مطالبہ کیا ہو۔ جمہور اصولیین فرض اور واجب کو مترادف سمجھتے ہیں۔ نماز، رمضان کے روزے اور زکوٰۃ کو دونوں ناموں سے تعبیر کیا جاسکتا ہے۔","احناف کے نزدیک فرض وہ لازم عمل ہے جو قطعی دلیل سے ثابت ہو، جبکہ واجب وہ لازم عمل ہے جو ظنی دلیل سے ثابت ہو۔","اس فرق کا مطلب یہ نہیں کہ حنفی اصطلاح میں واجب معمولی حکم ہے۔ واجب کا جان بوجھ کر ترک بھی گناہ ہے۔ فرق دلیل کے ثبوت یا دلالت کی قوت اور اس سے پیدا ہونے والے بعض اعتقادی و فقہی آثار میں ہے۔","مثلاً پانچ نمازیں فرض ہیں، جبکہ حنفی فقہ میں وتر کو واجب کہا جاتا ہے۔ یوں حکم کی عملی پابندی دونوں میں موجود ہے، مگر فرض کا درجہ اس کی قطعی دلیل کی وجہ سے زیادہ قوی ہے۔","جمہور مالکیہ، شافعیہ اور حنابلہ کے نزدیک فرض اور واجب اصولی طور پر مترادف ہیں۔ جو فعل لازم دلیل سے مطلوب ہو وہ فرض بھی ہے اور واجب بھی۔ بعض ابواب، خصوصاً حج میں، الفاظ کا استعمال فنی فرق کے ساتھ ہوسکتا ہے، مگر بنیادی حکم تکلیفی میں دونوں ایک درجے کو ظاہر کرتے ہیں۔","احناف دونوں میں دلیل کی قوت کے لحاظ سے فرق کرتے ہیں۔ فرض قطعی دلیل سے ثابت لازم عمل ہے، جبکہ واجب ظنی دلیل سے ثابت لازم عمل۔ قرآن کی قطعی دلالت یا متواتر سنت سے ثابت لازم حکم فرض ہوسکتا ہے؛ خبر واحد یا ظنی دلالت سے ثابت لازم حکم واجب کہلاتا ہے۔","عملی طور پر دونوں کی ادائیگی لازم اور بلاعذر ترک گناہ ہے۔ تاہم فرض کے انکار کا حکم اس کی قطعیت کی وجہ سے زیادہ شدید ہوسکتا ہے، جبکہ ظنی دلیل سے ثابت واجب کا انکار خود بخود کفر قرار نہیں پاتا۔ بعض عبادات میں فرض رہ جائے تو اصل عبادت باطل ہوتی ہے، جبکہ واجب کے ترک کی تلافی یا نقص کا حکم الگ ہوسکتا ہے۔","یہ اختلاف محض لفظی نہیں، کیونکہ اس کے اعتقادی، استدلالی اور بعض فروعی آثار ہیں۔ پھر بھی دونوں مناہج کا مشترک مقصد لازم شرعی مطالبے کی حفاظت ہے۔","واجب کی تقسیم کئی اعتبار سے ہوتی ہے: فرضِ عین ہر متعلق مکلف پر اور فرضِ کفایہ کافی افراد کے ادا کرنے سے دوسروں سے ساقط ہوتا ہے۔ معین واجب میں مطلوب فعل متعین اور مخیر واجب میں مقرر متبادلوں میں اختیار ہوتا ہے۔ مؤقت واجب کا وقت مقرر ہوتا ہے؛ موسع وقت میں ادائیگی کی گنجائش اور مضیق میں محدود مہلت ہوتی ہے۔ ان تقسیمات کو فرض و واجب کے حنفی فرق سے خلط نہ کریں۔","سنت، مندوب، مستحب اور نفل کے استعمال میں کتابوں اور مذاہب کے لحاظ سے تفصیل ہے۔ سنتِ مؤکدہ کو عام نفلی عمل کی طرح کم اہم کہنا درست نہیں۔ مکروہِ تحریمی حنفی اصطلاح میں ظنی دلیل سے ثابت لازم ترک کا حکم ہے، جبکہ مکروہِ تنزیہی غیر لازم ترک کی ترجیح ہے۔ حرام اور مکروہِ تحریمی دونوں سے اجتناب مطلوب ہے؛ ان کا فرق دلیل کے درجے اور بعض آثار میں ہے۔","اداء مقرر وقت میں مطلوب عمل پورا کرنا، قضاء وقت کے بعد فوت شدہ عمل کی شرعی تلافی، اور اعادہ ادا شدہ عمل کو متعلقہ خلل یا سبب سے دوبارہ کرنا ہے۔ ان کی دقیق حدبندی میں اصولی اصطلاحات مختلف ہوسکتی ہیں۔ قضاء لازم ہونے اور اس کے لیے نئی دلیل درکار ہونے کی بحث الگ ہے؛ محض لغوی معنی سے کسی فوت شدہ عبادت کا عملی حکم نہ نکالیں۔"],"definitions":[{"studyQuestion":15,"term":"الفرض","arabic":"ما ثبت بدليل قطعي لا شبهة فيه","translation":"جو ایسی قطعی دلیل سے ثابت ہو جس میں شبہ نہ ہو۔","explanation":"یہ اصول الشاشی کی حنفی اصطلاح ہے۔ لازم مطالبے کا وصف پورے سیاق سے معلوم ہوتا ہے؛ جمہور فرض و واجب کو عموماً مترادف رکھتے ہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث بيان معنى الفرض، ص 379","url":"https://shamela.ws/book/6302/159"},"kind":"definition","originalStudyQuestion":15},{"studyQuestion":15,"term":"الواجب","arabic":"ما ثبت بدليل فيه شبهة كالآية المؤولة والصحيح من الآحاد","translation":"جو ایسی دلیل سے ثابت ہو جس میں احتمال ہو، جیسے مؤول آیت اور صحیح خبرِ آحاد۔","explanation":"«شبہ» یہاں معتبر علمی احتمال ہے، بے حجتی نہیں۔ حنفی واجب عمل کے لحاظ سے لازم ہوتا ہے، مگر اس کا درجہ فرض کی قطعی دلیل سے الگ ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث بيان معنى الفرض، ص 379","url":"https://shamela.ws/book/6302/159"},"kind":"definition","originalStudyQuestion":15},{"studyQuestion":15,"term":"المندوب: سنت اور نفل کو شامل","arabic":"الْمُرَادُ بِالْمَنْدُوبِ مَا يَشْمَلُ السُّنَّةَ وَالنَّقْلَ","translation":"مندوب سے مراد وہ ہے جس میں سنت اور نفل دونوں شامل ہوں۔","explanation":"تلویح کے مطابق اسی وسعت سے احکام کے چھ درجات بنتے ہیں۔ حنفی اصطلاح میں سنت و نفل کا فرق بعد میں الگ سے بیان ہوتا ہے۔ (نسخے کے لفظ «النقل» سے مراد «النفل» ہے۔)","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"أقسام الأحكام","url":"https://shamela.ws/book/9508/17"},"kind":"definition","originalStudyQuestion":15}],"originalNumber":15},{"number":16,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":7,"chapter_title":"حکم وضعی","question":"سبب، شرط اور مانع میں کیا فرق ہے؟ مناسب فقہی مثالوں سے واضح کریں۔","answer":["سبب سے حکم کا تعلق اس وقت مؤثر ہوتا ہے جب متعلقہ شرائط پوری ہوں اور مانع نہ ہو۔ زکوٰۃ میں نصاب اور ملکیت کا سبب سے تعلق، اور بہت سے اموال میں حولانِ حول کی شرط، الگ پہچاننا چاہیے؛ ہر زکوٰۃ میں سال گزرنا لازم نہیں۔ مانع کی واضح مثال وراثت میں ایسا قتل ہے جو متعلقہ مذہب کے نزدیک مانعِ ارث ہو۔ قصاص میں والد کی حیثیت ایک اختلافی تفصیلی مسئلہ ہے، اسے تمام مذاہب کا یکساں حکم نہیں کہنا چاہیے۔","سبب وہ ظاہری اور منضبط وصف ہے جسے شارع نے کسی حکم کے وجود کی علامت قرار دیا ہو، اس طرح کہ اس کے پائے جانے سے حکم لازم آئے اور نہ پائے جانے سے حکم نہ ہو۔ مثال کے طور پر مالِ نصاب کا ایک سال تک مکمل ملکیت میں رہنا زکوٰۃ کے وجوب کا سبب ہے: جیسے ہی یہ شرط پوری ہو، زکوٰۃ واجب ہو جاتی ہے، اور اگر مال نصاب تک نہ پہنچے تو زکوٰۃ واجب نہیں ہوتی۔ سبب اور حکم کے مابین یہ تعلق شریعت نے خود متعین کیا ہے، عقل سے مستقل طور پر معلوم نہیں ہوتا۔","شرط وہ چیز ہے جس کا وجود کسی حکم کے قیام کے لیے لازمی ہو، مگر اس کا وجود بذاتِ خود حکم کے وقوع کی ضمانت نہیں دیتا، بلکہ حکم کے تحقق کے لیے دیگر عوامل بھی درکار ہوتے ہیں۔ مثال کے طور پر وضو نماز کی ایک شرط ہے: وضو کے بغیر نماز درست نہیں ہوتی، مگر محض وضو کر لینا نماز کے وجوب کا سبب نہیں بنتا۔ اسی طرح نکاح میں گواہوں کی موجودگی شرط ہے، مگر گواہوں کی موجودگی خود نکاح کے وقوع کی ضامن نہیں جب تک ایجاب و قبول نہ ہو۔","مانع وہ وصف ہے جس کی موجودگی سبب اور شرط کے مکمل ہونے کے باوجود حکم کے وقوع کو روک دیتی ہے۔ مثال کے طور پر باپ ہونا اصولاً بیٹے کے قتل کے بدلے قصاص کا سبب بننا چاہیے، مگر 'ابوت' (باپ ہونا) اسلامی فقہ میں قصاص کے وجوب میں مانع تصور کی جاتی ہے، یعنی باپ کو بیٹے کے قتل کے بدلے قصاص نہیں کیا جاتا، اگرچہ قتلِ عمد کے دیگر شرائط پوری ہو چکی ہوں۔ اسی طرح حیض نماز کے وجوب میں مانع ہے۔"],"definitions":[{"studyQuestion":16,"term":"السبب: حدّه في اصطلاح الشاشي","arabic":"فالسبب ما يكون طريقا إلى الشيء بواسطة","translation":"سبب وہ ہے جو کسی واسطے سے کسی چیز تک پہنچنے کا راستہ ہو۔","explanation":"یہ شاشی کی خاص اصطلاحی توضیح ہے۔ بعض اصولیین سبب کو حکم کی شرعی علامت کے معنی میں بیان کرتے ہیں؛ اس لیے مختلف کتابوں کی اصطلاحات کا محل ملحوظ رکھیے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل الحكم، ص 353","url":"https://shamela.ws/book/6302/148"},"kind":"definition","originalStudyQuestion":16}],"originalNumber":16},{"number":17,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":7,"chapter_title":"حکم وضعی","question":"عزیمت اور رخصت سے کیا مراد ہے، اور ان کا اطلاق کن حالات میں ہوتا ہے؟","answer":["عزیمت اور رخصت اصل حکم اور معتبر عذر کی بنیاد پر دی گئی سہولت کا تعلق واضح کرتی ہیں۔ رخصت ہمیشہ کم درجے کی نیکی نہیں؛ شدید خطرے میں جان بچانے کے لیے اس کا اختیار لازم بھی ہوسکتا ہے۔ حنفی فقہ میں سفر کی قصر کا حکم جمہور سے مختلف تفصیل رکھتا ہے، اس لیے تمام مثالوں کو یکساں اختیاری سہولت کہنا مناسب نہیں۔ رخصت کی نوعیت، عذر، مقدار اور باقی رہنے والے حکم کو الگ بیان کرنا چاہیے۔","اگرچہ رخصت اور عزیمت بنیادی طور پر حکمِ تکلیفی سے متعلق تصورات ہیں، مگر بعض اصولیین انہیں حکمِ وضعی کے ضمن میں بھی زیرِ بحث لاتے ہیں، کیونکہ رخصت کا سبب (جیسے سفر یا بیماری) دراصل ایک وضعی سبب ہے جو اصل حکم میں تخفیف پیدا کرتا ہے۔ اس اعتبار سے سفر یا بیماری کو ایک 'وضعی سبب' سمجھا جا سکتا ہے جو حکمِ تکلیفی کی نوعیت میں تبدیلی پیدا کرتا ہے، اور یہی وہ نکتہ ہے جو ان دونوں تصورات (تکلیفی و وضعی) کے مابین باہمی ربط کو ظاہر کرتا ہے۔","عزیمت وہ اصل عمومی حکم ہے جو عام حالات میں مکلفین کے لیے مقرر کیا گیا ہو۔ نماز کا قیام، رمضان کا روزہ اور حرام چیزوں سے اجتناب اپنی اصل صورت میں عزیمت کے احکام ہیں۔","عزیمت وہ اصل شرعی حکم ہے جو کسی مؤثر عذر کے بغیر عام حالت میں ثابت ہو۔","رخصت وہ مشروع سہولت ہے جو کسی معتبر عذر، ضرورت یا مشقت کی وجہ سے اصل حکم کے مقابلے میں دی جاتی ہے، جبکہ اصل حکم کا سبب اپنی جگہ موجود رہتا ہے۔ سفر میں نماز قصر کرنا، بیماری میں بیٹھ کر نماز پڑھنا اور اضطرار میں بقدر ضرورت ممنوع غذا استعمال کرنا اس کی مثالیں ہیں۔","رخصت وہ حکم ہے جو عذر کی بنا پر مشروع ہو، حالانکہ اصل حکم کا سبب باقی ہو۔","رخصت شریعت سے نکلنے کا راستہ نہیں؛ وہ خود شریعت کا حکم ہے۔ کبھی عزیمت پر عمل افضل ہوتا ہے، کبھی رخصت اختیار کرنا بہتر، اور کبھی جان یا ضروری حق کے تحفظ کے لیے رخصت پر عمل واجب ہوجاتا ہے۔","ہر دشواری رخصت کا سبب نہیں۔ رخصت کے لیے ایسی معتبر مشقت، بیماری، سفر، اکراہ یا اضطرار درکار ہوتا ہے جسے شارع نے حکم میں تخفیف کے لیے مؤثر مانا ہو۔ معمول کی وہ محنت جو عبادت کی فطرت کا حصہ ہے، عموماً رخصت پیدا نہیں کرتی۔","قرآنی اصول: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ (البقرۃ: 185)","اللہ تمہارے لیے آسانی چاہتا ہے، تنگی نہیں چاہتا۔","دوسرا اصول تناسب ہے۔ رخصت اتنی ہی ہوگی جتنی عذر یا ضرورت کا تقاضا ہو۔ فقہی قاعدہ ہے: «الضَّرُورَاتُ تُبِيحُ الْمَحْظُورَاتِ»؛ ضرورت ممنوع چیز کو بقدر ضرورت جائز کرتی ہے۔ ساتھ ہی قاعدہ ہے: «الضَّرُورَةُ تُقَدَّرُ بِقَدَرِهَا»؛ ضرورت اپنی حد کے مطابق رکھی جائے گی۔","تیسرا اصول یہ ہے کہ عذر واقعی یا غالب گمان سے ثابت ہو۔ محض وہم، سہولت پسندی یا خواہش سے عزیمت ترک نہیں کی جاسکتی۔ اگر کم ضرر والا جائز راستہ موجود ہو تو زیادہ ممنوع راستہ اختیار نہیں کیا جائے گا۔","عذر ختم ہوجائے تو عام طور پر اصل حکم واپس آجاتا ہے۔ یوں رخصت آسانی کا منضبط شرعی نظام ہے، نہ کہ ذمہ داری سے بے قید آزادی۔"],"definitions":[{"studyQuestion":17,"term":"العزيمة","arabic":"عبارة عما لزمنا من الأحكام ابتداء","translation":"وہ احکام جو ابتدا سے ہمارے لیے لازم کیے گئے ہوں۔","explanation":"عزیمت اصل مشروع حکم ہے۔ رخصت معتبر عذر سے تخفیف ہے؛ عزیمت کو ہمیشہ رخصت سے افضل کہنا ہر صورت میں درست نہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل العزيمة، ص 383","url":"https://shamela.ws/book/6302/161"},"kind":"definition","originalStudyQuestion":17},{"studyQuestion":17,"term":"الرخصة","arabic":"صرف الأمر من عسر إلى يسر بواسطة عذر في المكلف","translation":"مکلف کے عذر کی وجہ سے حکم کو دشواری سے آسانی کی طرف منتقل کرنا۔","explanation":"رخصت شرع کی مقرر تخفیف ہے۔ عذر، مقدار اور مدت کی حد رہتی ہے؛ ہر معمولی مشقت سے ہر ممنوع عمل جائز نہیں ہوجاتا۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث بيان الرخصة، ص 385","url":"https://shamela.ws/book/6302/162"},"kind":"definition","originalStudyQuestion":17}],"originalNumber":17},{"number":18,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":9,"chapter_title":"اہلیت","question":"اہلیتِ وجوب اور اہلیتِ اداء میں کیا فرق ہے؟","answer":["اہلیتِ وجوب حق اور ذمہ داری کا حامل بننے کی صلاحیت ہے؛ اہلیتِ اداء اپنے قول و فعل سے معتبر شرعی اثر پیدا کرنے کی صلاحیت ہے۔ جنین کے لیے بعض حقوق، مثلاً مشروط وراثت، ثابت ہوسکتے ہیں؛ اسے ناقص اہلیتِ وجوب کہتے ہیں۔ زندہ پیدائش کے بعد اہلیتِ وجوب کامل ہوتی ہے۔ غیر ممیز، ممیز اور بالغ عاقل کی اہلیتِ اداء مختلف ہے، اور مالی تصرف میں رشد و سفہ کے احکام الگ تفصیل چاہتے ہیں۔","اہلیت وجوب انسان کی وہ صلاحیت ہے جس کی بنا پر اس کے لیے حقوق اور اس پر ذمہ داریاں ثابت ہوسکیں۔ اس کی بنیاد انسانی زندگی اور «ذمہ» ہے۔ ذمہ سے مراد وہ اعتباری قانونی وصف ہے جو انسان کو حقوق و واجبات کا حامل بناتا ہے۔","اہلیت وجوب انسان میں حقوق پانے اور ذمہ داریاں قبول کرنے کی صلاحیت ہے۔","اہلیت ادا وہ صلاحیت ہے جس سے انسان کے قول اور فعل کو شرعاً معتبر اثر حاصل ہو۔ اس کی بنیاد عقل، تمییز، فہم اور اختیار ہے۔","مثال کے طور پر بچے کے لیے وراثت ثابت ہونا اہلیت وجوب ہے۔ اسی بچے کا بڑا ہوکر اپنے مال کی صحیح بیع کرنا اہلیت ادا ہے۔ پہلا سوال حق رکھنے کا ہے، دوسرا اپنے ارادے سے معتبر تصرف کرنے کا۔","دونوں کو الگ سمجھنا ضروری ہے۔ کوئی شخص حق کا مالک ہوسکتا ہے مگر خود اس حق میں تصرف کا اہل نہ ہو۔ ایسی صورت میں ولی یا سرپرست اس کے مفاد میں کام کرتا ہے۔","اہلیتِ وجوب حقوق و ذمہ داریوں کا محل بننے کی صلاحیت، اور اہلیتِ اداء معتبر قول و فعل صادر کرنے کی صلاحیت ہے۔ جنین کی ناقص اہلیتِ وجوب بعض حقوق، جیسے وراثت، کے لیے ہے، جس کی تکمیل زندہ ولادت وغیرہ کی شرائط سے ہوتی ہے۔ نابالغ ممیز کے تصرفات میں نفعِ محض، ضررِ محض اور دونوں کے احتمال کی تقسیم اہم ہے؛ ولی کی اجازت بھی ہر قسم کو یکساں درست نہیں کرتی۔"],"definitions":[],"originalNumber":18},{"number":19,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":10,"chapter_title":"عوارض اہلیت","question":"عوارضِ اہلیت کیا ہیں، اور وہ مکلف کے احکام کو کس طرح متاثر کرتے ہیں؟","answer":["ہر عارض تمام حقوق اور ذمہ داریاں ختم نہیں کرتا۔ نیند نماز کے وقت فعل کی قدرت کو متاثر کرتی ہے، لیکن بیداری کے بعد ادائیگی کی ذمہ داری باقی ہوسکتی ہے۔ نسیان بعض عبادات میں عذر ہے، جبکہ کسی کا مال تلف کرنے کا ضمان محض بھول سے لازماً ساقط نہیں ہوتا۔ اکراہ کی معروف حنفی تقسیم میں اس کی بحث عوارضِ مکتسبہ میں آتی ہے، مگر اس کا مطلب یہ نہیں کہ متاثر شخص نے دباؤ اپنی مرضی سے پیدا کیا ہے۔","عوارضِ اہلیت وہ حالات ہیں جو اہلیت یا اس کے شرعی آثار پر اثر انداز ہوتے ہیں۔ ہر عارض لازماً ایک ہی درجے کی کمی پیدا نہیں کرتا۔ معروف حنفی تقسیم میں سماوی عوارض، جیسے صغر، جنون اور نیند، اور مکتسب عوارض، جیسے جہالت، خطا، نشہ اور اکراہ، بیان ہوتے ہیں۔ مکتسب کا مطلب ہر صورت میں متاثر شخص کا رضاکارانہ انتخاب نہیں؛ اکراہ میں دوسرے شخص کا فعل اور دباؤ بنیادی ہوتا ہے۔","عوارض سماوی وہ حالات ہیں جو عموماً انسان کے اختیار اور کسب کے بغیر پیدا ہوتے ہیں۔ صغر، جنون، عته، نسیان، نیند، بے ہوشی، بیماری، حیض، نفاس اور موت اس کی معروف مثالیں ہیں۔ انسان ان کے پیدا ہونے کا براہ راست ذمہ دار نہیں ہوتا۔","اس فرق کا اثر مؤاخذے پر پڑتا ہے۔ غیر اختیاری عارض میں گناہ عموماً ساقط یا کم ہوتا ہے۔ کسبی عارض میں دیکھا جاتا ہے کہ شخص نے خود سبب اختیار کیا تھا یا نہیں۔ رضاکارانہ نشہ اور دوا سے غیر ارادی بے ہوشی کا حکم یکساں نہیں۔","پھر بھی سماوی و کسبی تقسیم اکیلی کافی نہیں۔ ہر مسئلے میں ارادہ، قدرت، دوسروں کے حقوق اور وضعی اثر الگ جانچے جاتے ہیں۔"],"definitions":[],"originalNumber":19},{"number":20,"unit_id":2,"unit_name":"یونٹ دوم","unit_title":"حکم شرعی اور اہلیت","chapter_number":8,"chapter_title":"محکوم فیہ اور تکلیف","question":"محکومٌ علیہ اور محکومٌ فیہ سے کیا مراد ہے، اور تکلیف کے درست اطلاق کے لیے کن شرائط کا لحاظ ضروری ہے؟","answer":["محکوم علیہ وہ شخص ہے جس سے شرعی خطاب متعلق ہے اور محکوم فیہ وہ فعل ہے جس کا حکم بیان ہوتا ہے۔ تکلیف میں عقل، بلوغ، فہم اور قدرت اہم ہیں، مگر تمام وضعی آثار انہی شرائط کے تابع نہیں۔ بچہ اپنے مال کا مالک ہوسکتا ہے اور اس کے مال سے بعض مالی ذمہ داریاں پوری کی جاسکتی ہیں۔ جہالت کا عذر بھی ہر جگہ یکساں نہیں؛ حکم کی نوعیت، رسائی اور شخص کے حالات دیکھے جاتے ہیں۔","محکومٌ علیہ، یعنی مکلف، کی بنیادی شرط یہ ہے کہ وہ 'اہلِ خطاب' ہو، یعنی اس میں سمجھنے، فہم اور شرعی خطاب کا مکلف بننے کی صلاحیت پائی جائے۔ اسی لیے بچہ، مجنون اور بے ہوش شخص، جن میں عقل و فہم کی صلاحیت مکمل یا وقتی طور پر معدوم ہو، اصولی طور پر تکلیف کے دائرے سے خارج سمجھے جاتے ہیں، جیسا کہ حدیثِ نبوی میں تین اشخاص سے قلم اٹھا لینے کا ذکر ملتا ہے: سویا ہوا شخص جب تک بیدار نہ ہو، بچہ جب تک بالغ نہ ہو، اور مجنون جب تک عقل واپس نہ آئے۔","محکومٌ فیہ سے مراد وہ فعل ہے جس سے حکمِ شرعی متعلق ہوتا ہے، جیسے نماز پڑھنا یا سود سے اجتناب کرنا۔ اس کی بنیادی شرائط یہ ہیں کہ وہ فعل مکلف کے علم میں ہو (یعنی حکم اس تک پہنچا ہو یا پہنچنا ممکن ہو)، وہ فعل انسانی قدرت کے دائرے میں ہو (یعنی ناممکن الوقوع نہ ہو)، اور اس فعل کا نسبتِ اختیار مکلف کی طرف صحیح ہو۔ ان شرائط کے بغیر کسی فعل پر شرعی تکلیف عائد نہیں کی جا سکتی، کیونکہ تکلیف بالمحال (ناممکن کا مکلف بنانا) اصولی طور پر باطل ہے۔"],"definitions":[],"originalNumber":20},{"number":21,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":11,"chapter_title":"دلیل شرعی مفہوم اور اقسام","question":"مصادرِ فقہ اور ادلۂ شرعیہ سے کیا مراد ہے، اور جمہور کے نزدیک ان کی بنیادی ترتیب کیا ہے؟","answer":["اہلِ سنت کے چار فقہی مذاہب قرآن، سنت، اجماع اور قیاس کی اصل حجیت تسلیم کرتے ہیں، اگرچہ ہر دلیل کی شرائط میں فرق ہوسکتا ہے۔ قرآن اور سنت بنیادی وحی پر مبنی مصادر ہیں، جبکہ اجماع اور قیاس کی حجیت بھی شرعی بنیاد رکھتی ہے۔ ترتیب کا مطلب سنت کو غیر اہم بنانا نہیں؛ ثابت سنت قرآن کی تبیین کرتی ہے۔ مختلف فیہ ادلہ، جیسے استحسان اور عرف، بھی نصوص سے آزاد خود مختار تشریع نہیں۔","مصادرِ شریعت سے مراد وہ بنیادی سرچشمے ہیں جن سے شرعی احکام اخذ کیے جاتے ہیں۔ ان مصادر کے ذریعے مجتہد کسی فعل کے شرعی حکم تک رسائی حاصل کرتا ہے، اور یہی مصادر فقہ اور اصولِ فقہ کا سب سے بنیادی موضوع سمجھے جاتے ہیں۔ مصادرِ شریعت کو 'ادلۂ شرعیہ' بھی کہا جاتا ہے، اور اصولی کتب میں ان کی حجیت، ترتیب اور استعمال کے طریقے پر تفصیلی بحث کی جاتی ہے۔","دلیل شرعی اس معتبر بنیاد کو کہتے ہیں جس سے صحیح اصولی غور کے ذریعے کسی شرعی حکم تک پہنچا جائے۔ دلیل کبھی براہ راست نص ہوتی ہے، جیسے قرآن و سنت، اور کبھی ایسا اصولی ذریعہ جس کی حجیت نصوص سے ثابت ہو، جیسے اجماع اور صحیح قیاس۔","دلیل وہ چیز ہے جس میں درست غور سے کسی علمی مطلوب تک پہنچا جاسکے۔ جب مطلوب شرعی حکم ہو تو اسے دلیل شرعی کہا جاتا ہے۔","«صحیح نظر» کی قید اہم ہے۔ محض کسی آیت یا حدیث کا حوالہ دے دینا کافی نہیں۔ ثبوت، دلالت، سیاق، تخصیص، تقیید، نسخ اور دوسری متعلقہ نصوص کا جائزہ ضروری ہے۔ غلط استدلال معتبر دلیل کو بھی غلط نتیجے کے لیے استعمال کرسکتا ہے۔","مثلاً ﴿وَأَقِيمُوا الصَّلَاةَ﴾ نماز کے حکم کی دلیل ہے۔ صیغۂ امر، دوسری آیات اور سنت سے نماز کا وجوب معلوم ہوتا ہے۔ اسی طرح خمر کی حرمت سے نشہ آور نئی چیز کا حکم قیاس کے ذریعے اخذ کیا جاتا ہے۔","دلیل شرعی کا مقصد رائے کو وحی کے تابع اور اجتہاد کو منضبط کرنا ہے۔ فقیہ یہ نہیں دیکھتا کہ نتیجہ اسے پسند ہے یا نہیں؛ وہ پوچھتا ہے کہ معتبر مصدر، صحیح دلالت اور اصولی طریقہ اس نتیجے کی تائید کرتے ہیں یا نہیں۔","§QUOTE§فإن أصول الفقه أربعة كتاب الله تعالى وسنة رسوله وإجماع الأمة والقياس","مفہوم: کتاب اللہ، سنتِ رسول، اجماع اور قیاس بنیادی دلائل ہیں؛ یہاں اصول سے مراد مصادر ہیں۔  حوالہ: اصول الشاشی، افتتاحِ کتاب: چار بنیادی اصول۔"],"definitions":[{"studyQuestion":21,"term":"الأصول الأربعة","arabic":"فإن أصول الفقه أربعة: كتاب الله تعالى وسنة رسوله وإجماع الأمة والقياس","translation":"فقہ کے چار بنیادی اصول ہیں: کتاب اللہ، رسول کی سنت، امت کا اجماع اور قیاس۔","explanation":"یہ کتاب کے آغاز کی اصل عبارت ہے، اصطلاح «علمِ اصول» کی مکمل تعریف نہیں۔ اس سے مرکزی مصادر کا تعارف ملتا ہے؛ مختلف فیہ دلائل کی بحث الگ شامل ہوتی ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث كون أصول الفقه أربعة، ص 13","url":"https://shamela.ws/book/6302/1"},"kind":"passage","originalStudyQuestion":21}],"originalNumber":21},{"number":22,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":12,"chapter_title":"قرآن مجید بحیثیت مصدر شریعت","question":"قرآن مجید کو بنیادی اور قطعی الثبوت مصدر کیوں کہا جاتا ہے، اور قطعیتِ ثبوت و قطعیتِ دلالت میں کیا فرق ہے؟","answer":["قرآن قطعی الثبوت ہے، مگر ہر آیت سے ہر جزوی مسئلے کا اخذ کردہ حکم قطعی نہیں ہوتا۔ میراث میں مقرر حصہ واضح دلالت رکھتا ہے، جبکہ مشترک لفظ کی تعبیر میں معتبر احتمال ہوسکتا ہے۔ کسی مخصوص معنی کی قطعیت طے کرتے وقت دوسری نصوص اور سیاق بھی دیکھنا ضروری ہے۔ قطعیتِ ثبوت، قطعیتِ دلالت اور فقہی تطبیق الگ مراحل ہیں؛ ایک مرحلے کی قطعیت کو دوسرے پر بلا تحقیق منتقل نہیں کیا جاسکتا۔","قرآن مجید کو پہلا اور اہم ترین مصدر اس لیے سمجھا جاتا ہے کہ یہ براہِ راست اللہ تعالیٰ کا کلام ہے، جو نبی کریم ﷺ پر بذریعہ وحی نازل ہوا اور تواتر کے ساتھ نسل در نسل منتقل ہوا، جس میں کسی قسم کے شک و شبہ کی گنجائش نہیں۔ اس کی قطعیتِ ثبوت (یعنی یہ یقینی طور پر اللہ کا کلام ہے) اسے دیگر تمام مصادر پر فوقیت دیتی ہے۔ اسی لیے اصولیین نے قرآن کو 'اصل الاصول' یعنی تمام مصادر کی اصل اور بنیاد قرار دیا ہے۔","قطعیتِ ثبوت کا تعلق نص کے متن کے ثابت ہونے سے ہے، یعنی کیا یہ الفاظ واقعی اللہ کے کلام کا حصہ ہیں۔ قطعیتِ دلالت کا تعلق نص کے معنی سے ہے، یعنی کیا اس آیت کا مفہوم بالکل واضح اور غیر مبہم ہے یا اس میں تاویل کی گنجائش ہے۔ قرآن کی تمام آیات قطعی الثبوت ہیں، مگر ان کی دلالت میں فرق پایا جاتا ہے: بعض آیات قطعی الدلالت ہیں (جیسے میراث کے مقررہ حصے) جبکہ بعض ظنی الدلالت ہیں (جیسے وہ الفاظ جو ایک سے زیادہ معنی رکھتے ہوں)۔"],"definitions":[],"originalNumber":22},{"number":23,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":13,"chapter_title":"سنت نبوی بحیثیت مصدر شریعت","question":"سنت کی تشریعی حیثیت کیا ہے، اور قولی، فعلی اور تقریری سنت کی فقہی دلالت میں کیا فرق ہے؟","answer":["قولی سنت میں الفاظ اور قرائن، فعلی سنت میں عمل کی نوعیت، اور تقریری سنت میں علم و اقرار کی شرائط دیکھی جاتی ہیں۔ رسول اللہ ﷺ کا ہر فعل بذات خود فرض نہیں؛ عمل تشریعی بیان، مستحب طریقہ، طبعی عادت یا آپ کی خصوصیت ہوسکتا ہے۔ تقریر بھی تب معتبر ہے جب آپ ﷺ کو فعل کا علم ہو اور اقرار کا محل ثابت ہو۔ اس لیے سنت کی حجیت کے ساتھ اس کی خاص دلالت الگ متعین کرنا ضروری ہے۔","سنتِ قولیہ سے مراد نبی کریم ﷺ کے وہ ارشادات ہیں جو آپ ﷺ نے زبانی ادا فرمائے، جیسے 'انما الاعمال بالنیات'۔ سنتِ فعلیہ سے مراد نبی کریم ﷺ کے وہ عملی افعال ہیں جو آپ ﷺ نے خود بجا لائے، جیسے نماز کی مخصوص کیفیت۔ سنتِ تقریریہ سے مراد وہ افعال یا اقوال ہیں جو کسی صحابی نے آپ ﷺ کی موجودگی میں انجام دیے اور آپ ﷺ نے خاموشی اختیار فرمائی یا تحسین کی، جس سے اس فعل کا جواز ثابت ہوتا ہے۔","قرآن مجید نے رسول اللہ ﷺ کی اطاعت کو اللہ کی اطاعت سے جوڑا، آپ کے فیصلے کو قبول کرنے کا حکم دیا اور آپ کو قرآن کی تشریح کا منصب عطا کیا۔ یہ آیات ثابت کرتی ہیں کہ سنت محض تاریخی سوانح نہیں، شرعی حجت ہے۔","اللہ تعالیٰ فرماتا ہے: ﴿مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ﴾ (النساء: 80)","جس نے رسول کی اطاعت کی، اس نے اللہ کی اطاعت کی۔ رسول کی اطاعت کو مستقل الفاظ میں بیان کرنا بتاتا ہے کہ آپ کی تشریعی رہنمائی واجب الاتباع ہے۔","ایک اور ارشاد ہے: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا﴾ (الحشر: 7)، یعنی رسول جو کچھ تمہیں دیں اسے لے لو، اور جس سے روکیں اس سے رک جاؤ۔ اگرچہ آیت کا فوری سیاق مالِ فے سے متعلق ہے، اس کے الفاظ اطاعت رسول کا عمومی اصول بھی بیان کرتے ہیں۔","قرآن نے فرمایا: ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾ (النحل: 44)۔ نماز، زکوٰۃ اور حج جیسے احکام کی عملی شکل اسی نبوی تبیین سے معلوم ہوئی۔","پس سنت کی حجیت قرآن کے مقابل نہیں، خود قرآن کے حکم سے ہے۔ قرآن کو مان کر رسول ﷺ کے ثابت تشریعی بیان کو اصولاً رد کرنا قرآنی نظام اطاعت کو ادھورا کردیتا ہے۔ البتہ ہر منسوب روایت کی صحت اور دلالت کی تحقیق الگ علمی ذمہ داری ہے۔"],"definitions":[],"originalNumber":23},{"number":24,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":13,"chapter_title":"سنت نبوی بحیثیت مصدر شریعت","question":"خبرِ واحد سے فقہی استدلال کے بارے میں اصولیین اور فقہی مذاہب کے اہم مناہج کیا ہیں؟","answer":["معتبر خبرِ واحد عملی احکام میں حجت ہے؛ بحث اس کی صحت، حاصل ہونے والے علم اور دوسری ادلہ سے تعلق کی ہے۔ شافعی منہج سند و روایت کی شرائط پوری ہونے پر اسے مضبوط حجت مانتا ہے؛ حنفی اصول میں کتاب، مشہور سنت اور عمومِ بلویٰ سے نسبت کی تفصیلات نمایاں ہیں۔ مالکیہ بعض مسائل میں عملِ اہلِ مدینہ کا وزن دیکھتے ہیں۔ ان اختلافات کو کسی مذہب کے مطلق ردِ حدیث سے تعبیر کرنا غلط ہے۔","راویوں کی تعداد کے اعتبار سے سنت کو دو بنیادی اقسام میں تقسیم کیا جاتا ہے: خبرِ متواتر اور خبرِ آحاد۔ خبرِ متواتر وہ روایت ہے جسے اتنی بڑی تعداد میں راویوں نے، جن کا جھوٹ پر اتفاق عقلاً ناممکن ہو، نقل کیا ہو۔ خبرِ آحاد وہ روایت ہے جسے اس معیار سے کم تعداد میں راویوں نے نقل کیا ہو، اور اسے مزید مشہور اور آحاد کی ذیلی اقسام میں تقسیم کیا جاتا ہے۔","متواتر روایت وہ ہے جسے ہر طبقے میں اتنی بڑی تعداد نے نقل کیا ہو کہ ان سب کا جھوٹ پر متفق ہونا عادتاً ناممکن ہو، اور خبر حسی مشاہدے یا سماع پر مبنی ہو۔ یہ لفظی بھی ہوسکتی ہے اور معنوی بھی۔","خبر واحد اصولی اصطلاح میں وہ روایت ہے جو تواتر کی حد تک نہ پہنچے، خواہ اسے ایک، دو یا چند راوی نقل کریں۔ «واحد» کا مطلب لازماً صرف ایک راوی نہیں؛ اصل معیار یہ ہے کہ نقل متواتر نہ ہو۔","مشہور کی تعریف میں مناہج مختلف ہیں۔ احناف کے نزدیک مشہور وہ خبر ہے جو ابتدا میں خبر واحد تھی، پھر دوسری یا تیسری نسل میں وسیع قبول و نقل حاصل کرگئی۔ اسے وہ خبر واحد سے قوی اور متواتر سے کم درجہ دیتے ہیں۔","جمہور محدثین کے ہاں «مشہور» عموماً اس روایت کو کہتے ہیں جس کے ہر طبقے میں کم از کم تین طرق ہوں، مگر وہ تواتر تک نہ پہنچے۔ اس استعمال میں مشہور خبر آحاد ہی کی ایک قسم رہتی ہے۔","اسی لیے کسی کتاب میں «مشہور» دیکھ کر فوراً ایک حکم نہیں لگانا چاہیے۔ پہلے مصنف کا مکتب اور اصطلاح دیکھنی ہوگی۔ درجہ بندی کا اثر حاصل ہونے والے علم، تعارض میں ترجیح اور بعض اصولی احکام پر پڑتا ہے۔"],"definitions":[{"studyQuestion":24,"term":"المتواتر","arabic":"ما نقله جماعة عن جماعة لا يتصور توافقهم على الكذب لكثرتهم واتصل بك هكذا","translation":"جسے جماعت نے جماعت سے اس کثرت کے ساتھ نقل کیا ہو کہ کذب پر ان کا توافق متصور نہ ہو، اور اسی طرح وہ آپ تک پہنچا ہو۔","explanation":"نقل کا متعلقہ تسلسل اہم ہے؛ آخری دور میں شہرت کافی نہیں۔ خبر کی بنیاد حس پر ہوتی ہے، محض اجتہادی رائے پر نہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث كون المتواتر موجباً للعلم القطعي، ص 272","url":"https://shamela.ws/book/6302/112"},"kind":"definition","originalStudyQuestion":24},{"studyQuestion":24,"term":"المشهور","arabic":"ما كان أوله كالآحاد ثم اشتهر في العصر الثاني والثالث وتلقته الأمة بالقبول","translation":"جس کا آغاز آحاد کی طرح ہو، پھر دوسرے اور تیسرے عصر میں مشہور ہو اور امت اسے قبول کرے۔","explanation":"یہ حنفی مشہور کی تعریف ہے۔ اسے محدثین کی ہر مشہور روایت یا عام زبان کی مقبول بات کے ساتھ یکساں نہ رکھیے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث كون المتواتر موجباً للعلم القطعي، ص 272","url":"https://shamela.ws/book/6302/112"},"kind":"definition","originalStudyQuestion":24}],"originalNumber":24},{"number":25,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":14,"chapter_title":"اجماع","question":"اجماع کی تعریف، حجیت اور امکانِ انعقاد کے بارے میں بنیادی علمی مباحث کیا ہیں؟","answer":["اجماع کا معتبر ثبوت اور اجماع کی اصولی حجیت دو الگ سوال ہیں۔ صریح اتفاق، اجماعِ سکوتی اور عدمِ علمِ مخالف ایک درجہ نہیں رکھتے۔ کسی قول کے خلاف رائے نہ ملنا خود بخود پوری امت کا قطعی اجماع نہیں بناتا۔ معاصر مجلس کا اکثریتی فیصلہ اجتماعی اجتہاد ہے، اجماعِ امت نہیں۔ اسی لیے اجماع کی نسبت میں زمانہ، اہلِ اجتہاد، مسئلے کی صورت اور نقل کا طریقہ واضح کرنا ضروری ہے۔","اصولیین کے نزدیک اجماع سے مراد رسول اللہ ﷺ کی وفات کے بعد کسی زمانے میں امت محمدیہ کے تمام اہل اجتہاد کا کسی شرعی حکم پر متفق ہوجانا ہے۔ اس تعریف میں اتفاق عام لوگوں کا نہیں، بلکہ ان مجتہدین کا معتبر ہے جو متعلقہ مسئلے میں استنباط کی اہلیت رکھتے ہوں۔","«بعد وفات النبی ﷺ» کی قید اس لیے ہے کہ عہد نبوی میں اختلاف کا فیصلہ خود وحی اور رسول اللہ ﷺ کرتے تھے۔ وہاں صحابہ کا اتفاق مستقل اجماع کے بجائے نبوی اقرار یا نص کے تابع ہوتا تھا۔","«تمام مجتہدین» کی قید کے سبب اکثریت، کسی ملک کے علماء، فقہی مجلس یا ایک مکتب کا اتفاق بذات خود اجماع نہیں بنتا، اگرچہ وہ قوی اجتماعی اجتہاد ہوسکتا ہے۔ «شرعی حکم» کی قید اجماع کو محض لغوی، طبی یا سیاسی اتفاق سے ممتاز کرتی ہے۔","اجماع نئی وحی پیدا نہیں کرتا۔ وہ اس بات کا قطعی یا نہایت قوی اظہار ہوتا ہے کہ امت کے اہل علم نے کتاب و سنت کی روشنی میں کسی حکم کو متفقہ طور پر سمجھا اور قبول کیا ہے۔","اجماع کے لیے پہلی شرط یہ ہے کہ اتفاق رسول اللہ ﷺ کی وفات کے بعد ہو۔ دوسری یہ کہ ایک ہی دور کے تمام متعلقہ مسلمان مجتہدین اس حکم پر متفق ہوں۔ قوم، نسل، ملک یا فقہی مکتب کی تحدید اجماع امت کے مفہوم کو پورا نہیں کرتی۔","تیسری شرط یہ ہے کہ اتفاق واضح اور قابل اثبات ہو۔ صریح اجماع میں قول، فتویٰ، فیصلہ یا ایسا عمل سامنے آتا ہے جو رائے کو صاف ظاہر کرے۔ اگر صرف کچھ آراء ملیں اور باقی علماء کا موقف معلوم نہ ہو تو اسے بلا دلیل اجماع نہیں کہا جاسکتا۔","چوتھی شرط یہ ہے کہ مسئلہ شرعی ہو اور اہل علم کو اس کی صحیح صورت معلوم ہو۔ ایک مبہم یا بدلتی ہوئی صورت پر ظاہری اتفاق حقیقی اجماع نہیں بنتا۔ جدید طبی یا مالی مسئلے میں پہلے ماہرین سے واقعے کی درست تصویر لینا ضروری ہے۔","پانچویں شرط کے طور پر بہت سے اصولیین اجماع کے کسی شرعی مستند—نص، دلالت، قیاس یا معتبر مصلحت—سے وابستہ ہونے کو بیان کرتے ہیں۔ اختلاف یہ ہے کہ اس مستند کا معلوم اور منقول ہونا انعقاد کی شرط ہے یا نہیں۔ بہرحال اجماع محض خواہش یا مستقل تشریع نہیں۔","بعض اصولیین «انقراض عصر» کو بھی شرط قرار دیتے ہیں، یعنی اس نسل کے مجتہدین کے گزرنے تک رجوع کا امکان ختم ہو۔ جمہور کے نزدیک کامل اتفاق ہوتے ہی حجیت قائم ہوسکتی ہے۔ یہ اختلاف اجماع کے ثبوت اور لازم ہونے کے وقت سے متعلق ہے۔","اجماع میں ایک زمانے کے متعلقہ اہلِ اجتہاد کا شرعی مسئلے پر اتفاق مطلوب ہوتا ہے۔ عوامی پسند، اکثریت یا ایک شہر کے علماء کا فیصلہ اس کی جگہ نہیں لیتا۔ اجماعِ سکوتی کی حجیت اور شرائط مختلف فیہ ہیں: قول کا پہنچنا، اظہارِ مخالفت کا موقع اور خاموشی کی وجہ اہم ہیں۔ لہٰذا صریح ثابت اتفاق اور محض سکوت کو یکساں قطعی کہنا احتیاط کے خلاف ہے۔"],"definitions":[{"studyQuestion":25,"term":"الإجماع کی اقسام","arabic":"ثمَّ الاجماع على أَرْبَعَة أَقسَام ١ - إِجْمَاع الصَّحَابَة ﵃ على حكم الْحَادِثَة نصا ٢ - ثمَّ إِجْمَاعهم بِنَصّ الْبَعْض وسكوت البَاقِينَ عَن الرَّد","translation":"اجماع چار قسموں پر ہے؛ پہلی: صحابہ کا کسی واقعے کے حکم پر صراحتاً اتفاق، دوسری: بعض کی صراحت اور باقی کی بغیر انکار خاموشی۔","explanation":"شاشی کے مطابق امت کا یہ اجماع شرعاً قابلِ عمل حجت ہے۔ سب سے مضبوط درجہ صحابہ کے صریح اجماع کا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"الإجماع","url":"https://shamela.ws/book/6302/119"},"kind":"definition","originalStudyQuestion":25}],"originalNumber":25},{"number":26,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":15,"chapter_title":"قیاس","question":"قیاس کی تعریف، ارکان اور حجیت کیا ہے؟","answer":["قیاس میں فرع پر اصل جیسا حکم اسی وقت ظاہر کیا جاتا ہے جب معتبر مشترک علت دونوں میں موجود ہو۔ اس کی حجیت جمہور اہلِ سنت کے نزدیک ثابت ہے، جبکہ ظاہری روایت کا موقف مختلف ہے۔ نشہ آور چیزوں میں صحیح حدیث کا عمومی حکم بھی موجود ہے، اس لیے انہیں صرف قیاس سے حرام کہنا نامکمل ہوگا۔ قیاس کی تدریسی مثال اور کسی مسئلے کی پوری شرعی دلیل ایک چیز نہیں؛ تمام متعلقہ نصوص بھی سامنے رہنی چاہییں۔","قیاس اصول فقہ میں کسی نئے اور غیر منصوص مسئلے کو ایک منصوص یا ثابت الاصل مسئلے کے حکم میں اس لیے شریک کرنا ہے کہ دونوں میں وہی مؤثر علت پائی جاتی ہے جس پر اصل کا حکم قائم ہے۔","مشترک علت کی وجہ سے فرع کو اصل کے حکم کے ساتھ ملانا قیاس ہے۔ «الحاق» کا مطلب نیا حکم ایجاد کرنا نہیں؛ مجتہد یہ ظاہر کرتا ہے کہ شارع کا اصل میں دیا ہوا حکم اسی علت کے سبب نئی صورت کو بھی شامل ہے۔","مثلاً قرآن نے خمر کو حرام قرار دیا۔ نصوص سے اس کی مؤثر علت نشہ معلوم ہوئی۔ کوئی نئی نشہ آور مصنوعی چیز بھی اسی علت کی حامل ہو تو اسے خمر کے حکم میں شامل کرکے حرام کہا جائے گا۔ خمر اصل، نئی چیز فرع، حرمت حکم، اور نشہ علت ہے۔","قیاس محض ظاہری مشابہت نہیں۔ رنگ، شکل یا نام کی یکسانی حکم منتقل نہیں کرتی۔ ضروری ہے کہ مشترک وصف شرعاً معتبر، حکم سے مناسب، منضبط اور فرع میں واقعی موجود ہو۔","اس تعریف سے قیاس کا مقام واضح ہوتا ہے: وہ نص کا بدل نہیں، نص کے حکم اور علت کو نئے واقعے تک پہنچانے کا منضبط اجتہادی طریقہ ہے۔","قیاس کے چار بنیادی ارکان ہیں: اصل، فرع، حکم اصل اور علت۔ ان میں سے کسی رکن کی خرابی قیاس کے نتیجے کو متاثر کرتی ہے۔","اصل وہ منصوص یا متفق علیہ مسئلہ ہے جس کا شرعی حکم معلوم ہو، جیسے خمر۔ فرع وہ نیا مسئلہ ہے جس کا حکم براہ راست نص میں متعین نہ ہو، جیسے نئی نشہ آور کیمیائی چیز۔","حکم اصل وہ شرعی حکم ہے جو اصل کے بارے میں ثابت ہے، مثلاً خمر کی حرمت۔ علت وہ ظاہر، منضبط اور شرعاً معتبر وصف ہے جس سے حکم وابستہ سمجھا جاتا ہے، مثلاً عقل کو ڈھانپ دینے والا نشہ۔","ایک ثابت اصل، ایک نیا فرع، اصل کا شرعی حکم اور دونوں کو ملانے والی مشترک علت قیاس کی ساخت مکمل کرتے ہیں۔","محض چار نام پورے ہوجانا کافی نہیں۔ اصل معتبر دلیل سے ثابت ہو، فرع میں پہلے سے فیصلہ کن نص نہ ہو، حکم قابل انتقال ہو، اور علت واقعی دونوں میں پائی جائے۔ یہی داخلی ربط قیاس کو اندازے سے الگ کرتا ہے۔","§QUOTE§هو إبانة مثل حكم أحد المذكورين بمثل علته في الآخر","مفہوم: ایک مذکور کا مثل حکم اس کی مثل علت کی بنا پر دوسرے میں ظاہر کرنا؛ یہ ملا جیون کی توضیح ہے۔  حوالہ: نور الأنوار، شرحِ باب القياس۔"],"definitions":[{"studyQuestion":26,"term":"القياس الشرعي","arabic":"هو ترتب الحكم في غير المنصوص عليه على معنى هو علة لذلك الحكم في المنصوص عليه","translation":"غیر منصوص صورت میں اس معنی کی بنیاد پر حکم مرتب ہونا جو منصوص صورت کے حکم کی علت ہے۔","explanation":"اصل کے ثابت حکم کو فرع میں مشترک معتبر علت سے سمجھا جاتا ہے۔ ظاہری مماثلت یا نص کی مخالفت قیاس کی معتبر بنیاد نہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل القياس الشرعي، ص 325","url":"https://shamela.ws/book/6302/134"},"kind":"definition","originalStudyQuestion":26}],"originalNumber":26},{"number":27,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":16,"chapter_title":"علت اور مسالک علت","question":"علت اور حکمت میں بنیادی فرق کیا ہے، اور حکم کے تعدیہ میں علت کو مرکزی حیثیت کیوں دی جاتی ہے؟","answer":["علت وہ معتبر وصف ہے جس سے حکم کا تعلق استنباط میں قائم کیا جاتا ہے؛ حکمت حکم کا مطلوب فائدہ یا دفع ہونے والا نقصان ہے۔ سفر رخصت کا منضبط سبب ہے اور رفعِ مشقت اس کی حکمت۔ ہر حکمت غیر منضبط نہیں، اور بعض اصولیین منضبط حکمت سے تعلیل کی گنجائش بیان کرتے ہیں۔ اس لیے یہ کہنا درست نہیں کہ شریعت کے تمام احکام ہمیشہ حکمت سے بے تعلق اور صرف ایک ظاہری علت پر قائم ہوتے ہیں۔","سبب وہ ظاہر اور منضبط امر ہے جس پر شارع نے حکم کا وجود وابستہ کیا ہو، خواہ عقل اس مناسبت کو پوری طرح سمجھ سکے یا نہ سکے۔ سورج کا ڈھلنا نماز ظہر کے وجوب کا سبب اور رمضان کا چاند روزے کے وجوب کا سبب ہے۔","علت بھی حکم سے وابستہ ظاہر و منضبط وصف ہے، مگر قیاس کے باب میں اس میں حکم سے مناسبت اور قابل انتقال معنی نمایاں ہوتا ہے۔ نشہ حرمت خمر کی علت ہے، کیونکہ عقل و نص دونوں اس کے فساد سے حکم کا ربط سمجھاتے ہیں۔","حکمت وہ مقصد یا فائدہ ہے جس کے حصول، یا جس نقصان کے دفعیے کے لیے حکم رکھا گیا، جیسے سفر میں قصر کی حکمت مشقت دور کرنا ہے۔ مشقت افراد، موسم اور وسائل کے ساتھ بدلتی ہے، اس لیے شریعت نے قابل ضبط «سفر» کو رخصت کا سبب بنایا۔","سبب حکم کی علامت، علت اس سے مناسب قانونی وصف، اور حکمت حکم کا مطلوب فائدہ ہے۔ تاہم کتب اصول میں سبب اور علت کبھی وسیع معنی میں ایک دوسرے کے لیے بھی استعمال ہوتے ہیں؛ مصنف کی اصطلاح دیکھنا ضروری ہے۔","چونکہ حکمت اکثر باطنی، غیر منضبط اور ہر فرد میں مختلف درجے کی ہو سکتی ہے، اس لیے اسے حکم کے وجود کی بنیاد بنانا عملی طور پر مشکل ہو جاتا ہے، کیونکہ اس کی پیمائش اور یقینی تعین ممکن نہیں۔ اس کے برعکس علت ایک ظاہری اور قابلِ مشاہدہ وصف ہے، جس کی موجودگی یا عدم موجودگی کو باآسانی جانچا جا سکتا ہے۔ اسی لیے شریعت نے احکام کو حکمت کی بجائے علت سے مربوط کیا، تاکہ حکم کا اطلاق یقینی اور منضبط رہے۔","مسالکِ علت وہ طریقے ہیں جن سے علت پہچانی جاتی ہے، جیسے صریح نص، نص کا اشارہ و ایماء، معتبر اتفاق، سبر و تقسیم اور مناسبت۔ ان کی تفصیلات اور قوت پر مناہج میں فرق ہے۔ سبر و تقسیم میں ممکن اوصاف جانچ کر غیر مؤثر اوصاف الگ کیے جاتے ہیں؛ محض ایک پسندیدہ وصف منتخب کرنا اس کا بدل نہیں۔ مناسبت میں شرعی اعتبار بھی دیکھنا پڑتا ہے، صرف ظاہری فائدہ کافی نہیں۔"],"definitions":[{"studyQuestion":27,"term":"علت جاننے کے طریقے","arabic":"إِنَّمَا يعرف كَون الْمَعْنى عِلّة بِالْكتاب وبالسنة وبالإجماع وبالإجتهاد والإستنباط","translation":"کسی معنی کا علت ہونا کتاب، سنت، اجماع اور اجتہاد و استنباط سے پہچانا جاتا ہے۔","explanation":"شاشی ہر طریقے کی مثال دیتے ہیں: کتاب سے کثرتِ طواف، سنت سے نیند میں استرخاءِ مفاصل، اجماع سے صغر، اور رائے و اجتہاد سے مناسب وصف۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل القياس الشرعي","url":"https://shamela.ws/book/6302/134"},"kind":"definition","originalStudyQuestion":27}],"originalNumber":27},{"number":28,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":16,"chapter_title":"علت اور مسالک علت","question":"تخریجِ مناط، تنقیحِ مناط اور تحقیقِ مناط میں کیا فرق ہے؟","answer":["تخریجِ مناط علت کی دریافت، تنقیحِ مناط غیر مؤثر اوصاف کو الگ کرنے، اور تحقیقِ مناط ثابت علت کا خاص واقعے میں وجود جانچنے کا عمل ہے۔ یہ ترتیب علت کے استدلال اور اس کے اطلاق کو الگ کرتی ہے۔ کسی دوا میں نشہ آور اثر موجود ہے یا نہیں، یہ طبی تحقیق بھی چاہتا ہے۔ ماہر اثر کی حقیقت بتاتا ہے؛ فقیہ اس حقیقت کو معتبر علت، مقدار، ضرورت اور متعلقہ حکم سے مربوط کرتا ہے۔","تنقیحِ مناط اس وقت استعمال ہوتی ہے جب نص میں علت کا اشارہ موجود ہو مگر اس کے ساتھ غیرمتعلق اوصاف بھی مذکور ہوں، اور مجتہد اصل علت کو الگ کرے۔ تخریجِ مناط اس وقت استعمال ہوتی ہے جب نص میں علت کا کوئی اشارہ موجود نہ ہو اور مجتہد کو مکمل طور پر اپنی فکری کاوش سے علت متعین کرنی پڑے۔ تحقیقِ مناط اس وقت استعمال ہوتی ہے جب علت پہلے سے معلوم ہو اور صرف یہ جانچنا ہو کہ آیا وہ کسی خاص نئے واقعے میں موجود ہے یا نہیں۔ یہ تینوں مراحل قیاس کے عملی اطلاق کی مختلف سطحیں ہیں۔","تخریج مناط اس وقت ہوتی ہے جب نص حکم تو بتائے مگر علت صراحت سے نہ بتائے۔ مجتہد مسالک علت کے ذریعے وہ وصف دریافت کرتا ہے جس پر حکم قائم ہے۔ خمر کی حرمت سے نشے کو علت اخذ کرنا اس کی معروف مثال ہے۔","تنقیح مناط میں علت کا بنیادی رخ معلوم ہوتا ہے، مگر واقعے کے ساتھ کئی اوصاف مذکور ہوتے ہیں۔ مجتہد غیر مؤثر اوصاف ہٹا کر خالص مؤثر وصف متعین کرتا ہے۔ روزۂ رمضان کے کفارے کے واقعے سے شخص، جگہ اور اتفاقی حالات الگ کرنا اسی نوع کا عمل ہے۔","تحقیق مناط میں علت پہلے سے ثابت ہوتی ہے؛ سوال یہ ہوتا ہے کہ وہ خاص شخص، چیز یا نئے واقعے میں موجود ہے یا نہیں۔ نشہ حرمت کی علت ہے، مگر کسی نئی دوا میں واقعی نشہ ہے یا علاج کی معمولی تاثیر، یہ تحقیق مناط ہے۔","تخریج علت نکالنا، تنقیح اسے غیر متعلق اوصاف سے پاک کرنا، اور تحقیق نئی صورت میں اس کا وجود ثابت کرنا ہے۔","ان تینوں کو خلط کرنے سے بحث الجھتی ہے۔ علماء علت پر متفق ہوسکتے ہیں مگر نئی صورت میں اس کے وجود پر اختلاف کریں؛ یہ اختلاف تحقیق مناط کا ہوگا، اصول علت کا نہیں۔"],"definitions":[{"studyQuestion":28,"term":"علتِ مستنبط (رائے و اجتہاد)","arabic":"إذا وجدنا وصفا مناسبا للحكم وقد اقترن به الحكم في موضع الإجماع يضاف الحكم إليه للمناسبة لا لشهادة الشرع بكونه علة","translation":"جب ایسا مناسب وصف ملے جس کے ساتھ اجماع کے مقام پر حکم مقرون ہو تو حکم اس کی طرف مناسبت کی بنا پر منسوب ہوتا ہے، شرع کی گواہی سے نہیں۔","explanation":"شاشی کے مطابق یہ ظن پر مبنی ہے اور ظن عمل کو واجب کرتا ہے جب اس سے اوپر دلیل نہ ہو۔ اسی لیے یہ قیاس مناسب فرق سے باطل ہو جاتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"العلة المعلومة بالرأي والاجتهاد","url":"https://shamela.ws/book/6302/140"},"kind":"definition","originalStudyQuestion":28}],"originalNumber":28},{"number":29,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":15,"chapter_title":"قیاس","question":"قیاس کی صحت کے لیے اصل، فرع، حکم اور علت میں کن بنیادی شرائط کا پایا جانا ضروری ہے؟","answer":["صحیح قیاس میں اصل کا حکم معتبر اور غیر منسوخ ہو، علت ثابت اور قابلِ تعدیہ ہو، اور فرع میں یہی مؤثر علت پائی جائے۔ محض قریب ترین مشابہ وصف کافی نہیں۔ فرع کے بارے میں ایسی فیصلہ کن نص موجود ہو جو مجوزہ قیاس کے خلاف ہو تو قیاس معتبر نہیں ہوگا۔ قیاسِ اولیٰ، مساوی اور ادنیٰ کی بحث بھی ہے، مگر قوتِ مماثلت علت کے شرعی اعتبار کا بدل نہیں۔","اصل (وہ مسئلہ جس پر قیاس کیا جائے) کی شرائط یہ ہیں: اس کا حکم نص یا اجماع سے ثابت ہو، وہ حکم منسوخ نہ ہو، وہ حکم کسی ایسی خصوصیت پر مبنی نہ ہو جو صرف نبی کریم ﷺ یا کسی خاص واقعے سے مخصوص ہو، اور اس حکم کی علت معلوم اور قابلِ انتقال ہو۔ اگر اصل کا حکم خود کسی قیاس سے ثابت ہو تو بعض اصولیین اس پر مزید قیاس کرنے (قیاس علی القیاس) کی اجازت نہیں دیتے، تاکہ سلسلہ لامحدود نہ ہو جائے۔","فرع (وہ نیا مسئلہ جس کا حکم مطلوب ہے) کی شرائط یہ ہیں: اس کا کوئی نص موجود نہ ہو، اس میں اصل جیسی یا اس کے قریب ترین علت پائی جاتی ہو، اور اس پر قیاس کا حکم اصل کے حکم کے مطابق ہی متعین ہونا چاہیے، اس کے برعکس نہیں۔ اگر فرع پر پہلے سے کوئی صریح نص موجود ہو تو اس پر قیاس کی ضرورت باقی نہیں رہتی، کیونکہ قیاس صرف انہی مسائل میں استعمال ہوتا ہے جہاں براہِ راست نص موجود نہ ہو۔","علت وہ وصف ہے جس پر شارع نے حکم کا مدار رکھا ہو، اور جس کی بنا پر اصل اور فرع کے مابین حکم کا اشتراک قائم کیا جا سکے۔ علت قیاس کی روح ہے، کیونکہ اسی کے ذریعے یہ ثابت ہوتا ہے کہ اصل اور فرع میں واقعی مماثلت پائی جاتی ہے۔ مثال کے طور پر شراب کی حرمت کی علت 'اسکار' (نشہ آور ہونا) ہے، اور جب یہ علت کسی نئی چیز میں پائی جائے، جیسے کوئی نیا نشہ آور مشروب، تو اسے بھی حرام قرار دیا جاتا ہے۔","قیاس پر اعتراض میں منعِ علت، فرع میں علت کی عدم موجودگی، مؤثر فرق اور نقض جیسے عنوانات آتے ہیں۔ نقض میں علت کا دعویٰ ہوتے ہوئے حکم نہ پانے کی صورت پیش کی جاتی ہے؛ اس کا جواب مانع یا شرط کی تحقیق سے متعلق ہوسکتا ہے۔ عبادات کی مقرر تعداد اور مقدار میں محض ذوقی مناسبت سے اضافہ نہیں کیا جاسکتا۔ اصل حکم تعبدی ہو یا معقول المعنی، اس کی تحقیق قیاس کے دائرے کو متعین کرتی ہے۔"],"definitions":[],"originalNumber":29},{"number":30,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":11,"chapter_title":"دلیل شرعی مفہوم اور اقسام","question":"دلیل کے ثبوت اور دلالت میں قطعیت و ظنیت کا فرق کیا ہے، اور یہ فرق فقہی نتیجے کو کیسے متاثر کرتا ہے؟","answer":["ثبوت متن کے صحیح طور پر پہنچنے کا اور دلالت اس متن کے معنی کا سوال ہے۔ دونوں میں قطعیت اور ظنیت الگ متعین ہوتی ہیں؛ اس طرح اصولی طور پر چار نسبتیں زیرِ بحث آتی ہیں۔ ظنی کا مطلب بے اعتبار نہیں، بلکہ دلیل و قرائن کی بنیاد پر غالب گمان ہے۔ بہت سے عملی احکام معتبر ظنی دلائل سے ثابت ہوتے ہیں۔ اختلاف اسی وقت علمی سمجھا جائے گا جب احتمال واقعی ہو، محض من گھڑت امکان نہ ہو۔","ثبوت کا سوال یہ ہے کہ متن یا خبر واقعی اپنے منسوب مصدر سے پہنچی ہے یا نہیں۔ دلالت کا سوال یہ ہے کہ وہ ثابت متن کس حکم یا معنی کی طرف رہنمائی کرتا ہے۔ دونوں الگ علمی مراحل ہیں۔","ثبوت کی قطعیت تواتر یا ایسے یقینی طریق نقل سے پیدا ہوتی ہے جو جھوٹ پر اجتماع کا معقول امکان ختم کردے۔ ثبوت کی ظنیت معتبر راویوں کی ایسی خبر میں ہوتی ہے جو حجت تو ہے، مگر تواتر کے درجے تک نہیں پہنچی۔","دلالت کی قطعیت لفظ کے ایک ہی معتبر معنی پر واضح ہونے سے پیدا ہوتی ہے۔ دلالت کی ظنیت اس وقت ہوتی ہے جب عموم و خصوص، حقیقت و مجاز، اطلاق و تقیید یا متعدد لغوی معانی کی قابل اعتبار گنجائش ہو۔","مثال: قرآن کی آیت کا ثبوت قطعی ہے، مگر لفظ «لَامَسْتُمُ النِّسَاءَ» (النساء: 43) سے محض چھونا مراد ہے یا ازدواجی تعلق، اس میں فقہی اختلاف ہوا۔ شافعیہ اور احناف کے وضو سے متعلق نتائج اسی دلالتی اختلاف سے متاثر ہوئے۔","اس فرق سے معلوم ہوتا ہے کہ نص کی تقدیس اور انسانی تفسیر کا درجہ ایک نہیں۔ متن قطعی طور پر محفوظ ہوسکتا ہے، مگر اس سے خاص مسئلے کا مفہوم اجتہادی رہ سکتا ہے۔"],"definitions":[],"originalNumber":30},{"number":31,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":12,"chapter_title":"قرآن مجید بحیثیت مصدر شریعت","question":"قرآن سے حکم اخذ کرتے وقت سیاق، سنت اور عربی زبان کو نظرانداز کیوں نہیں کیا جا سکتا؟","answer":["قرآن کے الفاظ عربی استعمال، سیاق اور نبوی تبیین کے ساتھ سمجھے جاتے ہیں۔ سببِ نزول کسی خطاب کا پس منظر واضح کرتا ہے، مگر عام لفظ کو ہر صورت اسی واقعے تک محدود نہیں کرتا۔ عام کی تخصیص یا مطلق کی تقیید کے لیے معتبر دلیل چاہیے۔ زبان، سنت اور دوسری آیات کو جمع کیے بغیر کسی ترجمے سے مکمل فقہی نتیجہ نکالنا اکثر متعلقہ قیود اور استثناؤں کو نظرانداز کردیتا ہے۔","سیاق و سباق سے مراد کسی آیت کا وہ سابقہ اور بعد کا کلام ہے جو اس آیت کے مکمل اور درست مفہوم کو سمجھنے میں مدد دیتا ہے۔ کسی آیت کو اس کے سیاق سے کاٹ کر پڑھنا اکثر غلط فہمی اور غلط استنباط کا باعث بنتا ہے۔ فقہاء نے قرآن سے احکام اخذ کرتے وقت ہمیشہ سیاق و سباق، اسبابِ نزول اور دیگر متعلقہ آیات کو ملحوظ رکھنے کی تاکید کی ہے، تاکہ حکم کا استخراج شارع کی حقیقی مراد کے مطابق ہو۔","قرآن مجید سے احکام کا درست استنباط عربی زبان، علمِ نحو و صرف، بلاغت، اسبابِ نزول، ناسخ و منسوخ، محکم و متشابہ، اور دلالاتِ الفاظ (عام، خاص، مطلق، مقید، حقیقت، مجاز) کے علم کے بغیر ناممکن ہے۔ یہی وجہ ہے کہ ایک مجتہد کے لیے صرف قرآن کے ترجمے یا سرسری مطالعے کی بنیاد پر حکم اخذ کرنا کافی نہیں سمجھا جاتا، بلکہ اس کے لیے وسیع لسانی و اصولی علم درکار ہوتا ہے، جس کی تفصیل اصولِ فقہ کی کتب میں 'دلالاتِ الفاظ' کے باب میں کی جاتی ہے۔"],"definitions":[],"originalNumber":31},{"number":32,"unit_id":3,"unit_name":"یونٹ سوم","unit_title":"ادلۂ شرعیہ اور مصادر شریعت","chapter_number":13,"chapter_title":"سنت نبوی بحیثیت مصدر شریعت","question":"سنت قرآن کی تبیین، تخصیص اور تقیید کس طرح کرتی ہے؟","answer":["تبیین مجمل حکم کی عملی تفصیل، تخصیص عام حکم کے بعض افراد کا اخراج، اور تقیید مطلق حکم کے ساتھ معتبر وصف کی تعیین ہے۔ نماز کی کیفیت تبیین کی واضح مثال ہے۔ وراثت کے عمومی احکام اور قتل یا اختلافِ دین جیسے موانع کا تعلق تخصیص کے مباحث سے سمجھا جاتا ہے۔ خبرِ واحد سے قرآن کی تخصیص یا اس پر اضافہ کے مسائل میں حنفی اور جمہوری مناہج کی تفصیل ہے؛ ہر صورت کا ایک ہی حکم نہیں۔","سنت قرآن کے اجمال کو قول، فعل اور تقریر سے کھولتی ہے؛ عام کی تخصیص، مطلق کی تقیید اور حکم کی عملی کیفیت بتاتی ہے۔ قرآن نے رسول ﷺ کی ذمہ داری بیان کی: ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾۔ اس لیے ثابت سنت کو قرآن سے الگ نہیں بلکہ اس کے مجاز بیان کے طور پر پڑھا جاتا ہے۔","قرآن نماز، زکوٰۃ اور حج کا حکم دیتا ہے۔ سنت نماز کی رکعات، زکوٰۃ کے نصاب اور حج کے مناسک واضح کرتی ہے۔ فقہی مذاہب تفصیلات میں حدیث کے ثبوت یا دلالت پر مختلف ہوسکتے ہیں، مگر اصولی طور پر سب سنت کی توضیحی حجیت تسلیم کرتے ہیں۔","بیان اور اجمال کی بحث یہ طے کرتی ہے کہ شارع کا خطاب کب بذاتِ خود کافی ہے اور کب کسی دوسرے بیان کی ضرورت ہے۔ قرآن کا اجمال سنت سے واضح ہوسکتا ہے، عام کی تخصیص، مطلق کی تقیید یا مجمل کی تفصیل ہوسکتی ہے؛ اس لیے نصوص کو ایک مربوط مجموعے کے طور پر پڑھنا ضروری ہے۔","قرآن کے ساتھ نسبت کے اعتبار سے سنت کی تین اقسام ہیں: سنتِ مؤکدہ یا مقررہ (جو قرآن کے حکم کی تائید و تاکید کرے، جیسے نماز کے وجوب کی احادیث)، سنتِ مبینہ یا مفسرہ (جو قرآن کے مجمل حکم کی تفصیل، تخصیص یا تقیید بیان کرے، جیسے نماز کی کیفیت کی احادیث)، اور سنتِ مستقلہ (جو قرآن میں مذکور نہ ہو بلکہ نبی کریم ﷺ نے مستقل طور پر بیان فرمائی ہو، جیسے پالتو گدھے کے گوشت کی حرمت)۔"],"definitions":[],"originalNumber":32},{"number":33,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":17,"chapter_title":"استحسان","question":"استحسان کیا ہے، اور اسے محض شخصی پسند کے بجائے منضبط اصولی استدلال کیوں سمجھا جاتا ہے؟","answer":["استحسان عام قاعدے یا ظاہر قیاس کو بلا دلیل چھوڑنا نہیں، بلکہ زیادہ قوی معتبر دلیل کی بنا پر خاص صورت کا مختلف حکم اختیار کرنا ہے۔ نور الأنوار میں اثر، اجماع، ضرورت اور قیاسِ خفی کی بنیادیں مذکور ہیں۔ سلم میں معلوم شرائط کے ساتھ مؤخر سامان کی بیع نص سے جائز ہے؛ اسے موجود سامان کی بیع کے عمومی تصور پر رد نہیں کیا جاتا۔ اصل سوال عدول کی دلیل اور اس کی قوت ہے، ذاتی پسند نہیں۔","لغت میں استحسان کسی چیز کو اچھا سمجھنے یا اسے بہتر قرار دینے کو کہتے ہیں۔ اصول فقہ میں یہ محض ذاتی پسند نہیں، بلکہ کسی مسئلے میں ظاہر قیاس یا عام قاعدے سے زیادہ قوی شرعی دلیل کی بنا پر عدول کرنے کا منہج ہے۔","لغوی تعریف: «الِاسْتِحْسَانُ عَدُّ الشَّيْءِ حَسَنًا»","کسی چیز کو اچھا یا بہتر سمجھنا استحسان کا لغوی معنی ہے۔ اس معنی سے اگر اصولی قیدیں ہٹا دی جائیں تو شخصی پسند کا خطرہ پیدا ہوتا ہے۔","کسی مسئلے میں اس جیسے دوسرے مسائل کے عام حکم سے کسی زیادہ قوی دلیل کی وجہ سے مختلف حکم اختیار کرنا استحسان ہے۔","یہ قوی دلیل نص، اجماع، ضرورت، عرف، خفی قیاس یا دوسری معتبر بنیاد ہوسکتی ہے۔ احناف کے ہاں استحسان فقہی لچک کا منضبط وسیلہ ہے؛ وہ قانون کو بے مقصد عموم یا غیر معمولی مشقت سے بچاتا ہے، لیکن نص اور اصول کے تابع رہتا ہے۔","استحسان میں قوی دلیل کے سبب ظاہر قیاس یا عام نظائر کے مقتضا سے عدول ہوتا ہے۔ اسے اچھا محسوس ہونے والی آزاد رائے نہ سمجھیں۔ نور الأنوار اس کی بنیادوں میں اثر، اجماع، ضرورت اور قیاسِ خفی ذکر کرتی ہے۔ مختلف مکاتب ایک ہی عملی استثناء کو الگ اصطلاح سے بیان کرسکتے ہیں؛ اصل تحقیق دلیل اور اس کی قوت کی ہے۔"],"definitions":[{"studyQuestion":33,"term":"الاستحسان","arabic":"هُوَ دَلِيلٌ يَقَعُ فِي مُقَابَلَةِ الْقِيَاسِ الْجَلِيِّ","translation":"استحسان ایسی دلیل ہے جو ظاہر (جلی) قیاس کے مقابلے میں آئے۔","explanation":"تلویح کے مطابق یہی صحیح تعریف ہے اور احناف کی کتب میں استحسان بول کر عموماً قیاسِ خفی مراد ہوتا ہے؛ ہر قیاسِ خفی استحسان ہے مگر ہر استحسان قیاسِ خفی نہیں۔ نفسانی خواہش کا نام استحسان نہیں۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"فصل في الاستحسان","url":"https://shamela.ws/book/9508/592"},"kind":"passage","originalStudyQuestion":33}],"originalNumber":33},{"number":34,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":18,"chapter_title":"مصالح مرسلہ","question":"مصالحِ مرسلہ سے کیا مراد ہے، اور اسے کن شرائط کے تحت معتبر مصلحت سمجھا جاتا ہے؟","answer":["مصلحتِ مرسلہ وہ مصلحت ہے جس کے لیے مخصوص جزوی دلیل قبول یا رد کی نہ ہو، مگر وہ شریعت کے معتبر کلی اصولوں سے مناسبت رکھتی ہو۔ اسے حقیقی، قابلِ تحقیق اور شرعی حدود سے ہم آہنگ ہونا چاہیے۔ عمومی مصلحت کا وزن اہم ہے، مگر تمام مکاتب میں ہر فردی مصلحت کو محض فردی ہونے کی وجہ سے رد نہیں کیا جاتا۔ عبادت کی نئی مقدار یا مقرر ہیئت صرف افادیت کے اندازے سے وضع نہیں ہوسکتی۔","مصلحت مرسلہ ایسی حقیقی اور شرعاً مناسب مصلحت ہے جس کے اعتبار یا رد پر کوئی خاص نص یا معین اجماع موجود نہ ہو، لیکن وہ شریعت کے کلی مقاصد اور عمومی اصولوں سے ہم آہنگ ہو۔","ایسی مصلحت جسے کسی خاص دلیل نے نام لے کر معتبر یا نامعتبر نہ کہا ہو، مصلحت مرسلہ کہلاتی ہے۔ «مرسلہ» کا مطلب بے قید نہیں؛ صرف خاص جزوی نص سے غیر وابستہ ہونا ہے۔","مثلاً سرکاری دستاویزات، ٹریفک قوانین، ہسپتالوں کے حفاظتی ضوابط اور ڈیجیٹل ریکارڈ کی بہت سی صورتیں قدیم نصوص میں اپنے موجودہ ناموں سے نہیں۔ ان کی مشروعیت عدل، حفظ جان، حفظ مال، امانت اور دفع ضرر جیسے کلی اصولوں سے جانچی جاتی ہے۔","اگر کوئی خاص نص مصلحت کو قبول کرتی ہو تو وہ «معتبرہ» ہے، اور اگر رد کرتی ہو تو «ملغاہ»۔ مرسلہ ان دونوں کے درمیان وہ میدان ہے جہاں منضبط اجتہاد کی ضرورت ہوتی ہے۔","مصلحت مرسلہ زیادہ تر معاملات، سیاست شرعیہ اور اجتماعی نظم میں کام کرتی ہے۔ خالص عبادات کی مقدار اور ہیئت میں اصل توقیف ہے؛ وہاں محض فائدے کے اندازے سے نئی عبادت نہیں بنائی جاسکتی۔","مصالحِ مرسلہ کو حجت ماننے کے لیے فقہاء نے چند شرائط مقرر کی ہیں: مصلحت حقیقی ہو، وہمی یا فرضی نہ ہو؛ مصلحت عمومی ہو، محض کسی خاص فرد کے مفاد تک محدود نہ ہو؛ اور مصلحت کسی قطعی نص یا اجماع سے متصادم نہ ہو۔ یہ شرائط اس لیے ضروری ہیں تاکہ مصلحت کے نام پر شریعت میں من مانی تبدیلیاں نہ کی جا سکیں، اور اس مصدر کا استعمال صرف انہی مسائل تک محدود رہے جہاں شریعت خاموش ہو اور معاشرتی مفاد کا تقاضا موجود ہو۔"],"definitions":[{"studyQuestion":34,"term":"حکمت اور وصفِ ظاہر","arabic":"الْحِكْمَةُ الْمُجَرَّدَةُ لَا تُعْتَبَرُ فِي كُلِّ فَرْدٍ لِخَفَائِهَا وَعَدَمِ انْضِبَاطِهَا بَلْ فِي الْجِنْسِ فَيُضَافُ الْحُكْمُ إِلَى وَصْفٍ ظَاهِرٍ مُنْضَبِطٍ","translation":"محض حکمت ہر فرد میں معتبر نہیں، کیونکہ وہ مخفی اور غیر منضبط ہے؛ اس لیے حکم ایسے وصف کی طرف منسوب ہوتا ہے جو ظاہر اور منضبط ہو۔","explanation":"مثال: سفر کا وصف مشقت کی حکمت کے ساتھ جڑا ہے۔ مصلحت و حکمت کو براہِ راست علت بنانے کے بجائے ظاہر وصف پر مدار رکھنا استنباط میں ابہام روکتا ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"المناسب والحكمة","url":"https://shamela.ws/book/9508/558"},"kind":"definition","originalStudyQuestion":34}],"originalNumber":34},{"number":35,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":19,"chapter_title":"استصحاب","question":"استصحاب کی اصولی حقیقت کیا ہے، اور فقہی استدلال میں اس کا عملی کردار کیا ہے؟","answer":["استصحاب سابق ثابت حالت کی بقا ہے، جب تبدیلی کی کافی معتبر دلیل نہ ہو۔ اس کے لیے ہمیشہ نئی دلیل کا قطعی ہونا لازم نہیں؛ متعلقہ باب میں معتبر شہادت یا شرعی حجت بھی سابق حالت بدل سکتی ہے۔ حنفی اصول میں دفع اور استحقاق کے لیے استصحاب کی قوت کا فرق اہم ہے۔ مثال کے طور پر مفقود کی سابق زندگی سے اس کے موجود حقوق کا تحفظ اور اس کے لیے نئے حق کا اثبات ایک ہی مسئلہ نہیں۔","استصحاب سے مراد کسی پہلے سے ثابت حالت یا حکم کو اس وقت تک برقرار سمجھنا ہے جب تک اس کے بدلنے کی معتبر دلیل نہ مل جائے۔ یہ اصول وہاں کام کرتا ہے جہاں نئی دلیل موجود نہ ہو اور سابق حالت یقینی یا معتبر طور پر معلوم ہو۔","جو حالت پہلے ثابت تھی، اسے اسی طرح باقی مانا جائے گا جب تک تبدیلی کی دلیل قائم نہ ہو۔","مثلاً کسی شخص کا وضو یقینی طور پر ثابت ہو اور بعد میں صرف شک ہو کہ ٹوٹا یا نہیں، تو وضو باقی سمجھا جائے گا۔ اسی طرح ثابت ملکیت محض بے دلیل دعوے سے ختم نہیں ہوتی۔","استصحاب نئی حقیقت پیدا نہیں کرتا؛ وہ ثبوت کے خلا میں سابق معلوم حالت کو عملی بنیاد بناتا ہے۔ اگر صحیح نص، گواہی، اقرار یا دوسرا قوی ثبوت تبدیلی دکھادے تو استصحاب ختم ہوجاتا ہے۔","اسی لیے اسے اکثر آخری اجتہادی سہارا کہا جاتا ہے۔ پہلے مخصوص دلائل تلاش کیے جاتے ہیں؛ ان کے نہ ملنے پر سابق حالت کی بقا سے عملی فیصلہ کیا جاتا ہے۔","استصحابِ حال سے مراد یہ اصول ہے کہ جو حکم پہلے سے یقینی طور پر ثابت ہو، اس کے بدل جانے کی کوئی یقینی دلیل موجود نہ ہونے تک، اسی حکم کا برقرار رہنا سمجھا جائے۔ اس کی حجیت اس عقلی و شرعی اصول پر مبنی ہے کہ 'الیقین لا یزول بالشک' (یقین شک سے زائل نہیں ہوتا)۔ یہ مصدر بطور احتیاطی اور آخری ذریعۂ استدلال استعمال ہوتا ہے، یعنی جب کوئی اور مضبوط دلیل دستیاب نہ ہو تو مجتہد استصحابِ حال کا سہارا لیتا ہے۔"],"definitions":[{"studyQuestion":35,"term":"استصحاب: حنفی نقطۂ نظر","arabic":"وَالِاسْتِصْحَابُ لَيْسَ بِحُجَّةٍ عِنْدَ عُلَمَائِنَا","translation":"ہمارے علماء کے نزدیک استصحاب (سابقہ حالت کو برقرار ماننا) حجت نہیں۔","explanation":"تلویح میں یہ بات نسخ کی بحث میں ضمناً آئی ہے۔ حنفیہ استصحاب کو دفع (پہلے سے موجود حق کو برقرار رکھنے) کے لیے سمجھتے ہیں، نئے حکم کے اثبات کے لیے دلیل نہیں مانتے؛ دوسرے مذاہب کی رائے الگ ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"بحث النسخ","url":"https://shamela.ws/book/9508/495"},"kind":"definition","originalStudyQuestion":35}],"originalNumber":35},{"number":36,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":20,"chapter_title":"عرف و عادت","question":"عرف کب شرعی اعتبار سے معتبر بنتا ہے، اور عرفِ صحیح و عرفِ فاسد میں کیا فرق ہے؟","answer":["معتبر عرف عام یا متعلقہ حلقے میں غالب ہو، معاملے کے وقت موجود ہو، اور فیصلہ کن نص یا صریح معتبر شرط کے خلاف نہ ہو۔ تجارتی معاہدے میں ترسیل، اجرت یا عیب کی غیر مذکور تفصیل عرف سے سمجھ آسکتی ہے۔ مگر فریقین نے کسی جائز تفصیل کو صاف متعین کردیا ہو تو عمومی عرف خودکار طور پر ان کی شرط بدل نہیں دیتا۔ عرف کی حجیت اس کے صحیح، متعلق اور ثابت ہونے سے ہے، محض مشہور ہونے سے نہیں۔","عرف صحیح وہ رواج ہے جو کسی قطعی نص، حرام امر، مسلم شرعی اصول یا فریق کے ثابت حق سے متصادم نہ ہو اور لوگوں کی جائز ضرورت پوری کرے۔ ایسا عرف الفاظ کی تشریح، معاملات کی تکمیل اور غیر منصوص جزئیات کی تعیین میں معتبر ہوسکتا ہے۔","عرف فاسد وہ ہے جو حلال کو حرام یا حرام کو حلال بنائے، ظلم و ضرر کو معمول قرار دے، واجب حق ساقط کرے یا واضح شرعی حکم کے خلاف ہو۔ سودی لین دین، رشوت، جہیز کا جبری مطالبہ، ناپ تول میں کمی یا ملازم کی اجرت روکنا عام ہوجائے تب بھی صحیح عرف نہیں بنتا۔","اصولی ضابطہ: «الْعِبْرَةُ لِلْعُرْفِ الصَّحِيحِ لَا لِلْعُرْفِ الْفَاسِدِ»","شرعی اعتبار صرف درست عرف کو حاصل ہے، محض رواج کو نہیں۔","شناخت کے لیے تین سطحیں دیکھی جائیں گی: عمل کی حقیقت کیا ہے، اس کا نتیجہ کس حق یا مصلحت پر پڑتا ہے، اور نصوص و کلی قواعد سے اس کا تعلق کیا بنتا ہے۔ نام بدلنے سے حقیقت نہیں بدلتی؛ سود کو سروس چارج کہنے سے وہ لازماً جائز نہیں ہوجاتا۔","اسی طرح ہر نئی چیز فاسد نہیں۔ اگر نیا طریقہ شفاف، رضامندی پر مبنی، ضرر سے محفوظ اور شرعی حدود کے اندر ہو تو اس کا نیا ہونا اس کے اعتبار میں مانع نہیں۔","عرفِ صحیح وہ رواج ہے جو کسی نصِ شرعی سے متصادم نہ ہو اور شریعت کے عمومی مزاج سے ہم آہنگ ہو، جیسے بازار میں بیع کی مخصوص شرائط کا رواج۔ عرفِ فاسد وہ رواج ہے جو کسی شرعی حکم سے متصادم ہو، جیسے سودی معاہدات کا معاشرتی طور پر رائج ہونا۔ صرف عرفِ صحیح ہی فقہی حجیت رکھتا ہے، جبکہ عرفِ فاسد کو، خواہ کتنا ہی معروف اور رائج کیوں نہ ہو، شرعی اعتبار سے تسلیم نہیں کیا جاتا۔"],"definitions":[],"originalNumber":36},{"number":37,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":21,"chapter_title":"قول صحابی","question":"قولِ صحابی کی حجیت کے بارے میں اصولیین کے اہم مواقف کیا ہیں؟","answer":["قولِ صحابی میں پہلے دیکھا جاتا ہے کہ وہ مرفوع روایت، اجماع، ناقابلِ رائے امر یا اجتہادی فتویٰ ہے۔ اختلاف خاص طور پر اس اجتہادی قول میں ہے جس کا مخالف صحابی معلوم نہ ہو۔ حنفی، مالکی اور حنبلی روایت میں اسے اہم وزن حاصل ہے، مگر شرائط و مراتب مختلف ہیں۔ شافعی روایت میں بھی ایک ہی مطلق موقف نہیں؛ قدیم و جدید اقوال اور بعد کے اصولیین کی تفصیل موجود ہے۔ صحابی کا قول دوسرے صحابی پر ہر اجتہادی مسئلے میں لازماً حجت نہیں۔","قول صحابی سے مراد کسی صحابی سے ثابت وہ فتویٰ، فیصلہ یا اجتہادی رائے ہے جو کسی شرعی مسئلے کے بارے میں منقول ہو۔ یہاں «صحابی» اس شخص کو کہتے ہیں جس نے حالت ایمان میں رسول اللہ ﷺ سے ملاقات کی اور ایمان پر وفات پائی۔","کسی شرعی مسئلے میں ایک صحابی کا ثابت شدہ فتویٰ، عدالتی فیصلہ یا اجتہادی موقف۔","ہر منقول بات ایک درجے کی نہیں۔ اگر صحابی رسول اللہ ﷺ کی بات نقل کرے تو وہ حدیث مرفوع ہے۔ اگر تمام صحابہ کسی حکم پر متفق ہوں تو وہ اجماع صحابہ ہے۔ قول صحابی کی اصل بحث وہاں ہوتی ہے جہاں ایک یا چند صحابہ کی اجتہادی رائے ہو اور اس پر مکمل اجماع ثابت نہ ہو۔","اگر قول ایسے امر سے متعلق ہو جس میں محض رائے کی گنجائش نہیں، جیسے بعض غیبی امور یا خاص مقدار، تو محدثین و اصولیین کبھی اسے «حکمِ رفع» دیتے ہیں، بشرطیکہ اسرائیلی روایت یا دوسرے ماخذ کا احتمال نہ ہو۔","اس لیے حجیت پر بحث سے پہلے نسبت، نوعیت اور محل معلوم کرنا ضروری ہے: یہ روایت ہے، اجماع ہے، قضائی فیصلہ ہے یا شخصی اجتہاد؟","حنفی اور مالکی مکتب کے نزدیک قولِ صحابی، بشرطیکہ وہ کسی نص سے مستنبط نہ ہو (یعنی صرف رائے پر مبنی ہو) اور دیگر صحابہ کی مخالفت سے محفوظ ہو، ایک درجہ حجیت رکھتا ہے، خصوصاً ان مسائل میں جہاں رائے کی گنجائش کم ہو (جیسے حدود کی مقدار)۔ شافعی مکتب کے نزدیک قولِ صحابی حجت نہیں، کیونکہ صحابی بھی بہرحال ایک مجتہد ہے جس سے خطا کا امکان موجود ہے، اگرچہ ان کی رائے کو ایک قوی قرینہ ضرور سمجھا جاتا ہے۔"],"definitions":[],"originalNumber":37},{"number":38,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":22,"chapter_title":"شرع من قبلنا","question":"شرعِ من قبلنا کی اصولی حیثیت کیا ہے، اور اسے دلیل ماننے میں کن شرائط کا لحاظ کیا جاتا ہے؟","answer":["سابقہ شریعت کے احکام میں تین صورتیں الگ ہیں: ہماری شریعت جس کی تائید کرے، جسے رد یا منسوخ کرے، اور جسے بیان کرے مگر ہمارے لیے قبول یا رد کی صراحت نہ ہو۔ پہلی دو میں حکم واضح ہے؛ اختلاف تیسری میں ہے۔ حنفی روایت میں اسے شرائط کے ساتھ دلیل ماننے کی گنجائش ہے، جبکہ دیگر اصولیین میں اختلاف ملتا ہے۔ حجیت ہماری معتبر وحی میں نقل ہونے سے متعلق ہے، موجودہ مذہبی کتاب کی ہر عبارت سے نہیں۔","شرع من قبلنا سے مراد وہ احکام ہیں جو اللہ تعالیٰ نے نبی اکرم ﷺ سے پہلے کسی نبی اور اس کی امت کے لیے مقرر فرمائے تھے، پھر ان کا ذکر قرآن مجید یا صحیح سنت میں ہم تک پہنچا۔ اصولیین خاص طور پر یہ بحث کرتے ہیں کہ ایسے احکام میں سے کون سے حکم امت محمدیہ کے لیے بھی قابل عمل ہیں۔","ہمارے نبی ﷺ کی بعثت سے پہلے گزرنے والے انبیاء کی شریعتوں میں ثابت احکام۔","یہاں ہر قدیم مذہبی روایت مراد نہیں۔ موجودہ تورات، انجیل، تاریخی روایت یا اسرائیلی حکایت اپنی مستقل سند سے ہمارے لیے شرعی دلیل نہیں بنتی۔ اصولی بحث اسی سابقہ حکم میں ہے جس کا سابق شریعت ہونا ہماری معتبر وحی سے ثابت ہو۔","شرع من قبلنا کے تین بڑے درجے ہیں: جس حکم کو اسلام نے برقرار رکھا؛ جسے منسوخ یا مخصوص کردیا؛ اور جس کا ذکر تو کیا مگر موجودہ امت کے بارے میں صریح قبول یا نسخ بیان نہ ہوا۔ اصل اختلاف تیسری قسم میں ہے۔","اس بحث کا مقصد سابقہ شریعت کو اسلام کے برابر رکھنا نہیں، بلکہ یہ سمجھنا ہے کہ قرآن و سنت نے ماضی کے کسی حکم کو ہمارے سامنے کس قانونی حیثیت سے پیش کیا ہے۔"],"definitions":[],"originalNumber":38},{"number":39,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":23,"chapter_title":"سد ذرائع اور فتح ذرائع","question":"سدِّ ذرائع کیا ہے، اور مباح وسیلے کو ممنوع قرار دینے کے لیے کن حدود کا لحاظ ضروری ہے؟","answer":["سدِّ ذرائع میں وسیلے کا حکم اس کے معتبر اور غالب انجام سے متاثر ہوتا ہے۔ محض بعید امکان سے ہر جائز عمل ممنوع نہیں ہوجاتا۔ نقصان کی شدت، وقوع کا احتمال، متبادل طریقہ اور پابندی کا تناسب دیکھنا ضروری ہے۔ اس کے ساتھ فتحِ ذرائع کا تصور بھی ہے: جائز مقصد تک پہنچنے والے معتبر راستے کھولنا۔ ذرائع کی بحث صرف روکنے کا اصول نہیں، مقصد اور وسیلے کے شرعی تعلق کا مطالعہ بھی ہے۔","سد ذرائع کا مطلب یہ ہے کہ کسی ایسے جائز یا بظاہر بے ضرر وسیلے کو روکا جائے جو غالب طور پر حرام، ظلم یا معتبر شرعی مفسدت تک پہنچاتا ہو۔ یہاں ممانعت خود وسیلے کی ذاتی برائی کی وجہ سے نہیں، بلکہ اس کے متوقع انجام کی وجہ سے ہوتی ہے۔","فساد تک پہنچانے والے راستوں کی جڑ کاٹ دینا تاکہ فساد واقع نہ ہو۔","قرآن نے فرمایا: ﴿وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ﴾ (الأنعام: 108)، یعنی جنہیں یہ لوگ اللہ کے سوا پکارتے ہیں انہیں برا نہ کہو، ورنہ وہ جہالت سے زیادتی کرتے ہوئے اللہ کو برا کہیں گے۔ بتوں کو برا کہنا فی نفسہٖ توحید کے خلاف نہ تھا، مگر جب اس سے ایک بڑی بے حرمتی پیدا ہونے لگی تو اس راستے کو بند کردیا گیا۔","سد ذرائع احتیاط کا بے حد پھیلاؤ نہیں۔ ہر دور کا وہم یا ہر دور کا بعید امکان کسی مباح کام کو حرام نہیں بناتا۔ معتبر مفسدت، سبب اور نتیجے کا مضبوط تعلق، غالب وقوع، اور ممانعت کی متناسب صورت ضروری ہے۔","مثلاً عام حالت میں ہتھیار بیچنا جائز ہوسکتا ہے، مگر فتنہ کے وقت ایسے شخص کو فروخت کرنا جو اسے ناحق قتل میں استعمال کرے گا، ممنوع ہوگا۔ یہ حرمت وسیلے کے فساد آفرین استعمال سے پیدا ہوئی ہے۔"],"definitions":[],"originalNumber":39},{"number":40,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":24,"chapter_title":"عمل اہل مدینہ اور دیگر مختلف فیہ اصول","question":"عملِ اہلِ مدینہ کی مالکی اصول میں کیا حیثیت ہے، اور اس کی حجیت کی بنیاد کیا ہے؟","answer":["مالکی اصول میں عملِ اہلِ مدینہ کی سب صورتیں برابر نہیں۔ وہ عمل جو نبوی دور سے مسلسل نقل شدہ ہو، جیسے عملی مقدار یا معروف عبادتی طریقہ، اجتہادی مقامی عمل سے زیادہ مضبوط سمجھا جاتا ہے۔ مقامی علماء کے کسی انتظامی یا اجتہادی اتفاق کو فوراً امت کا اجماع کہنا غلط ہے۔ اختلاف کی صورت میں عمل کی نوعیت، نقل، زمانہ اور مقابل روایت کی قوت الگ دیکھی جاتی ہے۔","عمل اہل مدینہ سے مراد وہ دینی طریقہ، مسلسل عملی روایت یا اجتماعی فقہی رویہ ہے جو مدینہ منورہ کے اہل علم کے ہاں رائج رہا۔ اصولیین یہ تحقیق کرتے ہیں کہ ایسا عمل کب سنت کی مضبوط روایت سمجھا جائے، کب اجتہادی ترجیح ہو، اور کب محض مقامی عرف کی حیثیت رکھتا ہو۔","اس عنوان کو صرف «اہل مدینہ کا اتفاق» کہنا کافی نہیں۔ اس میں عمل کی نوعیت، زمانہ، ناقلین، استمرار اور نبی اکرم ﷺ سے تعلق سب دیکھے جاتے ہیں۔ کبھی عمل نسل در نسل کسی عبادت کی عملی صورت منتقل کرتا ہے، جیسے صاع و مد کی مقدار یا اذان کا معروف طریقہ۔ کبھی مدینہ کے فقہاء کسی نئے مسئلے میں اجتہاد کرکے ایک رائے اختیار کرتے ہیں۔ دونوں کی علمی قوت برابر نہیں۔","اہل مدینہ کے عمل کی ایک قسم منقول اور وراثتی سنت ہے، جبکہ دوسری اجتہاد اور استدلال سے پیدا ہونے والا فقہی عمل ہے۔","مالکی اصول میں بالخصوص قدیم اور منقول عمل کو بہت بلند مقام حاصل ہے۔ دوسرے مذاہب بھی متواتر عملی سنت کی قوت تسلیم کرتے ہیں، مگر صرف مدینہ کے بعد کے فقہی اتفاق کو پوری امت پر لازم دلیل نہیں مانتے۔ اس لیے «عمل اہل مدینہ» ایک ہی درجے کی دلیل نہیں، بلکہ مختلف نوعیتوں کا مجموعہ ہے۔","امام مالک رحمہ اللہ کے نزدیک اہلِ مدینہ کا مسلسل اور اجماعی عمل، خصوصاً ان معاملات میں جن کا تعلق نبی کریم ﷺ کے دور سے چلا آ رہا ہو، سنت کی ایک قوی قسم سمجھا جاتا ہے، کیونکہ مدینہ کے باشندے نبی کریم ﷺ کی سیرت کے سب سے قریبی گواہ تھے۔ اگر کوئی خبرِ آحاد اہلِ مدینہ کے مسلسل عمل سے متصادم ہو، تو امام مالک بعض صورتوں میں عملِ اہلِ مدینہ کو ترجیح دیتے ہیں، جو مالکی مکتب کی ایک امتیازی خصوصیت ہے۔"],"definitions":[],"originalNumber":40},{"number":41,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":17,"chapter_title":"استحسان","question":"قیاس اور استحسان کے باہمی تعلق کو حنفی منہج کی روشنی میں کیسے سمجھا جا سکتا ہے؟","answer":["حنفی منہج میں قیاس اور استحسان دو بے تعلق راستے نہیں۔ کبھی ظاہر قیاس ایک حکم بتاتا ہے، مگر زیادہ قوی اثر یا خفی قیاس دوسری صورت کا تقاضا کرتا ہے۔ استحسان اسی قوی بنیاد کو ترجیح دیتا ہے۔ نور الأنوار میں پرندوں کے جھوٹے کی مثال کے ذریعے جلی مشابہت اور خفی مؤثر فرق واضح کیا گیا ہے۔ فیصلہ صرف ظاہر اور خفی کے نام سے نہیں، دلیل کی قوت اور اثر سے ہوتا ہے۔","قیاس مشترک علت کی بنا پر نئے مسئلے کو منصوص اصل سے ملاتا ہے۔ استحسان اس وقت ظاہر قیاس کو ترک کرتا ہے جب نص، اجماع، ضرورت، عرف یا زیادہ قوی پوشیدہ قیاس بہتر حکم کی طرف رہنمائی کرے۔","کنویں یا حوض کی طہارت اور بعض اجارہ کے مسائل میں عمومی قیاس کے مقابل ضرورت و تعامل کو وزن دینے کی مثالیں حنفی کتب میں ملتی ہیں۔ استحسان خواہش کا نام ہوتا تو وہ دلیل نہ بنتا۔ سرخسیؒ نے اسے قوی دلیل کے سبب قیاس سے عدول کے طور پر واضح کیا۔","حنفی منہج کی شناخت صرف قیاس یا رائے سے نہیں ہوتی؛ یہ قرآن، سنت، اجماع، قولِ صحابی، قیاس، استحسان، عرف اور منضبط دلالاتِ نص کے مربوط استعمال پر قائم ہے۔ عراق کے علمی ماحول اور عملی مسائل کی کثرت نے فرضی و تطبیقی فقہ کے ارتقا میں بھی کردار ادا کیا۔"],"definitions":[],"originalNumber":41},{"number":42,"unit_id":4,"unit_name":"یونٹ چہارم","unit_title":"مختلف فیہ اور تکمیلی مصادر","chapter_number":24,"chapter_title":"عمل اہل مدینہ اور دیگر مختلف فیہ اصول","question":"مختلف فیہ مصادر کے استعمال میں مذاہب کے اختلاف سے فقہی نتائج میں تنوع کیوں پیدا ہوتا ہے؟","answer":["اختلاف صرف کسی اضافی دلیل کو ماننے یا نہ ماننے سے پیدا نہیں ہوتا؛ ایک ہی دلیل کی تعریف، شرائط اور وزن میں فرق بھی مؤثر ہے۔ استحسان کا رد بعض اوقات بے دلیل پسند کا رد ہوتا ہے، جبکہ دوسرے مکتب کا معتبر استحسان نص یا قوی قیاس پر قائم ہوتا ہے۔ اس لیے پہلے یہ متعین کرنا چاہیے کہ اختلاف اصطلاح میں ہے یا واقعی حجیت میں۔ ہر مذہب کے اندر مختلف اقوال بھی ملحوظ رہیں۔","جیسا کہ پہلے بیان ہوا، حنفی مکتب استحسان کو وسیع پیمانے پر استعمال کرتا ہے جبکہ مالکی و حنبلی مکتب مصالحِ مرسلہ کو زیادہ اہمیت دیتے ہیں، اور شافعی مکتب ان دونوں کے استعمال میں نسبتاً زیادہ احتیاط برتتا ہے۔ اسی فرق کی بنا پر معاملات کے متعدد مسائل میں مختلف مذاہب مختلف نتائج پر پہنچتے ہیں، خصوصاً ان مسائل میں جہاں ظاہری قیاس اور عملی مصلحت کے مابین تصادم ہو۔","جب فقہاء عام، خبرِ واحد، قولِ صحابی یا مفہومِ مخالف کی حجیت و قوت مختلف سمجھیں تو متعلق فروع کے نتائج بھی بدل سکتے ہیں۔ ہر فرعی اختلاف لازماً اصولی اختلاف سے نہیں، مگر بہت سے منظم اختلافات اس سے واضح ہوتے ہیں۔","مثلاً شافعیہ مفہومِ مخالف کو شرائط کے ساتھ حجت مانتے ہیں، جبکہ احناف اس کے استعمال میں زیادہ محدود ہیں۔ اس فرق سے بعض مقداروں یا شرطوں سے متعلق نصوص کے فروعی احکام بدل سکتے ہیں۔ اصل مقدمہ معلوم ہو تو اختلاف محض متضاد فتووں کے بجائے قابلِ فہم استدلال بن جاتا ہے۔"],"definitions":[],"originalNumber":42},{"number":43,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":25,"chapter_title":"مقاصد شریعت تعارف اور اہمیت","question":"مقاصدِ شریعت کی جامع تعریف کیا ہے، اور اصولِ فقہ میں ان کی ضرورت کیوں پیش آتی ہے؟","answer":["مقاصد وہ معتبر غایات ہیں جن کا تعلق شریعت کے عمومی یا خصوصی احکام سے ہے۔ انہیں محض اچھے ارادے یا جدید پسندیدہ اقدار کے نام پر ثابت نہیں کیا جاتا؛ نصوص، علل اور استقراء ان کی بنیاد ہیں۔ ان سے نئی صورت کی معنویت، حقوق کا تعلق اور ترجیح کے پہلو واضح ہوتے ہیں۔ مگر کسی مقصد کی نسبت اور اس سے اخذ ہونے والا خاص حکم الگ استدلال چاہتے ہیں۔","مقاصد شریعت سے مراد وہ اعلیٰ غایات، معانی اور حکمتیں ہیں جنہیں اللہ تعالیٰ نے احکام کے ذریعے حاصل کرنا چاہا ہے۔ یہ مقاصد انسان کے دین و دنیا کی اصلاح، عدل کے قیام، رحمت کے فروغ، مصالح کے حصول اور مفاسد کے دفع سے متعلق ہیں۔","عمومی مقاصد وہ معانی اور حکمتیں ہیں جنہیں شارع نے پوری شریعت یا اس کے بیشتر احکام میں ملحوظ رکھا ہے۔","اس تعریف میں صرف کسی ایک حکم کی جزوی حکمت شامل نہیں۔ عدل، آسانی، انسانی ذمہ داری، حقوق کا تحفظ اور معاشرتی استحکام جیسے وسیع اصول بھی مقاصد ہیں۔ اسی طرح نماز میں ذکرِ الٰہی، روزے میں تقویٰ اور زکوٰۃ میں تزکیہ و معاشی تعاون جیسے خاص مقاصد بھی ہوتے ہیں۔","مقاصد تین سطحوں پر سمجھے جاتے ہیں: عمومی مقاصد جو پوری شریعت میں جاری ہیں؛ خصوصی مقاصد جو معاملات، خاندان یا سزاؤں جیسے کسی باب سے متعلق ہیں؛ اور جزوی مقاصد جو ایک خاص حکم میں پائے جاتے ہیں۔","مقاصد انسانی خواہشات کا نام نہیں۔ ان کا ثبوت قرآن، سنت، ثابت علل، احکام کے استقراء اور معتبر اصولی طریقوں سے ہوتا ہے۔ اسی وجہ سے مقاصد شریعت نصوص کے تابع علمی علم ہیں، آزاد فلسفیانہ اندازہ نہیں۔","مقاصد سے مراد تشریع کی وہ معتبر غایات اور حکمتیں ہیں جو نصوص اور منضبط استقراء سے معلوم ہوں۔ جدید اصطلاحی تعریف کو ان دو ابتدائی حنفی کتابوں کا لفظی اقتباس نہیں کہا جاسکتا۔ یہاں مفہوم اردو میں بیان کیا گیا ہے؛ مقاصد کا عنوان کسی پسندیدہ معاشرتی نتیجے کو دلیل کے بغیر شریعت سے منسوب کرنے کی اجازت نہیں دیتا۔"],"definitions":[{"studyQuestion":43,"term":"المناسب (آمدی کی تعبیر)","arabic":"الْمُنَاسِبَ عِبَارَةٌ عَنْ وَصْفٍ ظَاهِرٍ مُنْضَبِطٍ يَلْزَمُ مِنْ تَرَتُّبِ الْحُكْمِ عَلَى وَفْقِهِ حُصُولُ مَا يَصْلُحُ أَنْ يَكُونَ مَقْصُودًا مِنْ شَرْعِ ذَلِكَ الْحُكْمِ","translation":"مناسب وہ ظاہر و منضبط وصف ہے جس پر حکم کے مرتب ہونے سے وہ مقصد حاصل ہو جائے جو اس حکم کی مشروعیت کا ہو سکتا ہے۔","explanation":"تلویح اسے آمدی کی تعبیر کے طور پر نقل کرتی ہے اور بتاتی ہے کہ مقصود منفعت لانا بھی ہو سکتا ہے اور مفسدہ دور کرنا بھی؛ مثال: قصاص میں مقصود بقائے نفوس ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"المناسب","url":"https://shamela.ws/book/9508/558"},"kind":"definition","originalStudyQuestion":43}],"originalNumber":43},{"number":44,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":26,"chapter_title":"مقاصد شریعت کی بنیادی کلیات","question":"ضروریاتِ خمسہ کون سی ہیں، اور انہیں شریعت کے بنیادی مقاصد کیوں کہا جاتا ہے؟","answer":["دین، جان، عقل، نسل اور مال کی حفاظت ضروریاتِ خمسہ کا معروف خلاصہ ہے۔ ان کا تحفظ صرف ممانعت یا سزا سے نہیں؛ عبادت، تعلیم، علاج، خاندان، کسبِ معاش اور انصاف کے مثبت احکام بھی اس میں شامل ہیں۔ بعض اہلِ علم عرض یا عزت کی حفاظت کو الگ عنوان دیتے ہیں۔ پانچ کلیات شریعت کی اہم ضروری مصالح کا بیان ہیں؛ ان سے تمام اخلاقی، اجتماعی اور جزوی مقاصد ختم نہیں ہوجاتے۔","ضروریات خمس ان پانچ بنیادی کلیات کا نام ہے جن کے بغیر انسانی اور اجتماعی زندگی کا درست نظام قائم نہیں رہ سکتا۔ یہ دین، جان، عقل، نسل اور مال کا تحفظ ہیں۔ ان میں شدید خلل پیدا ہو تو صرف ایک فرد نہیں، پورا معاشرتی نظم فساد اور بے اعتدالی کا شکار ہوجاتا ہے۔","شریعت انسانوں کے لیے پانچ بنیادی چیزوں کی حفاظت چاہتی ہے: ان کا دین، جان، عقل، نسل اور مال۔","ضرورت سے مراد محض سہولت یا پسندیدہ فائدہ نہیں۔ ضروری مصلحت وہ ہے جس کے ضائع ہونے سے دین و دنیا کا بنیادی نظام بگڑتا ہے۔ حاجی مصلحت مشقت کم کرتی ہے، جبکہ تحسینی مصلحت اخلاق، پاکیزگی اور حسنِ معاشرت کو مکمل کرتی ہے۔","ان کلیات کی حفاظت دو رخوں سے ہوتی ہے۔ «جانبِ وجود» میں وہ احکام آتے ہیں جو کسی قدر کو قائم اور مضبوط کرتے ہیں؛ مثلاً عبادت، تعلیم، نکاح، تجارت اور علاج۔ «جانبِ عدم» میں وہ احکام آتے ہیں جو اسے ضائع ہونے سے بچاتے ہیں؛ مثلاً قتل، نشہ، زنا، چوری اور دھوکے کی ممانعت۔","ضروریات خمس الگ الگ خانے نہیں۔ تعلیم عقل کے ساتھ دین اور مال کو بھی محفوظ کرتی ہے۔ خاندان نسل کے ساتھ جان، اخلاق اور معاشی ذمہ داری کی حفاظت کرتا ہے۔ اس لیے مقاصدی فہم میں ان کے باہمی تعلق کو بھی دیکھا جاتا ہے۔"],"definitions":[],"originalNumber":44},{"number":45,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":27,"chapter_title":"مقاصد کی اقسام اور درجات","question":"ضروریات، حاجیات اور تحسینیات میں کیا فرق ہے؟","answer":["ضروری مصلحت بنیادی نظام کو محفوظ کرتی ہے، حاجی مصلحت غیر معمولی تنگی دور کرتی ہے، اور تحسینی مصلحت آداب، پاکیزگی اور حسن کو مکمل کرتی ہے۔ کسی عمل کا درجہ اس کے خاص پہلو اور حالت سے بدل سکتا ہے۔ طہارت کو پورے طور پر محض تحسینی کہنا درست نہیں؛ نماز کے لیے ضروری شرطِ طہارت اور زائد صفائی کے آداب الگ ہیں۔ اس تقسیم میں عمل کے نام سے زیادہ اس کا متعلق فائدہ اور فقدان کا اثر دیکھا جاتا ہے۔","یہ تقسیم مصلحت کی اہمیت اور اس کے ضائع ہونے کے اثرات کے لحاظ سے کی جاتی ہے۔ ضروری مقصد وہ ہے جس کے بغیر دین یا دنیا کا بنیادی نظام قائم نہ رہے۔ حاجی مقصد وہ ہے جس کے فقدان سے نظام ختم نہیں ہوتا، مگر عمومی مشقت، تنگی اور دشواری پیدا ہوتی ہے۔ تحسینی مقصد زندگی کو اخلاقی حسن، پاکیزگی، وقار اور بہتر آداب عطا کرتا ہے۔","ضروریات میں دین، جان، عقل، نسل اور مال کا بنیادی تحفظ شامل ہے۔ حاجیات کی مثال سفر میں قصر، بیماری میں روزے کی رخصت، سلم و اجارہ جیسے ایسے معاملات ہیں جو لوگوں کی حقیقی ضرورت آسان کرتے ہیں۔ تحسینیات میں طہارت، لباس کا وقار، کھانے کے آداب، نرمی اور معاملات میں حسنِ سلوک آتے ہیں۔","ضروری مقصد بنیاد ہے؛ حاجی اور تحسینی مقاصد اسے سہارا دیتے اور مکمل کرتے ہیں۔ اس لیے نچلا درجہ بے اہم نہیں، مگر وہ بلند درجے کو تباہ کرکے محفوظ نہیں کیا جاسکتا۔","ایک ہی عمل مختلف حالات میں مختلف درجے اختیار کرسکتا ہے۔ پانی پینا معمول میں حاجی یا عادی ضرورت ہے، مگر شدید پیاس میں جان بچانے کے لیے ضروری ہوجاتا ہے۔ مناسب لباس عام حالات میں تحسینی ہوسکتا ہے، مگر ستر پوشی اور موسم سے جان بچانا ضروری درجے میں داخل ہوسکتا ہے۔","اس تقسیم کا مقصد صرف نام رکھنا نہیں، بلکہ ترجیح اور رخصت کا معیار دینا ہے۔ جب دو مصالح جمع نہ ہوسکیں تو ان کے اثر، عموم، یقین اور مرتبے کو دیکھ کر فیصلہ کیا جاتا ہے۔"],"definitions":[],"originalNumber":45},{"number":46,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":25,"chapter_title":"مقاصد شریعت تعارف اور اہمیت","question":"مقاصدِ شریعت کا تصور قرآن و سنت اور استقراء سے کس طرح اخذ کیا جاتا ہے؟","answer":["مقاصد کی معرفت صریح نص، حکم کے ساتھ بیان کردہ علت، متعلقہ احکام کے مجموعی مطالعے اور معتبر استقراء سے ہوتی ہے۔ استقراء میں صرف موافق مثالیں جمع کرنا کافی نہیں؛ بظاہر مختلف احکام کی وجہ بھی سمجھنی ہوتی ہے۔ رفعِ حرج کی متعدد نصوص عمومی مقصد واضح کرتی ہیں، مگر ہر واجب کی معمول کی محنت ختم نہیں کرتیں۔ مقصد کی قوت اس کے شواہد کے مجموعے سے متعین ہوگی، صرف ایک پسندیدہ نتیجے سے نہیں۔","استقراء سے مراد قرآن و سنت کے متعدد جزئی احکام کا وسیع مطالعہ کر کے ان میں مشترک حکمت اور مقصود کو تلاش کرنا ہے۔ چونکہ مقاصدِ شریعت کسی ایک آیت یا حدیث میں مکمل طور پر بیان نہیں ہوئے بلکہ متعدد نصوص کے مجموعی مطالعے سے سامنے آتے ہیں، اسی لیے استقرائی طریقہ مقاصد کی معرفت کا بنیادی اور معتبر ترین ذریعہ سمجھا جاتا ہے، جیسا کہ امام شاطبی نے اپنے منہج میں اس پر خصوصی زور دیا۔","الفاظ حکم کا دروازہ ہیں، مگر سیاق، علت اور مقصد اس حکم کا صحیح محل واضح کرتے ہیں۔ صرف الگ لفظ کو دیکھنے سے کبھی عام کو خاص، وسیلے کو مقصد، یا وقتی انتظام کو ابدی قاعدہ سمجھ لیا جاتا ہے۔ مقاصدی نظر نص کے ظاہر کو ترک نہیں کرتی؛ وہ ظاہر کو پوری شریعت کے نظم میں پڑھتی ہے۔","قرآن نے فرمایا: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ (البقرۃ: 185)۔","اللہ تمہارے لیے آسانی چاہتا ہے، دشواری نہیں چاہتا۔ یہ آیت روزے کی رخصت کے سیاق میں ہے، مگر شریعت کے عمومی مزاج کی بھی رہنمائی کرتی ہے۔ اس سے یہ نتیجہ نہیں نکلتا کہ ہر مشکل حکم چھوڑ دیا جائے؛ بلکہ مشروع رخصت، استطاعت اور رفعِ حرج کو صحیح جگہ سمجھا جائے۔","مقاصدی فہم تین غلطیوں سے بچاتا ہے۔ پہلی، جزوی نص کو دیگر نصوص سے کاٹ دینا۔ دوسری، حکم کی علت بدلے بغیر صرف ظاہری مشابہت سے نئی صورت پر حکم لگا دینا۔ تیسری، ذاتی پسند کو «مقصد» کہہ کر الفاظ کی معتبر دلالت ختم کردینا۔","مثلاً مالی معاہدے میں صرف «رضامندی» کافی نہیں اگر دھوکا، شدید جہالت یا استحصال موجود ہو۔ نصوص کی مجموعی غایت رضامندی کے ساتھ عدل اور مال کا تحفظ بھی ہے۔","صحیح ترتیب یہ ہے: زبان اور سیاق سے نص سمجھا جائے، متعلقہ نصوص جمع کیے جائیں، علت و مآل دیکھا جائے، پھر ثابت مقصد کی روشنی میں تطبیق کی جائے۔"],"definitions":[],"originalNumber":46},{"number":47,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":25,"chapter_title":"مقاصد شریعت تعارف اور اہمیت","question":"اصولِ فقہ اور مقاصدِ شریعت کا باہمی تعلق کیا ہے، اور صرف مقاصد کا حوالہ کافی کیوں نہیں؟","answer":["اصول فقہ دلیل کی حجیت، دلالت اور استنباط کا طریقہ منظم کرتا ہے؛ مقاصد اسی استنباط کو شریعت کی معتبر غایات سے مربوط رکھتے ہیں۔ مقاصد کی معرفت بھی اصولی تحقیق چاہتی ہے۔ مثال کے طور پر حفظِ مال تجارت کی اجازت، دھوکے کی ممانعت اور حقوق کے تحفظ کو یکجا سمجھنے میں مدد دیتا ہے۔ مگر اسی عنوان سے ہر منافع بخش عقد جائز نہیں ہوجاتا؛ ربا، غرر اور ملکیت کی شرائط الگ تحقیق طلب ہیں۔","قرآن نے فرمایا: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ (البقرۃ: 185)۔","اصول کسی دلیل کی حجیت، الفاظ کی دلالت اور استنباط کی شرائط متعین کرتا ہے؛ مقاصد مجموعی تشریعی حکمت اور درست تطبیق میں رہنمائی دیتے ہیں۔ دونوں کو جمع کرنے کی مثال قرض کا معاملہ ہے: مقصود تنگ دست کی مدد ہے، مگر سودی شرط کو صرف مدد کے عنوان سے درست نہیں کہا جاسکتا۔ اسی طرح کسی مباح معاملے میں حقیقی ضرر معلوم ہو تو متعلقہ دلائل، ضرر کی نوعیت اور جائز متبادل دیکھے جائیں گے۔ مقصد کی صحت طریقے کی صحت سے بے نیاز نہیں کرتی۔"],"definitions":[],"originalNumber":47},{"number":48,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":28,"chapter_title":"مصلحت، مفسدت اور مآلاتِ افعال","question":"کیا مصلحت کو نص کے مقابل استعمال کیا جا سکتا ہے؟ مقاصدی اجتہاد کی حدود واضح کریں۔","answer":["کسی ثابت قطعی حکم کو محض مصلحت کے دعوے سے ختم نہیں کیا جاسکتا۔ ظنی الدلالہ نص میں معتبر تفسیر، تخصیص یا محلِ اطلاق کی تحقیق ہوسکتی ہے، مگر وہ بھی دلیل کی پابند ہے۔ ضرورت کی رخصت خود شرعی دلیل سے ثابت ہوتی ہے؛ اسے مصلحت کے ذریعے نص کی شکست کہنا غلط ہے۔ پہلے مصلحت کا ثبوت، پھر حکم کا درجہ اور پھر نص کے ساتھ اس کا حقیقی تعلق متعین کیا جاتا ہے۔","مصالحِ مرسلہ، جو ایک ثانوی اصولی مصدر ہے، اسی وقت معتبر مانی جاتی ہیں جب وہ کلیاتِ خمسہ میں سے کسی ایک کے تحفظ سے ہم آہنگ ہوں اور کسی قطعی نص سے متصادم نہ ہوں۔ اس طرح مقاصدِ شریعت مصالحِ مرسلہ کے قبول یا رد کیے جانے کا بنیادی معیار فراہم کرتے ہیں، اور یہی وجہ ہے کہ ان دونوں مباحث کو ایک دوسرے کا لازمی معاون سمجھا جاتا ہے۔","درء مفاسد کو اس وقت مقدم کیا جاتا ہے جب ایک ہی فعل میں مصلحت اور مفسدت اس طرح جمع ہوں کہ دونوں کو الگ کرنا ممکن نہ ہو، مفسدت معتبر اور غالب ہو، اور اس کا درجہ حاصل ہونے والی مصلحت کے برابر یا اس سے بلند ہو۔ اسی موقع پر قاعدہ «دَرْءُ الْمَفَاسِدِ مُقَدَّمٌ عَلَى جَلْبِ الْمَصَالِحِ» رہنمائی کرتا ہے۔","یہ قاعدہ مطلق نہیں۔ اگر مصلحت کہیں زیادہ یقینی اور عظیم ہو، جبکہ مفسدت محدود اور ناگزیر ہو، تو مصلحت کو اختیار کیا جاسکتا ہے۔ جراحی میں محدود جسمانی تکلیف بڑے مرض سے نجات کے لیے برداشت کی جاتی ہے۔ جہاد، حدود، گواہی اور بعض علاج میں بھی وقتی ضرر کسی بلند اور منضبط مصلحت کے تابع ہوسکتا ہے۔","حدیث میں نبی کریم ﷺ نے سیدہ عائشہؓ سے فرمایا: «لَوْلَا أَنَّ قَوْمَكِ حَدِيثُو عَهْدٍ بِجَاهِلِيَّةٍ لَأَمَرْتُ بِالْبَيْتِ فَهُدِمَ» (صحیح البخاری)۔","کعبہ کو بنیادِ ابراہیمی پر تعمیر کرنا مصلحت تھی، مگر نومسلم لوگوں کے دلوں میں پیدا ہونے والی شدید غلط فہمی کے اندیشے سے یہ اقدام مؤخر کردیا گیا۔ یہاں مصلحت رد نہیں ہوئی؛ ناموافق وقت میں بڑی مفسدت سے بچنے کے لیے اس کا حصول روکا گیا۔","صحیح تطبیق کے لیے مفسدت کی حقیقت، احتمال، شدت اور متبادل جانچے جائیں۔ محض یہ کہنا کہ کسی کام میں کچھ نقصان ہے، کافی نہیں؛ ورنہ ہر مفید اصلاح روکی جاسکتی ہے۔ قاعدہ خطرے اور فائدے کے منضبط موازنے کا نام ہے، تبدیلی سے خوف کا نہیں۔"],"definitions":[],"originalNumber":48},{"number":49,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":28,"chapter_title":"مصلحت، مفسدت اور مآلاتِ افعال","question":"مآلاتِ افعال سے کیا مراد ہے، اور کسی حکم کے نتائج کو دیکھنا اصولی استدلال میں کیوں اہم ہے؟","answer":["مآلات میں عمل کے متوقع نتائج کو معتبر شواہد کی بنیاد پر دیکھا جاتا ہے۔ مصلحت موجودہ فائدے کا اور مآل اس اقدام کے آئندہ اثرات کا سوال بھی ہوسکتا ہے۔ کسی قانونی اجازت سے کمزور فریق کا استحصال غالب طور پر بڑھے تو حفاظتی شرطیں زیر بحث آسکتی ہیں۔ نتائج کا لحاظ قطعی حکم کو منسوخ نہیں کرتا؛ وہ اجازت کی صورت، تنفیذ، وقت اور احتیاط کو متاثر کرسکتا ہے۔ محض خوف کافی دلیل نہیں۔","مآلات افعال سے مراد یہ دیکھنا ہے کہ کسی قول، فعل، فتویٰ، عدالتی فیصلے یا پالیسی کا انجام عملاً کیا نکلے گا۔ یہ انجام فوری یا دور رس، براہِ راست یا بالواسطہ، مقصود یا غیر مقصود ہوسکتا ہے۔ شرعی اجتہاد صرف عمل کی ظاہری صورت نہیں دیکھتا؛ وہ اس کے غالب نتائج کو بھی حکم کے ساتھ جوڑتا ہے۔","افعال کے انجام کو دیکھنا شریعت میں معتبر اور مطلوب ہے، خواہ زیرِ بحث فعل اپنی اصل کے اعتبار سے جائز ہو یا ناجائز۔ ایک جائز فعل اگر خاص حالت میں بڑی مفسدت پیدا کرے تو اس کی اجازت محدود ہوسکتی ہے۔ اسی طرح کسی ممنوع امر سے بچنے کا ایسا طریقہ بھی درست نہیں ہوگا جو اس سے برابر یا بڑی مفسدت پیدا کردے۔","قرآن نے فرمایا: ﴿وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ﴾ (الأنعام: 108)۔ باطل معبودوں کی مذمت اپنی جگہ درست تھی، مگر جب اس انداز کا غالب نتیجہ اللہ تعالیٰ کی شان میں گستاخی بننے لگا تو اس مخصوص طرز سے روک دیا گیا۔","مآل کا اعتبار قیاس آرائی نہیں۔ اس کے لیے سبب اور نتیجے کا معقول تعلق، معتبر تجربہ، عرف، سابق واقعات، ماہرین کی رائے اور وقوع کا قابلِ اعتماد امکان درکار ہے۔ نادر وہم سے حکم نہیں بدلتا، لیکن غالب اور سنگین نتیجہ نظر انداز بھی نہیں کیا جاتا۔"],"definitions":[],"originalNumber":49},{"number":50,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":28,"chapter_title":"مصلحت، مفسدت اور مآلاتِ افعال","question":"درء مفاسد اور جلب مصالح میں تعارض ہو تو ترجیح کا اصول کیا ہوگا؟","answer":["جب فائدہ اور نقصان جمع ہوں تو پہلے ایسا متبادل تلاش کیا جاتا ہے جو فائدہ محفوظ اور نقصان کم کرے۔ اگر ایسا ممکن نہ ہو تو مقدار، احتمال، شرعی درجہ اور متاثر حقوق کا موازنہ ہوتا ہے۔ درء مفاسد کی ترجیح ایک رہنما قاعدہ ہے، ہر معمولی نقصان کے مقابل ہر بڑی مصلحت کی نفی نہیں۔ جراحی کا محدود ضرر بڑی بیماری کے دفع کے لیے برداشت کیا جاتا ہے، بشرطیکہ طبی اندازہ اور دیگر شرائط معتبر ہوں۔","حدیث میں نبی کریم ﷺ نے سیدہ عائشہؓ سے فرمایا: «لَوْلَا أَنَّ قَوْمَكِ حَدِيثُو عَهْدٍ بِجَاهِلِيَّةٍ لَأَمَرْتُ بِالْبَيْتِ فَهُدِمَ» (صحیح البخاری)۔","موازنے میں پہلے نص سے متعین حق اور واجب کو محفوظ کریں، پھر فائدے اور نقصان کے یقین، شدت، عموم اور مدت کو جانچیں۔ معمولی ممکن نقصان کے مقابل بڑی یقینی مصلحت ترک کرنا لازم نہیں، جبکہ محدود فائدے کے لیے شدید اجتماعی ضرر قبول نہیں کیا جاسکتا۔ علاج میں وقتی تکلیف اور متوقع شفا کا تقابل اسی ضابطے کی مثال ہے۔ اگر دونوں مطلوب مصالح پوری ہوسکتی ہوں تو بلا ضرورت ایک کو ساقط کرنا ترجیح کا صحیح استعمال نہیں؛ اور اگر ثبوت ناکافی ہو تو مزید تحقیق کی جائے۔"],"definitions":[],"originalNumber":50},{"number":51,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":27,"chapter_title":"مقاصد کی اقسام اور درجات","question":"اگر مختلف مقاصد باہم متعارض ہوں تو ترجیح کس اصول پر قائم ہوگی؟","answer":["ترجیح میں مقصد کے درجے کے ساتھ دلیل کی قوت، نقصان کی شدت، عموم، مدت اور متبادل بھی دیکھے جاتے ہیں۔ کسی عمومی فائدے کے نام پر فرد کے ثابت حق کو بلا حد ختم نہیں کیا جاسکتا۔ کبھی ضروری مقصد کے حصول کا کم نقصان والا راستہ دستیاب ہوتا ہے؛ تب زیادہ نقصان اختیار نہیں ہوگا۔ ضروریاتِ خمسہ کی ترتیب ایک میکانکی فہرست نہیں جسے ہر واقعے پر یکساں لگادیا جائے؛ جزوی صورت کی تحقیق لازم ہے۔","ضروریات خمس میں حقیقی تعارض کم ہوتا ہے؛ اکثر مسئلہ کسی خاص صورت میں دو مصالح کے درجات یا وسائل کے ٹکراؤ کا ہوتا ہے۔ ترجیح صرف ایک جامد فہرست دیکھ کر نہیں دی جاتی۔ پہلے ہر مصلحت کی نوعیت، دلیل، وسعت، یقینیّت اور متوقع نقصان معلوم کیا جاتا ہے۔","اہم معیار یہ ہیں: قطعی کو ظنی پر، ضروری کو حاجی و تحسینی پر، عمومی مصلحت کو مناسب شرائط کے ساتھ محدود مصلحت پر، بڑے اور ناقابلِ تلافی نقصان کے دفع کو معمولی نقصان پر، اور قریب و غالب نتیجے کو دور و موہوم اندیشے پر ترجیح دی جائے۔ ساتھ یہ بھی دیکھا جائے کہ دونوں مقاصد کو جمع کرنے کا کوئی متبادل راستہ موجود ہے یا نہیں۔","اصولی ضابطہ ہے: «يُرْتَكَبُ أَخَفُّ الضَّرَرَيْنِ لِدَفْعِ أَعْظَمِهِمَا»۔","جب دو نقصانات سے مکمل بچاؤ ممکن نہ ہو تو بڑے نقصان کو روکنے کے لیے کم نقصان برداشت کیا جاتا ہے۔ مگر نقصان کی مقدار اندازے سے نہیں، معتبر شہادت اور اہلِ خبرہ کی رائے سے متعین ہوگی۔","مثلاً متعدی وبا میں اجتماعِ عام کو عارضی طور پر محدود کرنا بظاہر بعض دینی اجتماعات پر اثر ڈالتا ہے، مگر جانوں کا غالب خطرہ اور خود شریعت کی دی ہوئی رخصت اس محدود اقدام کو درست کرسکتی ہے۔ اس کے برعکس محض معمولی اندیشے سے عبادت یا بنیادی حق کو غیر معینہ مدت تک معطل نہیں کیا جاسکتا۔","ترجیح کا درست فیصلہ درجاتِ مقصد، حکم کی نوعیت، متاثر افراد، مدت، متبادل، مآل اور واپسی کی امکان پذیری کو جمع کرکے ہوگا۔ اس لیے ایک واقعے کی ترجیح کو ہر زمانے اور ہر صورت کا مستقل قاعدہ نہیں بنایا جاسکتا۔","پہلا مرحلہ حقیقی تعارض کی تحقیق ہے۔ بہت سے مسائل میں دو مقاصد جمع ہوسکتے ہیں یا ٹکراؤ صرف غلط تطبیق سے پیدا ہوتا ہے۔ اس لیے حکم، واقعہ، متاثر افراد اور دستیاب متبادل واضح کیے بغیر ترجیح نہیں دی جاتی۔","دوسرا مرحلہ مرتبہ ہے: ضروری کو حاجی پر، حاجی کو تحسینی پر ترجیح دی جاتی ہے۔ اسی مرتبے کے اندر دلیل کی قطعیت، مصلحت کی وسعت، نقصان کی شدت، وقوع کا امکان، مدت اور تلافی کی صلاحیت دیکھی جاتی ہے۔","تیسرا مرحلہ عمومی اور خصوصی اثر ہے۔ عمومی مصلحت کو بلا شرط فرد کے حق پر غالب نہیں کیا جاتا، مگر بڑے اجتماعی ضرر کو روکنے کے لیے متناسب محدود پابندی ممکن ہے۔ اس میں کمزور طبقے پر منتقل ہونے والے نقصان کو خاص طور پر جانچنا ضروری ہے۔","اصولی قواعد رہنمائی کرتے ہیں: «الضَّرَرُ يُزَالُ»، «الضَّرَرُ الْأَشَدُّ يُزَالُ بِالضَّرَرِ الْأَخَفِّ»، اور «دَرْءُ الْمَفَاسِدِ مُقَدَّمٌ عَلَى جَلْبِ الْمَصَالِحِ»؛ مگر ہر قاعدہ اپنے محل اور شرائط کے ساتھ استعمال ہوگا۔","مثلاً وبا میں اجتماع کی عارضی تنظیم حفظ نفس کی خدمت کرسکتی ہے، لیکن خطرے کی مقدار، مدت، متبادل عبادتی صورت اور حقوق کی مساوی رعایت دیکھنا ہوگی۔ معمولی اندیشے سے غیر معینہ پابندی درست نہیں۔","آخر میں فیصلہ کم سے کم ضرر، زیادہ قابلِ تلافی راستے اور مسلسل جائزے کے ساتھ کیا جاتا ہے۔ ترجیح ایک میکانکی فہرست نہیں، منضبط علمی موازنہ ہے۔"],"definitions":[],"originalNumber":51},{"number":52,"unit_id":5,"unit_name":"یونٹ پنجم","unit_title":"مقاصد شریعت","chapter_number":25,"chapter_title":"مقاصد شریعت تعارف اور اہمیت","question":"امام شاطبیؒ نے مقاصدی منہج کو اصولِ فقہ میں کس طرح منظم کیا، اور الموافقات کی علمی اہمیت کیا ہے؟","answer":["امام شاطبیؒ نے مقاصد کو استقراء، کلی و جزئی دلائل کے ربط، مکلف کے قصد اور احکام کے مآلات کے ساتھ منظم کیا۔ ان سے پہلے جوینیؒ اور غزالیؒ سمیت دوسرے علماء نے بھی مصالح و مقاصد پر بحث کی تھی۔ الموافقات کی خصوصیت ان مباحث کی جامع اصولی تنظیم ہے۔ کتاب کا مقصود جزوی نصوص کو غیر اہم بنانا نہیں، بلکہ شریعت کے کلی مقاصد اور جزوی احکام کو ساتھ سمجھنا ہے۔","امام شاطبی (م ۷۹۰ھ) نے اپنی شہرہ آفاق کتاب الموافقات فی اصول الشریعۃ میں مقاصدِ شریعت کے موضوع کو نہایت گہرائی اور تفصیل کے ساتھ مرتب کیا۔ اگرچہ مقاصد کا تصور ان سے پہلے بھی موجود تھا، مگر شاطبی نے اسے ایک مستقل اور منظم علمی نظام کی شکل دی، جس میں ضروریات، حاجیات اور تحسینیات کی درجہ بندی، اور کلیاتِ خمسہ (حفاظتِ دین، جان، نسل، مال، عقل) جیسے تصورات کو بنیادی حیثیت دی گئی۔ ان کی یہ خدمت معاصر مقاصدی فقہ کی بنیاد سمجھی جاتی ہے۔"],"definitions":[],"originalNumber":52},{"number":53,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":29,"chapter_title":"الفاظ اور دلالات کا تعارف","question":"اصولِ فقہ میں مباحثِ الفاظ اور اصولِ تعبیر کو اتنی بنیادی اہمیت کیوں حاصل ہے؟","answer":["دلالاتِ الفاظ نص کے معنی، دائرے اور قوت کو متعین کرتی ہیں۔ صرف لغت جاننا کافی نہیں؛ شرعی استعمال، سیاق، قرینہ اور دوسری ادلہ بھی اہم ہیں۔ حنفی روایت میں لفظ کی وضع، وضوح، استعمال اور طریقِ استدلال الگ تقسیمیں ہیں۔ خاص و عام کو ظاہر و نص یا عبارت و اشارہ کی جگہ استعمال نہیں کیا جاسکتا۔ ایک عبارت مختلف اعتبارات سے بیک وقت خاص، ظاہر اور عبارت النص ہوسکتی ہے؛ یہ متضاد اوصاف نہیں۔","شریعت کے بنیادی دلائل زبان کے ذریعے ہم تک پہنچے ہیں۔ حکم، ممانعت، عموم، تخصیص، اطلاق، تقیید، حقیقت، کنایہ اور لازمِ کلام کو سمجھے بغیر یہ طے نہیں ہوسکتا کہ نص کیا کہہ رہی ہے، کس سے کہہ رہی ہے اور کن حالات پر اس کا اطلاق ہوگا۔ اسی لیے دلالات کی بحث استنباط کے آلات میں مرکزی مقام رکھتی ہے۔","ایک ہی آیت میں لفظی پہلو بدلنے سے فقہی نتیجہ بدل سکتا ہے۔ ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ﴾ (البقرۃ: 228) میں «قروء» کے معنی پر اختلاف نے عدت کے حساب میں فقہی اختلاف پیدا کیا۔ یہ اختلاف نص سے بے اعتنائی نہیں، بلکہ مشترک لفظ، لغوی شواہد اور متعلقہ احادیث کے وزن میں اختلاف ہے۔","دلالات مجتہد کو تین طرح کی حفاظت دیتی ہیں۔ پہلی، وہ معنی لفظ پر نہ لادا جائے جسے زبان برداشت نہیں کرتی۔ دوسری، محض ظاہری سطح پر رک کر سیاق، اشارے اور مقصد کو ضائع نہ کیا جائے۔ تیسری، مختلف نصوص کو جمع کرکے مضبوط اور منظم حکم اخذ کیا جائے۔","یہ بحث جدید قوانین، معاہدوں اور فتاویٰ میں بھی اتنی ہی اہم ہے۔ ایک تعریف کا دائرہ، استثنا کی جگہ، شرط کا تعلق اور سکوت کا اثر عملی حقوق بدل سکتے ہیں۔ اصولِ دلالت سکھاتے ہیں کہ اچھا فقیہ صرف عبارت نقل نہیں کرتا؛ وہ عبارت کی قوت، حد، احتمال اور عملی محل کو دلیل کے ساتھ واضح کرتا ہے۔"],"definitions":[],"originalNumber":53},{"number":54,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":30,"chapter_title":"عام اور خاص","question":"عام اور خاص میں کیا فرق ہے، اور تخصیصِ عام کے اہم طریقے کون سے ہیں؟","answer":["عام متعدد افراد کو اپنی دلالت کے تحت جمع کرتا ہے، جبکہ خاص متعین معنی، فرد، نوع یا عدد سے متعلق ہوسکتا ہے۔ حنفی اصطلاح میں خاص کا مطلب لازماً صرف ایک شخص نہیں؛ معین عدد بھی خاص ہے۔ تخصیص عام کے بعض افراد کا معتبر دلیل سے اخراج ہے۔ حنفی اصول میں تخصیص کی فنی تعریف اور متصل قیود کی تعبیر جمہور سے مختلف تفصیل رکھتی ہے؛ استثنا، شرط اور نسخ کو مترادف نہیں کرنا چاہیے۔","مثلاً «كل إنسان» ہر انسان کو اور «المؤمنون» اپنے معروف سیاق میں تمام مومن افراد کو شامل کرتا ہے۔ عموم کا تعلق لفظ کی دلالت سے ہے، افراد کی واقعی تعداد سے نہیں۔ اگر کسی وقت اس جنس کا صرف ایک فرد موجود ہو تب بھی لفظ کی ساخت عام ہوسکتی ہے۔","امام غزالی نے معنی کو یوں قریب کیا کہ عام وہ واحد لفظ ہے جو ایک جہت سے دو یا زیادہ چیزوں پر دلالت کرے۔ تعریفوں کے الفاظ مختلف ہیں، مگر اصل عناصر تین ہیں: لفظ میں شمول، افراد کی غیر معین کثرت، اور ایک ہی حیثیت سے ان سب پر دلالت۔","عام کو مطلق سے الگ رکھنا ضروری ہے۔ عام ہر فرد کو شامل کرتا ہے، جبکہ مطلق کسی غیر معین فرد یا ماہیت پر دلالت کرتا ہے۔ «تمام طلبہ کو انعام دو» عام ہے؛ «کسی طالب علم کو انعام دو» مطلق ہے۔ اس فرق سے حکم کی تعمیل، تخصیص اور تقیید کے الگ اصول سمجھ میں آتے ہیں۔","تخصیص کے ذرائع میں قرآن (کوئی دوسری آیت جو عمومی حکم کو محدود کرے)، سنت (کوئی حدیث جو عمومی نص کو مخصوص کرے)، اجماع، قیاس اور عقل شامل ہیں۔ ہر ذریعہ اس بات کا تعین کرتا ہے کہ کیا وہ متصل تخصیص ہے (جو نص کے ساتھ ہی مذکور ہو، جیسے استثناء) یا منفصل تخصیص ہے (جو بعد میں کسی الگ دلیل سے ثابت ہو)۔","§QUOTE§فالخاص لفظ وضع لمعنى معلوم أو لمسمى معلوم على الانفراد","مفہوم: ایک معلوم معنی یا معلوم مسمى کے لیے انفرادی طور پر وضع کیا گیا لفظ۔  حوالہ: اصول الشاشی، فصل الخاص والعام۔","§QUOTE§والعام كل لفظ ينتظم جمعا من الأفراد","مفہوم: عام وہ لفظ ہے جو افراد کے مجموعے کو شامل کرے۔  حوالہ: اصول الشاشی، بحث العام والخاص؛ عبارت کا ابتدائی حصہ۔","متصل مخصص اسی کلام میں ہوتا ہے، جیسے استثناء، شرط اور بعض قیود؛ منفصل مخصص الگ دلیل ہوتا ہے۔ حنفی اصطلاح میں تخصیص کی حد اور اس کے نسخ سے فرق میں دلیل کی استقلال و مقارنت اہم ہیں۔ غیر مخصوص عام کے مقابل خبرِ واحد یا قیاس کا معاملہ حنفی اور جمہور مناہج میں یکساں نہیں۔ لہٰذا ذرائع کی عمومی فہرست کو تمام مذاہب کی بے شرط مشترک ترتیب نہ سمجھیں۔"],"definitions":[{"studyQuestion":54,"term":"الخاص","arabic":"لفظ وضع لمعنى معلوم أو لمسمى معلوم على الانفراد","translation":"ایسا لفظ جو متعین معنی یا مسمى کے لیے انفراد کے طور پر وضع ہو۔","explanation":"خاص صرف ایک شخص نہیں؛ متعین فرد، نوع، جنس یا عدد بھی ہوسکتا ہے۔ اسے عام کے شمول اور مشترک کے مختلف معانی سے الگ رکھیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل الخاص والعام، ص 13","url":"https://shamela.ws/book/6302/1"},"kind":"definition","originalStudyQuestion":58},{"studyQuestion":54,"term":"العام","arabic":"كل لفظ ينتظم جمعاً من الأفراد","translation":"ہر وہ لفظ جو متعدد افراد کو شامل کرے۔","explanation":"عام میں ایک معنی کے افراد کا شمول ہے۔ مطلق کا غیر معین فرد اور مشترک کے مختلف معانی اس سے الگ دلالتیں ہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث العام والخاص، ص 17","url":"https://shamela.ws/book/6302/2"},"kind":"definition","originalStudyQuestion":58},{"studyQuestion":54,"term":"النکرۃ اور المعرفۃ","arabic":"فَهِيَ مَا وُضِعَ لِشَيْءٍ لَا بِعَيْنِهِ عِنْدَ الْإِطْلَاقِ لِلسَّامِعِ وَالْمَعْرِفَةُ مَا وُضِعَ لِمُعَيَّنٍ عِنْدَ الْإِطْلَاقِ لَهُ","translation":"نکرہ وہ ہے جو غیر معین چیز کے لیے وضع ہو، اور معرفہ وہ جو معین کے لیے وضع ہو (سامع کے لحاظ سے)۔","explanation":"تلویح انہی تعریفات سے خاص و عام اور مطلق کے حدود نکالتی ہے۔ ایک لفظ ایک حیثیت سے مشترک اور دوسری حیثیت سے عام ہو سکتا ہے، لیکن بیک وقت عام اور خاص نہیں۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"تقسيم الألفاظ","url":"https://shamela.ws/book/9508/60"},"kind":"definition","originalStudyQuestion":54}],"originalNumber":58},{"number":55,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":31,"chapter_title":"مطلق اور مقید","question":"مطلق اور مقید میں کیا فرق ہے، اور مطلق کو مقید پر محمول کرنے کی بنیادی شرائط کیا ہیں؟","answer":["عام کی شمولی دلالت اور مطلق کی بدلی دلالت الگ ہیں۔ ایک مطلق فرد میں کسی اضافی وصف کی قید بیان نہیں ہوتی، جبکہ مقید میں معتبر وصف مذکور ہوتا ہے۔ مطلق کو مقید پر حمل کرنے میں حکم اور سبب کے اتحاد یا اختلاف کی چار صورتیں زیرِ بحث آتی ہیں۔ اختلافِ سبب و اتحادِ حکم، مثلاً بعض کفارات کی رقبتوں، میں مذاہب مختلف ہیں۔ ہر مقید عبارت تمام مطلق عبارات کی خودکار قید نہیں بنتی۔","مطلق کا مطلب یہ نہیں کہ وہ تمام افراد کو ایک ساتھ شامل کرتا ہے۔ وہ اپنی جنس کے کسی ایک غیر معین فرد سے پورا ہوسکتا ہے۔ اسی بنا پر مطلق اور عام الگ ہیں: عام ہر مناسب فرد کو شامل کرتا ہے، جبکہ مطلق کسی غیر معین فرد یا اصل ماہیت پر دلالت کرتا ہے۔","مستند قرآنی مثال کفارۂ ظہار کی آیت ہے: ﴿فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا﴾ (المجادلۃ: 3)۔ یہاں «رَقَبَةٍ» غلام یا لونڈی آزاد کرنے کی اصل حقیقت پر دلالت کرتا ہے؛ اسی آیت میں ایمان کی صفت مذکور نہیں۔ اس لیے یہ لفظ اپنی عبارت کے اعتبار سے مطلق ہے۔","ایک اور مثال تیمم کی آیت میں ﴿فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ﴾ (المائدۃ: 6) کا لفظ «أَيْدِيكُمْ» ہے۔ آیت نے یہاں ہاتھ کی آخری حد لفظاً بیان نہیں کی۔ یہ مثال آگے اس سوال کو پیدا کرتی ہے کہ کیا وضو میں «إِلَى الْمَرَافِقِ» کی قید تیمم پر بھی منتقل ہوگی یا دونوں احکام اپنے اپنے سیاق میں رہیں گے۔ یوں تعریف فوراً عملی استنباط سے جڑ جاتی ہے۔","جب دو نصوص کا حکم بھی ایک ہو اور سبب بھی ایک، اور ایک نص مطلق جبکہ دوسری اسی موضوع میں مقید ہو، تو اصولیین مطلق کو مقید پر محمول کرتے ہیں۔ دونوں نصوص ایک ہی شرعی واقعے کی وضاحت سمجھی جاتی ہیں؛ مقید نص بتاتی ہے کہ مطلق لفظ سے کون سی متعین صورت مراد ہے۔","اس کی معروف قرآنی مثال خون کی حرمت ہے۔ ایک مقام پر فرمایا: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ﴾ (المائدۃ: 3)، جہاں «الدم» بلا قید آیا۔ دوسرے مقام پر کھانے کی ممنوع چیزوں میں فرمایا: ﴿أَوْ دَمًا مَسْفُوحًا﴾ (الأنعام: 145)، یعنی بہایا ہوا خون۔ دونوں نصوص میں کھانے کی حرمت حکم ہے اور خون بطور مأکول محل و سبب ایک ہے؛ اس لیے مطلق خون کو «بہایا ہوا خون» کی قید کے ساتھ سمجھا جاتا ہے۔","یہی وجہ ہے کہ فقہاء نے ذبح کے بعد گوشت کی رگوں میں رہ جانے والی غیر بہتی سرخی کو «دم مسفوح» کے حکم میں نہیں رکھا۔ امام طبری، امام قرطبی اور دوسرے مفسرین نے آیتِ انعام کے تحت بہتے ہوئے خون اور گوشت میں باقی رہ جانے والے خون کا یہ فرق نقل کیا ہے۔ اصل دلیل خود قرآن کی قید «مَسْفُوحًا» ہے۔","اس صورت میں حمل کا مقصد کسی نص کو ترک کرنا نہیں بلکہ دونوں پر ایک ساتھ عمل کرنا ہے۔ مطلق حکم اصل ممانعت بیان کرتا ہے اور مقید نص اس ممانعت کی حد واضح کرتی ہے۔ اگر واقعی حکم یا سبب الگ نکلے تو یہی نتیجہ خودکار طور پر لاگو نہیں ہوگا۔"],"definitions":[{"studyQuestion":55,"term":"حکمُ المطلق والمقید","arabic":"حُكْمُ الْمُطْلَقِ أَنْ يَجْرِيَ عَلَى إطْلَاقِهِ كَمَا أَنَّ الْمُقَيَّدَ عَلَى تَقْيِيدِهِ","translation":"مطلق کو اس کے اطلاق پر اور مقید کو اس کی قید پر جاری رکھا جائے گا۔","explanation":"اگر دونوں ایک ہی حکم اور سبب میں وارد ہوں تو بحث بدل جاتی ہے (تلویح اس کی تفصیل اگلے مقام پر دیتی ہے)؛ یہاں اصل قاعدہ یہ ہے کہ کسی ایک کو بلا دلیل دوسرے پر محمول نہ کیا جائے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"فصل حكم المطلق","url":"https://shamela.ws/book/9508/116"},"kind":"definition","originalStudyQuestion":55},{"studyQuestion":55,"term":"المطلق: خاص کی قسم","arabic":"أَنَّ الْمُطْلَقَ مِنْ أَقْسَامِ الْخَاصِّ؛ لِأَنَّ الْمُطْلَقَ وُضِعَ لِلْوَاحِدِ النَّوْعِيِّ","translation":"مطلق خاص کی قسموں میں سے ہے، کیونکہ وہ «واحدِ نوعی» کے لیے وضع ہوا ہے۔","explanation":"یعنی مطلق ایک نوع کو بلا کسی قید کے بیان کرتا ہے، جیسے «رقبۃ» بغیر ایمان یا کفر کی قید کے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"تقسيم الألفاظ","url":"https://shamela.ws/book/9508/60"},"kind":"definition","originalStudyQuestion":55}],"originalNumber":59},{"number":56,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":35,"chapter_title":"مشترک مترادف اور مؤول","question":"مشترک، مترادف اور مؤول الفاظ کیا ہیں، اور فقہی استنباط میں ان سے کیا مسائل پیدا ہوتے ہیں؟","answer":["مشترک ایک لفظ کے مختلف موضوع لہ معانی، مترادف مختلف الفاظ کے ایک معنی، اور مؤول معتبر دلیل سے منتخب معنی سے متعلق ہے۔ نور الأنوار کی خاص تقسیم میں مؤول وہ مشترک ہے جس کا ایک احتمال غالب رائے سے راجح ہو۔ عمومی اصولی استعمال میں تاویل کا مفہوم اس سے وسیع بھی ہے۔ اس لیے ہر کتاب کی اصطلاح کو اسی کے مقام پر سمجھنا چاہیے؛ مؤول کو بلا دلیل من چاہا معنی نہیں کہا جاسکتا۔","مشترک وہ لفظ ہے جو ایک سے زیادہ معانی کے لیے وضع کیا گیا ہو، اور ان معانی میں سے کسی ایک کا تعین سیاق و سباق یا قرینے کے بغیر ممکن نہ ہو، جیسے لفظ 'قرء' جو حیض اور طہر دونوں معنوں میں استعمال ہوتا ہے۔ مشترک الفاظ کی تعبیر میں فقہاء کے مابین اکثر اختلاف پیدا ہوتا ہے، کیونکہ ہر مذہب مختلف قرائن کی بنیاد پر مختلف معنی کو ترجیح دیتا ہے، جیسا کہ لفظ 'قرء' کی تعبیر میں حنفی اور شافعی مکتب کے مابین معروف اختلاف ہے۔","صحیح تاویل میں لفظ مراد لیے گئے معنی کا احتمال رکھے، ظاہر چھوڑنے کے لیے معتبر شرعی یا عقلی دلیل ہو، معنی سیاق اور عربی اسلوب سے موافق ہو، اور وہ قطعی نص یا اجماع سے نہ ٹکرائے۔ تاویل کرنے والے میں زبان، حدیث اور جمعِ دلائل کی اہلیت بھی ضروری ہے۔","﴿وَاسْأَلِ الْقَرْيَةَ﴾ میں اہلِ بستی مراد لینا انہی ضوابط پر پورا اترتا ہے۔ اس کے برخلاف ﴿أَقِيمُوا الصَّلَاةَ﴾ کو صرف سماجی نظم کہنا، جبکہ سنت نے نماز کی ہیئت متواتر طور پر بیان کی، باطل تاویل ہے۔ اصولی قاعدہ یہ ہے کہ دلیل معنی کو منتخب کرے؛ منتخب معنی کے لیے دلیل تراشی نہ جائے۔","مشترک، مترادف اور مؤول کے مباحث اس لیے اہم ہیں کہ ایک ہی لفظ کے متعدد ممکن معانی یا بظاہر قریب الفاظ کے دقیق فرق استنباط کو بدل سکتے ہیں۔ اصولی منہج یہ تقاضا کرتا ہے کہ لغت، عرف، شرعی استعمال، سیاق اور قرائن کی مدد سے معنی متعین کیا جائے اور محض ذوقی ترجیح پر حکم قائم نہ کیا جائے۔","§QUOTE§وأما المشترك فما يتناول أفرادا مختلفة الحدود على سبيل البدل","مفہوم: مختلف حقیقت رکھنے والے معانی کو باری باری شامل کرنے والا لفظ۔  حوالہ: نور الأنوار، متنِ منار: المشترك۔","§QUOTE§وأما المؤول فما ترجح من المشترك بعض وجوهه بغالب الرأي","مفہوم: مشترک کے کسی معنی کا غالب رائے سے راجح ہونا؛ یہاں مؤول کی خاص حنفی اصطلاح ہے۔  حوالہ: نور الأنوار، متنِ منار: المؤول۔"],"definitions":[{"studyQuestion":56,"term":"المشترك","arabic":"ما وضع لمعنيين مختلفين أو لمعان مختلفة الحقائق","translation":"وہ لفظ جو دو مختلف معانی یا مختلف حقیقتوں والے متعدد معانی کے لیے وضع ہو۔","explanation":"مشترک کے مختلف معنی اور عام کے ایک معنی کے افراد الگ ہیں۔ مراد کے انتخاب میں قرینہ اور منہج اہم ہوتے ہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل المشترك والمؤول، ص 36","url":"https://shamela.ws/book/6302/8"},"kind":"definition","originalStudyQuestion":55},{"studyQuestion":56,"term":"المؤول: عبارة تعريفية","arabic":"ثم إذا ترجح بعض وجوه المشترك بالغالب الرأي يصير مؤولاً","translation":"جب مشترک کے بعض معانی غالب رائے سے راجح ہوجائیں تو وہ مؤول ہوجاتا ہے۔","explanation":"یہ اصل متن کی توضیحی عبارت ہے۔ اجتہادی ترجیح کے ساتھ خطا کا احتمال باقی ہے؛ متکلم کی قطعی تفسیر کی صورت الگ ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل المشترك والمؤول، ص 39","url":"https://shamela.ws/book/6302/9"},"kind":"passage","originalStudyQuestion":55}],"originalNumber":55},{"number":57,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":34,"chapter_title":"حقیقت اور مجاز","question":"حقیقت اور مجاز میں کیا فرق ہے، اور کسی لفظ کو مجازی معنی پر محمول کرنے کے لیے کس قرینے کی ضرورت ہوتی ہے؟","answer":["حقیقت اپنے مقرر معنی میں اور مجاز معتبر تعلق و قرینے کے ساتھ دوسرے معنی میں استعمال ہے۔ اصول الشاشی میں اصل وضع اور بعد کے استعمال کا یہ فرق نمایاں ہے۔ مجاز کی بحث کو تاویل کی ہر صورت کے برابر نہیں سمجھنا چاہیے؛ تخصیص اور مشترک کے معنی کی تعیین بھی الگ اسباب رکھتے ہیں۔ بعض اہلِ علم مجاز کی اصطلاحی تقسیم سے اختلاف کرتے ہیں، مگر اس سے زبان کے تمام قرائن کی نفی لازم نہیں آتی۔","حقیقت سے مراد وہ لفظ ہے جو اپنے اصل وضعی معنی میں استعمال ہو، جیسے 'اسد' بمعنی شیر۔ مجاز سے مراد وہ لفظ ہے جو اپنے اصل معنی سے ہٹ کر، کسی علاقے (ربط) کی بنا پر، کسی دوسرے معنی میں استعمال ہو، جیسے 'اسد' کو بہادر انسان کے لیے استعمال کرنا (شجاعت کی مناسبت سے)۔ فقہاء کا اصول ہے کہ جب تک کوئی قرینہ مجاز کی طرف نہ لے جائے، لفظ کو اس کے حقیقی معنی پر ہی محمول کیا جاتا ہے، کیونکہ حقیقت اصل اور مجاز اس سے منحرف صورت ہے۔","حقیقت وہ استعمال ہے جس میں لفظ اپنے اصل یا معروف مقررہ معنی میں بولا جائے۔ مجاز وہ استعمال ہے جس میں کسی تعلق اور واضح قرینے کی وجہ سے لفظ کو اصل معنی سے ہٹا کر دوسرے مناسب معنی میں لیا جائے۔ قرینہ اس امکان کو روکتا ہے کہ اصل معنی ہی مراد ہو۔","اصولی کتابوں میں حقیقت کی لغوی، شرعی اور عرفی صورتیں بیان ہوتی ہیں۔ «صلاۃ» کا لغوی مفہوم دعا ہے، مگر شرعی خطاب میں مخصوص ارکان والی عبادت اس کی شرعی حقیقت ہے۔ «دابۃ» لغت میں ہر چلنے والے جاندار کے لیے آسکتا ہے، مگر کسی عرف میں خاص جانور کے لیے معروف ہوسکتا ہے۔ متعلقہ سیاق میں اسی غالب حقیقت کو مقدم کیا جاتا ہے۔","مجاز کی مثال قرآن کے اسلوب میں ﴿وَاسْأَلِ الْقَرْيَةَ﴾ (یوسف: 82) ہے۔ بستی کی عمارتوں سے سوال مراد نہیں؛ قرینہ بتاتا ہے کہ اہلِ بستی سے پوچھنا مراد ہے۔ اسی طرح ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ﴾ (الکہف: 77) میں دیوار کے ارادے سے اس کا جھکنا اور گرنے کے قریب ہونا مراد لیا جاتا ہے۔","اصولی قاعدہ یہ ہے کہ حقیقت بلا قرینہ اصل ہے۔ مجاز اسی وقت اختیار ہوگا جب لفظی یا حالی دلیل اس کی طرف لے جائے۔ اس احتیاط سے دو خطروں سے بچاؤ ہوتا ہے: ہر تعبیر کو جامد ظاہریت میں قید کرنا، اور مجاز کے نام پر نص کو من چاہا معنی دینا۔ بعض متاخر اہلِ علم نے مجاز کی اصطلاحی تقسیم پر تنقید کی، لیکن سب اس بات کو مانتے ہیں کہ زبان میں اسالیب، قرائن اور غیر حرفی تعبیرات کو سمجھے بغیر درست فہم ممکن نہیں۔","قرینہ اس لیے ضروری ہے کہ لفظ کا اصل حق حقیقی معنی ہے۔ اگر کسی مضبوط علامت کے بغیر حقیقی معنی چھوڑ دیا جائے تو ہر شخص اپنی خواہش کے مطابق نص بدل سکتا ہے اور زبان کی مشترک دلالت ختم ہوجاتی ہے۔ قرینہ لفظی، عقلی، حالی یا شرعی ہوسکتا ہے۔","حقیقت و مجاز کی بحث زبان، عرف اور شرعی استعمال کے باہمی تعلق کو منظم کرتی ہے۔ کسی لفظ کو مجازی معنی پر منتقل کرنے سے پہلے اس کے حقیقی استعمال، سیاق اور قرینہ کو دیکھنا ضروری ہے، کیونکہ بے قرینہ مجاز پر منتقل ہونا نص کے مفہوم کو غیر ضروری طور پر بدل سکتا ہے۔","صریح اور کنایہ بھی اہم ہیں: صریح کا مقصود معروف استعمال میں واضح ہوتا ہے، جبکہ کنایہ میں مراد تعیین چاہتی ہے۔ حقیقت و مجاز استعمال کا تعلق وضع سے اور صریح و کنایہ کا تعلق وضوحِ مراد سے ہے، اس لیے یہ ایک ہی تقسیم نہیں۔ نکاح، طلاق اور اقرار میں لفظ، نیت اور قرائن کا اثر باب کی مخصوص فقہی تفصیل کے مطابق دیکھا جائے۔","§QUOTE§كل لفظ وضعه واضع اللغة بإزاء شيء فهو حقيقة له ولو استعمل في غيره يكون مجازا لا حقيقة","مفہوم: لفظ اپنے موضوع لہ کے لیے حقیقت اور اس کے سوا استعمال میں مجاز ہوتا ہے؛ معتبر تعلق و قرینہ کی بحث بھی متعلق ہے۔  حوالہ: اصول الشاشی، فصل الحقيقة والمجاز۔"],"definitions":[{"studyQuestion":57,"term":"الحقیقة","arabic":"كل لفظ وضعه واضع اللغة بإزاء شيء فهو حقيقة له","translation":"ہر وہ لفظ جسے واضعِ لغت نے کسی چیز کے لیے وضع کیا ہو، اُس چیز کے لیے حقیقت ہے۔","explanation":"حقیقت کا مدار وضع پر ہے، استعمال کی کثرت پر نہیں۔ اسی سے حقیقت و مجاز کی تقسیم کا آغاز ہوتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل في الحقيقة والمجاز","url":"https://shamela.ws/book/6302/10"},"kind":"definition","originalStudyQuestion":57},{"studyQuestion":57,"term":"المجاز","arabic":"ولو استعمل في غيره يكون مجازا لا حقيقة","translation":"اور اگر وہی لفظ اپنے وضعی معنی کے علاوہ میں استعمال ہو تو وہ مجاز ہے، حقیقت نہیں۔","explanation":"مجاز کے لیے قرینہ درکار ہوتا ہے؛ جب تک حقیقت پر عمل ممکن ہو، حقیقت مقدّم رہتی ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل في الحقيقة والمجاز","url":"https://shamela.ws/book/6302/10"},"kind":"definition","originalStudyQuestion":57},{"studyQuestion":57,"term":"الصريح","arabic":"لفظ يكون المراد به ظاهراً","translation":"وہ لفظ جس کی مراد ظاہر ہو۔","explanation":"صریح و کنایہ استعمال اور وضوحِ مراد کی تقسیم ہے؛ حقیقت و مجاز کے وضعی تعلق کی تقسیم سے ہر حال میں یکساں نہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل الصريح والكناية، ص 64","url":"https://shamela.ws/book/6302/21"},"kind":"definition","originalStudyQuestion":54},{"studyQuestion":57,"term":"الكناية","arabic":"هي ما استتر معناه","translation":"وہ عبارت جس کی مراد پوشیدہ ہو۔","explanation":"اس کی تعیین میں نیت اور دلالتِ حال اہم ہوسکتی ہے۔ مخصوص قول یا عقد کا حکم متعلقہ فقہی باب کی شرائط سے جانچا جاتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل الصريح والكناية، ص 65","url":"https://shamela.ws/book/6302/22"},"kind":"definition","originalStudyQuestion":54}],"originalNumber":54},{"number":58,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":36,"chapter_title":"واضح الدلالہ الفاظ","question":"ظاہر، نص، مفسر اور محکم میں کیا فرق ہے، اور ان میں تاویل یا نسخ کی گنجائش کیسے مختلف ہوتی ہے؟","answer":["حنفی تقسیم میں ظاہر سے مراد کا ابتدائی وضوح، نص میں سیاق کی وجہ سے زائد وضوح، مفسر میں تاویل و تخصیص کے احتمال کا زوال، اور محکم میں نسخ کا احتمال بھی ختم ہونا مراد ہے۔ نص بھی معتبر تاویل کا احتمال رکھتا ہے؛ اسے مفسر کی طرح بے احتمال کہنا غلط ہے۔ نسخ کی گنجائش عہدِ تشریع سے متعلق ہے؛ رسول اللہ ﷺ کی وفات کے بعد کوئی نئی دلیل شریعت کو منسوخ نہیں کرسکتی۔","مثلاً ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ سے بیع کا حلال اور ربا کا حرام ہونا صاف سمجھ میں آتا ہے۔ یہ حکم لفظ سے ظاہر ہے۔ تاہم بیع کی ہر ممکن صورت آیت کا مقصود نہیں؛ دوسری نصوص نے غرر، دھوکے اور ممنوع اشیا کی بیع کو اس عموم سے خارج کیا ہے۔ اس لیے ظاہر حجت ہے، مگر قوی دلیل اسے مخصوص یا مؤول کرسکتی ہے۔","واضح الدلالہ الفاظ میں بھی وضوح کے درجات یکساں نہیں ہوتے۔ ظاہر، نص، مفسر اور محکم کی درجہ بندی یہ سمجھاتی ہے کہ کبھی معنی پہلی نظر میں واضح ہوتا ہے، کبھی سیاق اسے زیادہ متعین کرتا ہے، کبھی شارع کی توضیح احتمال ختم کرتی ہے، اور کبھی دلالت ایسی پختہ ہو جاتی ہے کہ تاویل یا نسخ کی گنجائش باقی نہیں رہتی۔","حنفی اصولی روایت میں یہ درجہ بندی استنباط کی قوت اور متعارض قرائن کے وزن کو سمجھنے کے لیے بنیادی حیثیت رکھتی ہے۔","دونوں الفاظ اپنی عبارت سے معنی واضح کرتے ہیں۔ فرق یہ ہے کہ ظاہر کا مفہوم کلام کا ضمنی یا تابع معنی ہوسکتا ہے، جبکہ نص کا مفہوم سیاق کا اصل مقصود ہوتا ہے۔ اسی لیے تعارض کی صورت میں، جب جمع ممکن نہ ہو، نص کو ظاہر پر ترجیح دی جاتی ہے۔","﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ بیع کے جواز اور ربا کی حرمت پر ظاہر ہے۔ مگر آیت کا سیاق ان لوگوں کی تردید کرتا ہے جو کہتے تھے ﴿إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا﴾؛ لہٰذا بیع اور ربا کے شرعی فرق کو ثابت کرنا نص کا بنیادی مقصود ہے۔ ایک ہی عبارت مختلف نسبتوں سے ظاہر اور نص ہوسکتی ہے۔","یہ حنفی درجہ بندی ہے: ظاہر اور نص دونوں قابلِ عمل ہیں اور دونوں میں معتبر تاویل کا احتمال باقی ہوسکتا ہے؛ نص کا سیاقی وضوح زیادہ ہے۔ مفسر میں تاویل و تخصیص کا احتمال ختم ہوتا ہے، مگر عہدِ رسالت میں نسخ کی گنجائش ہوتی ہے۔ محکم میں متعلقہ حکم نسخ بھی قبول نہیں کرتا۔ عہدِ رسالت کے بعد نئی وحی کے ذریعے نسخ کا دروازہ بند ہے؛ بعد کے علماء کی تشریح نسخ نہیں۔","§QUOTE§فالظاهر اسم لكل كلام ظهر المراد به للسامع بنفس السماع من غير تأمل","مفہوم: وہ کلام جس کا مقصود سامع کو خود سماع سے بلا تامل ظاہر ہو۔  حوالہ: اصول الشاشی، فصل الظاهر والنص۔","§QUOTE§والنص ما سيق الكلام لأجله","مفہوم: وہ معنی جس کے لیے کلام لایا گیا ہو۔  حوالہ: اصول الشاشی، فصل الظاهر والنص۔","§QUOTE§وأما المفسر فهو ما ظهر المراد به من اللفظ ببيان من قبل المتكلم بحيث لا يبقى معه احتمال التأويل والتخصيص","مفہوم: متکلم کے بیان سے مراد ایسی واضح ہو کہ تاویل و تخصیص کا احتمال باقی نہ رہے۔  حوالہ: اصول الشاشی، بحث المفسر۔","§QUOTE§وأما المحكم فهو ما ازداد قوة على المفسر بحيث لا يجوز خلافه أصلا","مفہوم: مفسر سے بڑھ کر پختہ دلالت جس کا خلاف اصلاً جائز نہ ہو۔  حوالہ: اصول الشاشی، بحث المحكم۔"],"definitions":[{"studyQuestion":58,"term":"الظاهر","arabic":"اسم لكل كلام ظهر المراد به للسامع بنفس السماع من غير تأمل","translation":"وہ کلام جس کی مراد سننے والے کو محض سماع سے، تأمل کے بغیر، ظاہر ہوجائے۔","explanation":"یہ حنفی تقسیم ہے۔ ظاہر میں اصل وضوح کے باوجود معتبر تاویل کا احتمال رہ سکتا ہے؛ سند کی قطعیت اس دلالتی تقسیم سے الگ ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل المتقابلات، ص 68","url":"https://shamela.ws/book/6302/23"},"kind":"definition","originalStudyQuestion":60},{"studyQuestion":58,"term":"النص","arabic":"ما سيق الكلام لأجله","translation":"وہ معنی جس کے لیے کلام لایا گیا ہو۔","explanation":"حنفی اصطلاح میں مقصدِ سوق سے زائد وضوح ملتا ہے۔ اسے دوسرے منہج کے «صرف ایک معنی» والے نص کے ساتھ بلا وضاحت نہ ملائیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل المتقابلات، ص 68","url":"https://shamela.ws/book/6302/23"},"kind":"definition","originalStudyQuestion":60},{"studyQuestion":58,"term":"المفسر","arabic":"ما ظهر المراد به من اللفظ ببيان من قبل المتكلم بحيث لا يبقى معه احتمال التأويل والتخصيص","translation":"وہ لفظ جس کی مراد متکلم کے بیان سے ایسی کھل جائے کہ تاویل اور تخصیص کا احتمال باقی نہ رہے۔","explanation":"مفسر کی قطعی توضیح اور مؤول کی اجتہادی ترجیح الگ ہیں۔ عہدِ تشریع میں مفسر کے لیے نسخ کی گنجائش کا سوال محکم سے فرق واضح کرتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث ترجيح المفسر على النص، ص 76","url":"https://shamela.ws/book/6302/27"},"kind":"definition","originalStudyQuestion":60},{"studyQuestion":58,"term":"المحكم","arabic":"ما ازداد قوة على المفسر بحيث لا يجوز خلافه أصلاً","translation":"وہ جو مفسر سے بھی زیادہ قوی ہو اور اس کی مخالفت کی گنجائش بالکل نہ ہو۔","explanation":"اصل وضوح کے ساتھ بذاتِ خود نسخ کا عدمِ قبول سمجھا جاتا ہے۔ خاتمۂ وحی کے بعد تمام ثابت شرعی احکام میں نیا تشریعی نسخ بند ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث الخفي والمشكل، ص 80","url":"https://shamela.ws/book/6302/29"},"kind":"definition","originalStudyQuestion":60}],"originalNumber":60},{"number":59,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":37,"chapter_title":"غیر واضح الدلالہ الفاظ","question":"خفی، مشکل، مجمل اور متشابہ میں کیا فرق ہے، اور ابہام دور کرنے کا اصولی طریقہ کیا ہے؟","answer":["خفی میں لفظ کا اصل معنی واضح مگر کسی خاص فرد پر اطلاق مشکل ہوتا ہے؛ مشکل میں خود معنی کی تعیین تحقیق چاہتی ہے؛ مجمل میں متکلم کے بیان کی ضرورت ہوتی ہے؛ متشابہ میں مراد کا ایسا خفاء ہوتا ہے جس کی تعیین انسان کے لیے دستیاب طریقے سے نہیں ہوتی۔ متشابہ کی اصولی و تفسیری تعبیرات میں اختلاف ہے۔ اسے صرف مشکل عبارت کا مترادف سمجھنا غلط ہے۔ مجمل نص نبوی بیان کے بعد پہلے جیسی مجمل نہیں رہتی۔","خفی وہ لفظ ہے جس کا اصل معنی تو واضح ہو مگر کسی خاص فرع پر اس کا اطلاق مبہم ہو جائے، جیسے 'سارق' کا لفظ جیب کترے یا کفن چور پر اطلاق میں کچھ خفاء رکھتا ہے۔ مشکل وہ لفظ ہے جس کا معنی اس سے بھی زیادہ پیچیدہ اور الجھا ہوا ہو، جس کی تفہیم کے لیے گہری تحقیق درکار ہو۔ یہ دونوں اقسام حنفی مکتب کی ابہام کی درجہ بندی کا حصہ ہیں، جو وضوح کی چار درجاتی تقسیم (ظاہر تا محکم) کے متوازی ابہام کی چار درجاتی تقسیم (خفی، مشکل، مجمل، متشابہ) بناتی ہیں۔","قرآن نے ﴿أَقِيمُوا الصَّلَاةَ﴾ اور ﴿آتُوا الزَّكَاةَ﴾ فرمایا، مگر نماز کی رکعات اور زکوٰۃ کے نصاب کی پوری تفصیل اسی حکم میں مذکور نہیں۔ نبی ﷺ کے قول و عمل نے اس اجمال کو کھولا۔ اس لیے سنت محض اضافی معلومات نہیں؛ بہت سے قرآنی احکام کی لازمی تبیین ہے۔","غیر واضح الدلالہ الفاظ میں خفاء کی نوعیت الگ الگ ہوسکتی ہے؛ کبھی لفظ واضح ہے مگر کسی فرد پر اس کا انطباق دشوار ہوتا ہے، کبھی معنی لغوی یا سیاقی تحقیق چاہتا ہے، کبھی شارع کی توضیح کے بغیر مراد متعین نہیں ہوتی۔ اسی فرق کی بنا پر خفی، مشکل، مجمل اور متشابہ کو ایک ہی درجے میں نہیں رکھا جاتا۔","خفی میں خفاء خارجی عارض سے، مشکل میں مراد کی تعیین غور و قرائن سے، اور مجمل میں بیانِ متکلم سے واضح ہوتی ہے۔ متشابہ کی اصولی اور کلامی تفصیلات ایک ہی انداز سے بیان نہیں کی جاتیں؛ اس سے متعلق غیر ثابت تشریح کو قطعی مراد کہنا درست نہیں۔ مجمل کی مثال میں نماز کی مطلوب کیفیت سنت سے معلوم ہوتی ہے؛ لفظ کا عمومی مفہوم جاننا تمام عملی تفصیل جاننے کے برابر نہیں۔","§QUOTE§وهو ما احتمل وجوها فصار بحال لا يوقف على المراد به إلا ببيان من قبل المتكلم","مفہوم: کئی وجوہ کا احتمال رکھنے والا کلام جس کی مراد متکلم کے بیان ہی سے معلوم ہو۔  حوالہ: اصول الشاشی، بحث المجمل۔"],"definitions":[{"studyQuestion":59,"term":"المشكل: اقتباس من التعريف","arabic":"لا ينال المراد إلا بالطلب ثم بالتأمل حتى يتميز عن أمثاله","translation":"مراد طلب اور پھر تأمل سے حاصل ہوتی ہے، یہاں تک کہ وہ مماثل صورتوں سے ممتاز ہوجائے۔","explanation":"یہ مشکل کی طویل تعریف کا منتخب اصل جز ہے۔ اس میں زبان اور قرائن پر زائد غور چاہیے؛ اسے مجمل کی ہر صورت کے ساتھ یکساں نہ رکھیے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث الخفي والمشكل، ص 81","url":"https://shamela.ws/book/6302/30"},"kind":"passage","originalStudyQuestion":61},{"studyQuestion":59,"term":"المجمل","arabic":"ما احتمل وجوهاً فصار بحال لا يوقف على المراد به إلا ببيان من قبل المتكلم","translation":"جو متعدد صورتوں کا احتمال رکھے اور اس کی مراد متکلم کے بیان ہی سے معلوم ہوسکے۔","explanation":"مجمل کی شرعی مراد کے لیے معتبر بیان ضروری ہے۔ عبادات کی کیفیت میں سنت کی توضیح اسی علمی ضرورت کو پورا کرتی ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث الخفي والمشكل، ص 81","url":"https://shamela.ws/book/6302/30"},"kind":"definition","originalStudyQuestion":61}],"originalNumber":61},{"number":60,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":35,"chapter_title":"مشترک مترادف اور مؤول","question":"تاویلِ صحیح اور تاویلِ فاسد میں فرق کیسے کیا جائے گا؟ معتبر تاویل کی بنیادی شرائط کیا ہیں؟","answer":["معتبر تاویل میں منتخب معنی لفظ کی گنجائش میں ہو اور ظاہر یا دوسرے احتمال سے عدول کی قوی دلیل موجود ہو۔ محض احتمال اور راجح معنی الگ ہیں۔ حنفی تقسیم میں مؤول مشترک کے راجح معنی کا عنوان بھی ہے، جبکہ عام استعمال میں تاویل ظاہر سے کسی محتمل معنی کی طرف عدول کو کہتے ہیں۔ کسی خاص رائے کو پہلے طے کرکے نصوص کو اس کے مطابق ڈھالنا صحیح تاویل نہیں؛ معنی، دلیل اور سیاق کا ربط دکھانا ضروری ہے۔","لفظ جس معنی کا احتمال ہی نہیں رکھتا، اسے اس پر حمل کرنا معتبر تاویل نہیں۔ ظاہر معنی چھوڑنے کی دلیل، قرینے کی قوت اور متعلقہ نصوص کی موافقت واضح ہونی چاہیے۔ قرآن میں بستی سے سوال کرنے کا معنی اہلِ بستی سے سوال کرنا سمجھا جاتا ہے، کیونکہ سیاق اور خطاب اس پر رہنمائی کرتے ہیں۔ اس کے برخلاف نماز کے ثابت شرعی مفہوم کو صرف سماجی نظم قرار دینا اس کی متواتر نبوی تبیین سے متصادم ہے۔ کسی تاویل کو غلط کہنے میں اعتراض کی اصل وجہ بتائیں، صرف اپنے فہم سے اختلاف کافی نہیں۔"],"definitions":[],"originalNumber":62},{"number":61,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":32,"chapter_title":"امر مفہوم دلالت اور احکام","question":"امر اصولی اعتبار سے کن معانی پر دلالت کرتا ہے، اور کیا ہر امر وجوب کے لیے ہوتا ہے؟","answer":["بے قرینہ شرعی امر کی اصل دلالت وجوب ہے، مگر قرینہ اسے ندب، اباحت، ارشاد یا تہدید جیسے معنی دے سکتا ہے۔ امرِ وجوب اور حکم کے فرض یا واجب ہونے کی حنفی درجہ بندی الگ سوال ہیں۔ فور، تراخی اور تکرار بھی خود وجوب سے جدا مباحث ہیں۔ اصول الشاشی میں مجرد امر سے تکرار لازم نہیں؛ عبادات کا تکرار ان کے اسباب کے تکرار سے سمجھایا گیا ہے۔","قرآن میں ﴿وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ﴾ نماز قائم کرنے اور زکوٰۃ دینے کا حکم ہے۔ یہاں «أقيموا» اور «آتوا» دونوں امر ہیں۔ تعریف کا عملی فائدہ یہ ہے کہ دعا، التجا اور مشورے کے صیغے کو شرعی حکم سے الگ رکھا جائے؛ مثلاً بندے کا کہنا ﴿رَبَّنَا اغْفِرْ لَنَا﴾ دعا ہے، اصطلاحی امر نہیں، کیونکہ بندہ اپنے رب کے مقابل بالا دست نہیں۔","امر کی بحث میں صرف صیغۂ امر کو دیکھنا کافی نہیں؛ اصولی حکم تک پہنچنے کے لیے سیاق، قرینہ، متعلقہ نصوص، شارع کا مقصود اور حکم کے درجے کو باہم دیکھا جاتا ہے۔ اسی وجہ سے اصولیین نے وجوب، ندب، اباحت، فور، تراخی اور تکرار جیسے مباحث الگ کیے تاکہ ایک ہی لفظی قالب کو ہر جگہ ایک ہی قانونی اثر نہ دیا جائے۔","اس باب کی تفصیل امام شافعی کی الرسالہ، امام غزالی کی المستصفیٰ، امام آمدی کی الإحکام اور حنفی روایت میں اصول السرخسی و کشف الأسرار میں دیکھی جا سکتی ہے۔","جمہور اصولیین کے نزدیک جب شارع کا امر کسی ایسی قرینہ سے خالی ہو جو اسے ندب، اباحت یا کسی اور معنی کی طرف پھیر دے، تو اس کا اصل مقتضا وجوب ہے۔ قاعدہ ہے: «اَلْأَصْلُ فِي الْأَمْرِ لِلْوُجُوبِ مَا لَمْ تَقُمْ قَرِينَةٌ تَصْرِفُهُ عَنْهُ»۔","اس کی روشن مثال ﴿وَأَقِيمُوا الصَّلَاةَ﴾ ہے۔ محض «قائم کرو» کا مطالبہ، نماز کی فرضیت پر دوسرے قطعی دلائل کے ساتھ، وجوب بتاتا ہے۔ حدیث میں نبی ﷺ نے فرمایا: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ»۔ اگر امر لازماً لازم نہ سمجھا جاتا تو مشقت، حکم دینے سے مانع نہ بنتی۔ البتہ وجوب کا یہ اصول ابتدائی دلالت ہے؛ معتبر قرینہ آجائے تو مفہوم بدل سکتا ہے۔","§QUOTE§الأمر في اللغة قول القائل لغيره افعل وفي الشرع تصرف إلزام الفعل على الغير","مفہوم: لغت میں دوسرے سے افعل کہنا اور شرعی بحث میں دوسرے پر فعل لازم کرنے کا تصرف۔  حوالہ: اصول الشاشی، باب الأمر۔"],"definitions":[{"studyQuestion":61,"term":"الأمر","arabic":"الْأَمر فِي اللُّغَة قَول الْقَائِل لغيره افْعَل وَفِي الشَّرْع تصرف إِلْزَام الْفِعْل على الْغَيْر","translation":"امر لغت میں کسی کا دوسرے سے «کرو» کہنا ہے، اور شریعت میں دوسرے پر فعل لازم کرنے والا تصرف۔","explanation":"شاشی نے ساتھ ہی واضح کیا کہ امر کو صرف صیغۂ «افعل» تک محدود ماننا درست نہیں، کیونکہ اللہ تعالیٰ کا کلام ازلی ہے اور اس میں صیغہ ازل میں موجود نہیں ہوتا۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل في الأمر","url":"https://shamela.ws/book/6302/46"},"kind":"definition","originalStudyQuestion":61}],"originalNumber":56},{"number":62,"unit_id":6,"unit_name":"یونٹ ششم","unit_title":"مباحث الفاظ کی بنیادیں","chapter_number":33,"chapter_title":"نہی مفہوم دلالت اور احکام","question":"نہی کس حکم پر دلالت کرتی ہے، اور کیا نہی ہمیشہ متعلقہ عمل کے فساد کو لازم کرتی ہے؟","answer":["نہی کی اصل دلالت حرمت ہے، مگر فساد کا حکم اس کے متعلق کی تحقیق چاہتا ہے۔ ممانعت فعل یا عقد کی اصل، لازم وصف یا خارجی امر سے متعلق ہوسکتی ہے۔ حنفی معاملات میں باطل اور فاسد کی تفریق اسی بحث سے مربوط ہے۔ جمعہ کے وقت خرید و فروخت کی ممانعت اور عقد کی قانونی صحت کو ایک ہی سوال نہیں سمجھنا چاہیے؛ گناہ اور صحت کے آثار مختلف مذاہب میں تفصیل رکھتے ہیں۔","قرآن کا حکم ﴿وَلَا تَقْرَبُوا الزِّنَا﴾ زنا ہی نہیں بلکہ اس تک لے جانے والے ممنوع راستوں سے بھی روکتا ہے۔ اس کے برخلاف کم تر شخص کی اپنے سے بڑے کو درخواست اصطلاحی نہی نہیں۔ تعریف فقیہ کو یہ سمجھاتی ہے کہ کون سا جملہ قانونی تحریم، کون سا اخلاقی ادب اور کون سا محض خبر یا دعا ہے۔","نہی کے باب میں اصل سوال یہ نہیں کہ ممانعت کا لفظ کہاں آیا، بلکہ یہ ہے کہ اس ممانعت کا درجہ کیا ہے، اس کا متعلق فعل یا وصف کون سا ہے، اور آیا ممانعت خود فعل کی ذات سے متعلق ہے یا کسی خارجی وصف سے۔ یہی امتیاز حرمت، کراہت اور فساد یا بطلان کے نتائج پر اثر انداز ہوتا ہے۔","اس موضوع میں متکلمین اور احناف کے مناہج کا تقابل خاص اہمیت رکھتا ہے؛ المستصفیٰ، الإحکام، اصول السرخسی اور کشف الأسرار اس بحث کے بنیادی مراجع میں شمار ہوتے ہیں۔","اصول یہ ہے: «اَلْأَصْلُ فِي النَّهْيِ لِلتَّحْرِيمِ مَا لَمْ تَقُمْ قَرِينَةٌ تَصْرِفُهُ»۔ یعنی شارع کسی فعل سے بے قرینہ روکے تو اسے حرام سمجھا جائے گا، محض ناپسندیدہ نہیں۔ اس کی وجہ یہ ہے کہ ممانعت کی تعمیل فعل چھوڑنے ہی سے ہوتی ہے۔","﴿لَا تَأْكُلُوا الرِّبَا﴾ اور ﴿لَا تَقْرَبُوا الزِّنَا﴾ کے ساتھ شدید وعیدیں بھی آئی ہیں، اس لیے تحریم اور واضح ہوجاتی ہے۔ البتہ اگر صحیح دلیل بتائے کہ مقصد تنزیہی کراہت یا مصلحت کی رہنمائی ہے تو اصل دلالت بدل سکتی ہے۔ محض سہولت یا ذاتی پسند کو قرینہ بنانا جائز نہیں۔","اصولیین کے مابین یہ اختلاف پایا جاتا ہے کہ آیا نہی کسی فعل کے فاسد یا باطل ہونے کا تقاضا کرتی ہے۔ جمہور فقہاء کے نزدیک اگر نہی کا تعلق فعل کی اصل ذات سے ہو (جیسے سود پر مبنی بیع)، تو وہ فعل فاسد یا باطل قرار پاتا ہے۔ اگر نہی کا تعلق فعل کے کسی خارجی وصف سے ہو (جیسے جمعہ کے وقت بیع کرنا)، تو فعل بذاتِ خود درست رہتا ہے مگر اس کا ارتکاب گناہ سمجھا جاتا ہے۔ یہ فرق حنفی اور شافعی مکاتب کے مابین ایک اہم اصولی نکتہ ہے۔"],"definitions":[{"studyQuestion":62,"term":"النہی کی دو قسمیں","arabic":"النَّهْي نَوْعَانِ نهي عَن الْأَفْعَال الحسية كَالزِّنَا وَشرب الْخمر وَالْكذب وَالظُّلم وَنهي عَن التَّصَرُّفَات الشَّرْعِيَّة","translation":"نہی دو طرح کی ہے: حسی افعال (زنا، شراب، جھوٹ، ظلم) سے نہی، اور شرعی تصرفات سے نہی۔","explanation":"پہلی قسم میں منہی عنہ بذاتہ قبیح ہوتا ہے اور اصلاً مشروع نہیں رہتا؛ دوسری میں تصرف بذاتہ حَسَن اور لغیرہ قبیح ہوتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل في النهي","url":"https://shamela.ws/book/6302/68"},"kind":"definition","originalStudyQuestion":62},{"studyQuestion":62,"term":"النہی عن التصرفات: تقریر","arabic":"النَّهْي عَن التَّصَرُّفَات الشَّرْعِيَّة يَقْتَضِي تقريرها","translation":"شرعی تصرفات سے نہی ان کے مشروع رہنے کا تقاضا کرتی ہے۔","explanation":"یعنی نہی کے بعد بھی تصرف بذاتِ خود مشروع رہتا ہے اور خرابی غیر (وصف یا مجاور) کی طرف لوٹتی ہے؛ ورنہ بندہ عاجز ہو کر نہی کا مخاطب ہی نہ رہتا۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل في النهي","url":"https://shamela.ws/book/6302/68"},"kind":"definition","originalStudyQuestion":62}],"originalNumber":57},{"number":63,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":38,"chapter_title":"احناف کے ہاں دلالات نص","question":"عبارۃ النص، اشارۃ النص، دلالۃ النص اور اقتضاء النص میں کیا فرق ہے؟","answer":["عبارت النص مقصود بیان، اشارۃ النص غیر مقصود لازم معنی، دلالۃ النص زبان سے معلوم مشترک معنی، اور اقتضاء النص کلام کی صحت کے لیے ضروری مقدر معنی ہے۔ دلالۃ النص کی واضح مثال والدین کو اف کہنے کی ممانعت سے زیادہ اذیت کی حرمت سمجھنا ہے۔ اقتضاء میں صرف اتنا معنی مانا جاتا ہے جتنا کلام درست کرنے کے لیے ضروری ہو؛ ہر مفید اضافہ اقتضاء نہیں۔ نور الأنوار اور اصول الشاشی دونوں اس فرق کی تفصیل دیتے ہیں۔","﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ اپنی عبارت سے بیع کی حلت اور ربا کی حرمت بتاتی ہے۔ یہ نتائج کسی پوشیدہ لازم یا قیاس سے نہیں، انہی الفاظ سے نکلتے ہیں۔ عبارت النص استنباط کا پہلا اور عموماً سب سے واضح راستہ ہے۔","حنفی دلالاتِ نص—عبارت النص، اشارۃ النص، دلالۃ النص اور اقتضاء النص—یہ دکھاتی ہیں کہ نص سے حکم صرف صریح جملے سے نہیں نکلتا بلکہ بعض اوقات لازم معنی، مفہومِ موافق یا کلام کے صحیح ہونے کے لیے مقدر معنی بھی معتبر ہوتے ہیں۔ ان چاروں کو خلط کرنے سے دلیل کی قوت اور استنباط کا طریقہ مبہم ہوجاتا ہے۔","اصول السرخسی اور کشف الأسرار اس تقسیم کی تفہیم کے لیے بنیادی حنفی مراجع ہیں، جبکہ دوسرے اصولی مناہج سے تقابل اس کی خصوصیت مزید واضح کرتا ہے۔","دلالتِ اشارہ سے مراد وہ حکم ہے جو کلام کا اصل مقصود نہیں مگر اس کے ساخت سے لازمی طور پر نکل آتا ہے۔ مثال کے طور پر آیت 'وعلی المولود لہ رزقھن وکسوتھن' (باپ پر بچے کی ماں کا نان و نفقہ لازم ہے) سے یہ دلالتِ اشارہ نکلتی ہے کہ نسب کا تعلق باپ سے ہے، کیونکہ نفقے کی ذمہ داری کا لفظ 'مولود لہ' یعنی 'جس کے لیے بچہ پیدا ہوا' استعمال ہوا، جو باپ کی طرف نسب کی نسبت کی طرف اشارہ کرتا ہے، حالانکہ آیت کا اصل مقصود نان و نفقے کا حکم ہے۔","دلالتِ اقتضاء سے مراد وہ حکم ہے جسے کلام کی درست تکمیل یا صحت کے لیے تقدیراً ماننا ضروری ہو، اگرچہ وہ الفاظ میں مذکور نہ ہو۔ مثال کے طور پر حدیث 'رفع عن امتی الخطا والنسیان' (میری امت سے خطا اور نسیان کا مواخذہ اٹھا لیا گیا) کا ظاہری مطلب یہ ہے کہ خطا اور نسیان بذاتِ خود اٹھا لیے گئے، جبکہ حقیقتاً یہ خطا اور نسیان پر مبنی گناہ کا مواخذہ اٹھایا گیا ہے، اور یہی تقدیری لفظ (گناہ کا مواخذہ) کلام کی درست تکمیل کے لیے ضروری ہے۔","§QUOTE§وأما الاستدلال بعبارة النص فهو العمل بظاهر ما سيق الكلام له","مفہوم: اس ظاہر مفہوم سے استدلال جس کے لیے کلام لایا گیا ہو۔  حوالہ: نور الأنوار، متنِ منار: عبارة النص۔","§QUOTE§وأما دلالة النص فهي ما علم علة للحكم المنصوص عليه لغة لا اجتهادا ولا استنباطا","مفہوم: منصوص حکم کی وہ علت جو زبان سے معلوم ہو، اجتہادی استنباط سے نہیں۔  حوالہ: اصول الشاشی، فصل دلالة النص۔"],"definitions":[{"studyQuestion":63,"term":"ترک اور حرام کا باہمی تعلق","arabic":"فَيُقَالُ عَدَمُ مُبَاشَرَةِ الْوَاجِبِ حَرَامٌ وَعَدَمُ مُبَاشَرَةِ الْحَرَامِ وَاجِبٌ","translation":"واجب کو نہ کرنا حرام کہلاتا ہے اور حرام کو نہ کرنا واجب۔","explanation":"تلویح میں یہ اس لیے بتایا گیا کہ احکام کی صفتیں ترک پر بھی بولی جاتی ہیں؛ اسی بنیاد پر فعل اور ترک کے الگ الگ طرف شمار ہو کر اقسام بارہ بنتی ہیں۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"أقسام الأحكام","url":"https://shamela.ws/book/9508/17"},"kind":"definition","originalStudyQuestion":63},{"studyQuestion":63,"term":"عبارة النص","arabic":"ما سيق الكلام لأجله وأريد به قصداً","translation":"وہ معنی جس کے لیے کلام لایا گیا اور جسے قصداً مراد لیا گیا۔","explanation":"یہ عبارت کی مقصود دلالت ہے؛ مقصد کبھی اصلی اور کبھی تابع ہوسکتا ہے۔ غیر مقصود لازم معنی کی اشارتی دلالت الگ ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل متعلقات النصوص، ص 99","url":"https://shamela.ws/book/6302/37"},"kind":"passage","originalStudyQuestion":63},{"studyQuestion":63,"term":"إشارة النص","arabic":"ما ثبت بنظم النص من غير زيادة وهو غير ظاهر من كل وجه ولا سيق الكلام لأجله","translation":"جو نظمِ نص سے بلا اضافہ ثابت ہو، مگر ہر پہلو سے ظاہر نہ ہو اور کلام اس کے لیے نہ لایا گیا ہو۔","explanation":"یہ عبارت دو مسلسل صفحات سے مکمل کی گئی ہے۔ معنی متن کا لازم تعلق ہے؛ ضروری حذف کی تقدیر، جو اقتضاء ہے، الگ جہت رکھتی ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل متعلقات النصوص، ص 99–101","url":"https://shamela.ws/book/6302/38"},"kind":"definition","originalStudyQuestion":63},{"studyQuestion":63,"term":"دلالة النص","arabic":"ما علم علة للحكم المنصوص عليه لغة لا اجتهاداً ولا استنباطاً","translation":"وہ معنی جو منصوص حکم کی علت کے طور پر زبان سے معلوم ہو، اجتہاد اور استنباط سے نہیں۔","explanation":"اف کی ممانعت سے زیادہ ایذا کی ممانعت اس کی معروف مثال ہے۔ اسے ہر اجتہادی قیاس کے ساتھ یکساں رکھنا حنفی تقسیم کا فرق مٹا دیتا ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث حكم دلالة النص، ص 104","url":"https://shamela.ws/book/6302/40"},"kind":"definition","originalStudyQuestion":63},{"studyQuestion":63,"term":"الاقتضاء: حد المقدّر","arabic":"يثبت بطريق الضرورة فيقدر بقدر الضرورة","translation":"ضرورت کے راستے سے ثابت ہوتا ہے، اس لیے بقدرِ ضرورت ہی مانا جائے گا۔","explanation":"یہ اقتضاء کی مکمل حد نہیں بلکہ اصل کتاب میں مقتضیٰ کی مقدار کا ضابطہ ہے۔ کلام کی شرعی صحت کے لیے لازم غیر مذکور معنی اس دلالت سے متعلق ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"بحث القبول في البيع، ص 112","url":"https://shamela.ws/book/6302/44"},"kind":"passage","originalStudyQuestion":63}],"originalNumber":63},{"number":64,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":38,"chapter_title":"احناف کے ہاں دلالات نص","question":"دلالۃ النص اور قیاس میں بنیادی فرق کیا ہے؟","answer":["دلالۃ النص میں غیر مذکور صورت کے لیے متعلق معنی زبان اور سیاق سے سمجھ میں آجاتا ہے؛ قیاس میں علت کے ثبوت اور فرع میں اس کے وجود پر اجتہادی استدلال ہوتا ہے۔ والدین کو اف کی ممانعت سے مارنے کی ممانعت حنفی دلالۃ النص کی معروف مثال ہے۔ بعض دوسرے اصولیین اسی نوع کو مفہومِ موافق یا قیاسِ جلی کی تعبیر میں رکھتے ہیں۔ نام کا اختلاف ہر صورت میں نتیجے کا اختلاف نہیں۔","دلالۃ النص میں مشترک معنی اتنا نمایاں ہوتا ہے کہ اہلِ زبان نص سنتے ہی غیر مذکور صورت کا حکم سمجھ لیتے ہیں۔ قیاس میں مجتہد اصل کے حکم، علت اور فرع پر اس علت کے انطباق کی باقاعدہ تحقیق کرتا ہے۔ اس لیے دلالۃ النص کو احناف لسانی دلالت شمار کرتے ہیں، جبکہ قیاس ایک الگ اجتہادی عمل ہے۔","«اف» سے مارنے کی حرمت سمجھنے کے لیے نئی علت اخذ کرنے کی پیچیدہ کوشش نہیں چاہیے؛ اذیت صاف ہے۔ اس کے مقابلے میں شراب کی حرمت کو کسی نئی نشہ آور چیز تک منتقل کرنے میں اسکار کو علت ماننا اور نئی چیز میں اسے ثابت کرنا قیاس ہے۔ دونوں درست ہوسکتے ہیں، مگر ان کی علمی راہ الگ ہے۔"],"definitions":[],"originalNumber":68},{"number":65,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":39,"chapter_title":"منطوق اور مفہوم","question":"منطوق اور مفہوم سے کیا مراد ہے، اور مفہومِ موافقت و مفہومِ مخالفت میں بنیادی فرق کیا ہے؟","answer":["منطوق وہ معنی ہے جو محلِ نطق میں الفاظ کی دلالت سے معلوم ہو؛ یہ صرف نہایت صریح عبارت تک محدود نہیں، غیر صریح منطوق کی اقسام بھی ہیں۔ مفہوم غیر مذکور صورت کا حکم بتاتا ہے۔ مفہومِ موافق میں حکم موافق یا اولیٰ ہوتا ہے؛ مخالف میں معتبر قید کے فقدان سے مختلف حکم سمجھا جاتا ہے۔ سائمہ کی مثال میں جمہور کو یکساں نہ سمجھیں؛ مالکی زکوٰۃ کی بعض شرائط میں شافعی و حنبلی موقف سے مختلف ہیں۔","مفہوم موافق میں غیر مذکور صورت کا حکم، مذکور صورت کے حکم کے موافق ہوتا ہے؛ کبھی زیادہ قوی اور کبھی مساوی۔ مفہوم مخالف میں کسی معتبر قید کے نہ ہونے پر غیر مذکور صورت کے لیے الٹ حکم سمجھا جاتا ہے۔","«اف» کی ممانعت سے مارنے کی حرمت مفہوم موافق ہے۔ حدیث «فِي سَائِمَةِ الْغَنَمِ زَكَاةٌ» سے شافعیہ اور حنابلہ یہ سمجھتے ہیں کہ ہر وقت چارہ کھلائی جانے والی غیر سائمہ بھیڑ میں اسی عنوان سے زکوٰۃ نہیں؛ یہ مفہوم صفت اور مفہوم مخالف ہے۔ پہلی دلالت علت کی قوت پر، دوسری قید کے احترازی ہونے پر قائم ہے۔","منطوق و مفہوم کی تقسیم نص کے براہِ راست بیان اور اس سے سمجھے جانے والے غیر صریح مفہوم کے درمیان فرق قائم کرتی ہے۔ مفہومِ موافق عموماً قوی تر سمجھا جاتا ہے، جبکہ مفہومِ مخالف کی حجیت میں شرط، وصف، غایت، عدد اور لقب جیسے اسالیب کے لحاظ سے تفصیل اور فقہی اختلاف پایا جاتا ہے۔"],"definitions":[],"originalNumber":64},{"number":66,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":39,"chapter_title":"منطوق اور مفہوم","question":"مفہومِ مخالف کی حجیت میں احناف اور جمہور کے مواقف کیوں مختلف ہیں؟","answer":["احناف شرعی خطاب میں محض کسی صورت کے ذکر سے غیر مذکور صورت کا مخالف حکم ثابت نہیں سمجھتے۔ مفہومِ مخالف کے قائل اصولیین احترازی قید کی صورت میں اسے معتبر مانتے ہیں۔ اس اختلاف کو مفہومِ لقب، شرط، وصف، عدد اور غایت کی الگ بحثوں کے ساتھ دیکھنا چاہیے۔ بہت سے فقہاء مفہومِ لقب کو نہیں مانتے، اگرچہ دوسری اقسام قبول کرتے ہیں۔ کسی مکتب کا ایک قسم قبول کرنا تمام اقسام کی غیر مشروط قبولیت نہیں۔","جمہور مالکیہ، شافعیہ اور حنابلہ شرائط کے ساتھ مفہوم مخالف کو حجت مانتے ہیں۔ احناف شرعی نص میں محض تخصیص بالذکر سے غیر مذکور صورت کی نفی کو مستقل دلیل نہیں سمجھتے؛ ان کے نزدیک غیر مذکور کا حکم دوسری دلیل، اصل یا قیاس سے معلوم ہوگا۔","یہ فرق ہر عملی مسئلے میں لازماً مختلف نتیجہ نہیں دیتا۔ احناف کبھی دوسری نص یا علت سے وہی حکم پاتے ہیں جو جمہور مفہوم مخالف سے لیتے ہیں۔ نیز عرفی گفتگو، وصیت، وقف اور معاہدے میں قید کا مفہوم احناف کے ہاں بھی اثر رکھ سکتا ہے، کیونکہ وہاں متکلم کا عرفی قصد اور حقوق کی تحدید خاص اہمیت رکھتے ہیں۔","جمہور متکلمین شرائط کے ساتھ مفہوم مخالف کو شرعی حجت مانتے ہیں۔ احناف کہتے ہیں کہ نص میں کسی صورت کا ذکر، بذاتِ خود غیر مذکور صورت کے مخالف حکم کو لازم نہیں کرتا؛ اس کے لیے الگ دلیل یا اصل چاہیے۔ وہ اسے عموماً «تخصیص الشیء بالذکر» سے لازم نفی نہ ماننے کے اصول سے بیان کرتے ہیں۔","اس کے باوجود احناف عرفی کلام، وقف، وصیت اور معاہدات میں قیود کے مفہوم کو نظر انداز نہیں کرتے۔ اختلاف خاص طور پر نصوصِ شریعت کی دلالت کی درجہ بندی میں ہے، نہ کہ ہر انسانی گفتگو میں قید کو بے معنی قرار دینے میں۔","احناف اور متکلمین دونوں نص سے حکم اخذ کرنا چاہتے ہیں مگر دلالات کی درجہ بندی اور اصطلاحی ساخت میں فرق رکھتے ہیں۔ حنفی منہج عبارت، اشارہ، دلالت اور اقتضاء کے ذریعے معنی کی تہیں واضح کرتا ہے، جبکہ متکلمین منطوق، مفہوم اور متعلقہ اصولوں کے ذریعے اسی میدان کو منظم کرتے ہیں۔"],"definitions":[],"originalNumber":65},{"number":67,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":39,"chapter_title":"منطوق اور مفہوم","question":"مفہومِ مخالف کے معتبر ہونے کے لیے کن شرائط کا پایا جانا ضروری ہے؟","answer":["مفہومِ مخالف کے لیے قید احترازی ہو، محض غالب حالت یا واقعے کی حکایت نہ ہو، اور قوی مخالف دلیل موجود نہ ہو۔ اصل حکم کی علت غیر مذکور صورت میں بھی پائی جائے تو صرف قید کے فقدان سے الٹ حکم اخذ نہیں کیا جائے گا۔ ربیبہ کے زیرِ پرورش ہونے اور ربا کے کئی گنا ہونے کی قیود سے غیر مذکور صورت کی حلت ثابت نہیں ہوتی۔ ہر قید کی غرض اور دوسری نصوص سے نسبت الگ جانچنا ضروری ہے۔","جو فقہاء مفہومِ مخالف کو حجت مانتے ہیں، وہ اس کے لیے کچھ شرائط مقرر کرتے ہیں: قید کا ذکر کسی خاص واقعے یا غالب رواج کے تناظر میں نہ ہو (ورنہ یہ محض 'وصفِ اتفاقی' سمجھا جائے گا)، قید کسی اضافی تاکید کے لیے نہ ہو، اور کوئی اور دلیل اس مخالف مفہوم سے متصادم نہ ہو۔ ان شرائط کے پورا ہونے پر ہی مفہومِ مخالف کو ایک مضبوط اور معتبر دلیل تسلیم کیا جاتا ہے۔","قید احترازی ہو؛ محض غالب حالت، تاکید، مدح، ذم، سوال کے جواب یا واقعے کی تصویر کے لیے نہ ہو۔ منطوق سے قوی دلیل اس کے خلاف نہ ہو۔ غیر مذکور صورت میں وہی قید واقعی غائب ہو۔ اور کلام سے مخالف حکم لینا شارع کے معروف مقصد یا دوسری نصوص کو نہ توڑے۔","مثلاً «ربائبكم اللاتي في حجوركم» میں زیرِ پرورش ہونا غالب حالت ہے، حرمت کی شرط نہیں۔ اسی طرح ﴿لَا تَأْكُلُوا الرِّبَا أَضْعَافًا مُضَاعَفَةً﴾ کا مقصد صرف کئی گنا ربا روکنا نہیں؛ دوسری قطعی نصوص ہر ربا کی حرمت بتاتی ہیں۔ شرطوں کے بغیر مفہوم مخالف غلط حلت پیدا کرسکتا ہے۔","یہاں اصل احتیاط یہ ہے کہ مفہومِ مخالف کو ایسے مقام پر نہ چلایا جائے جہاں قید محض غالب حال، توضیح یا کسی خاص سبب کے لیے آئی ہو۔"],"definitions":[],"originalNumber":73},{"number":68,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":29,"chapter_title":"الفاظ اور دلالات کا تعارف","question":"نصوص کی تعبیر میں سیاق و سباق اور قرینہ کیا کردار ادا کرتے ہیں؟","answer":["سیاق کلام کے اندرونی ربط اور قرینہ معنی متعین کرنے والی اضافی علامت ہے۔ قرینہ لفظی، حالی یا دوسری معتبر دلیل کی صورت میں ہوسکتا ہے۔ سببِ نزول یا ورود سیاق سمجھنے میں مدد دیتا ہے، مگر ہر عام خطاب کو صرف اسی شخص تک محدود نہیں کرتا۔ کسی قید کے غالب حال یا احتراز کے لیے آنے کا تعین بھی قرائن سے ہوگا۔ لفظ کی لغوی گنجائش کے بغیر سیاق کے نام پر نیا معنی ایجاد نہیں کیا جاسکتا۔","اگر کسی آیت یا حدیث کو اس کے سیاق و سباق سے کاٹ کر پڑھا جائے، تو اس کا مفہوم غلط یا نامکمل نکل سکتا ہے، جو کبھی کبھار شریعت کی اصل مراد کے بالکل برعکس نتیجے پر بھی پہنچا سکتا ہے۔ فقہاء نے اسی بنا پر یہ اصول اپنایا ہے کہ کسی حکم کے استنباط سے پہلے متعلقہ آیت یا حدیث کے سابقہ اور بعد کے کلام، اسبابِ نزول یا اسبابِ ورود، اور دیگر متعلقہ نصوص کا مکمل جائزہ لینا ضروری ہے۔","قرینہ سے مراد وہ اضافی شرعی یا سیاقی نشانی ہے جو کسی لفظ کے ظاہری مفہوم کو کسی خاص سمت کی طرف رہنمائی دے، مثلاً کسی امر کے صیغے کو وجوب سے استحباب کی طرف پھیرنا۔ قرینہ لفظی بھی ہو سکتا ہے (جیسے کوئی اور آیت یا حدیث) اور حالی بھی (جیسے کسی خاص واقعے کا سیاق)۔ نصوص کی درست تعبیر کے لیے تمام موجود قرائن کو جمع کر کے دیکھنا ضروری ہے، ورنہ محض ایک لفظ کی سطحی قرات سے غلط نتیجہ نکل سکتا ہے۔","حروفِ معانی بھی حکم پر اثر ڈال سکتے ہیں: واو اصل جمع و اشتراک، فاء ترتیب اور تعقیب، اور ثم ترتیب کے ساتھ تراخی ظاہر کرتی ہے۔ ان کا استعمال سیاق کے ساتھ پڑھا جائے؛ ہر مقام پر صرف ابتدائی لغوی مفہوم کافی نہیں۔ غایت، شرط، استثناء اور نفی بھی حکم کے دائرے کو محدود یا واضح کرتے ہیں۔ ایک حرف پر استدلال کرتے وقت دوسری متعلقہ نصوص کا تعلق ضرور جانچیں۔"],"definitions":[],"originalNumber":66},{"number":69,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":41,"chapter_title":"بیان اور اجمال","question":"بیان اور اجمال سے کیا مراد ہے، اور مجمل نص کو مبین کرنے کے اہم طریقے کون سے ہیں؟","answer":["بیان کسی خطاب کی مراد واضح کرتا ہے؛ کبھی قول، کبھی عمل، کبھی تقریر اور کبھی متعلقہ قرینہ اس کا ذریعہ بنتا ہے۔ حنفی کتابوں میں بیانِ تقریر، تفسیر، تغییر، تبدیل اور ضرورت کی تقسیم بھی ملتی ہے۔ ان کے نام مختلف نوعیت کے توضیحی تعلقات بتاتے ہیں، سب ایک ہی درجے کا اضافہ نہیں۔ بیان کو وقتِ حاجت سے مؤخر کرنے اور نسخ کے ساتھ اس کے تعلق کی بحث بھی ہے؛ اجمال کا مفہوم ان مسائل سے زیادہ واضح ہوتا ہے۔","قرآن نے نماز قائم کرنے کا حکم دیا، مگر اس کی مکمل ہیئت ہر مقام پر بیان نہیں کی۔ نبی ﷺ نے فرمایا: «صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي»۔ آپ ﷺ کی نماز نے رکوع، سجود اور رکعات کی عملی وضاحت کردی۔ یوں بیان اصل حکم کو بدلتا نہیں؛ مکلف کے لیے اس کی مراد قابلِ عمل بناتا ہے۔","اس باب سے یہ اصول مضبوط ہوتا ہے کہ کسی ایک نص کو دوسری متعلقہ نصوص اور نبوی توضیح سے کاٹ کر حتمی حکم اخذ نہیں کیا جانا چاہیے۔","حنفی کتب میں بیانِ تقریر، تفسیر، تغییر، تبدیل اور ضرورت جیسے عنوانات ملتے ہیں۔ بیان کبھی پہلے معنی کو مضبوط، کبھی مجمل کی تفصیل اور کبھی متصل استثناء سے دائرہ واضح کرتا ہے۔ نسخ کو بعض تقسیمات میں بیانِ تبدیل کہا جاتا ہے، مگر ہر شرح یا تخصیص نسخ نہیں۔ ضرورت سے ثابت دلالت بھی بے دلیل قیاس آرائی نہیں؛ اس کا معتبر محل اور شرائط دیکھنا ضروری ہیں۔"],"definitions":[{"studyQuestion":69,"term":"بيان التفسير","arabic":"ما إذا كان اللفظ غير مكشوف المراد فكشفه ببيانه","translation":"جب لفظ کی مراد کھلی نہ ہو اور بیان سے اسے واضح کردیا جائے۔","explanation":"تقریر پہلے سے ظاہر مراد کی توثیق کرتی ہے، جبکہ تفسیر غیر مکشوف مراد کھولتی ہے۔ اصول الشاشی کی سات اقسامِ بیان الگ تفصیل رکھتی ہیں۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"فصل وجوه البيان، ص 245","url":"https://shamela.ws/book/6302/101"},"kind":"definition","originalStudyQuestion":67}],"originalNumber":67},{"number":70,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":40,"chapter_title":"دلالات میں احناف و متکلمین کا تقابلی منہج","question":"احناف اور متکلمین کے ہاں دلالاتِ نص کی درجہ بندی میں بنیادی فرق کیا ہے؟","answer":["حنفی منہج میں چار الگ اعتبارات ہیں: وضع کے لحاظ سے خاص، عام، مشترک، مؤول؛ وضوح کے لحاظ سے ظاہر تا محکم اور خفی تا متشابہ؛ استعمال میں حقیقت، مجاز، صریح، کنایہ؛ اور استدلال میں عبارت، اشارہ، دلالت، اقتضاء۔ متکلمین منطوق و مفہوم اور دیگر تقسیموں سے یہی میدان منظم کرتے ہیں۔ دونوں نظاموں میں جزوی مماثلت ہے، مگر مکمل ایک بہ ایک برابری نہیں۔ شافعی تقسیم کو حنفی چار عنوانات کا عین بدل کہنا درست نہیں۔","فقہی نتیجہ صرف ایک نص کے وجود سے نہیں، اس کے ثبوت، معنی، عموم، تخصیص اور دوسری دلیل سے تعلق پر بنتا ہے۔ اگر دو مذاہب خبرِ واحد، عام یا عرف کا وزن مختلف رکھیں تو ایک ہی مواد سے مختلف احکام نکل سکتے ہیں۔","وضو میں جسم سے خون نکلنے کے مسئلے میں احناف بعض آثار اور قیاس سے نقضِ وضو کہتے ہیں، جبکہ شافعیہ و مالکیہ اصلِ طہارت اور مختلف حدیثی فہم کی بنا پر اسے ناقض نہیں سمجھتے۔ اختلاف محض حدیث ماننے یا نہ ماننے کا نہیں؛ متعلق روایات، علت اور اصلِ مستصحب کی ترتیب مختلف ہے۔","مذاہب اربعہ کے اصولی مناہج کا تقابل کرتے وقت مشترک مصادر اور مختلف ترجیحی قواعد دونوں کو سامنے رکھنا چاہیے۔ سب قرآن و سنت کو بنیاد مانتے ہیں، مگر خبر واحد، عملِ اہلِ مدینہ، استحسان، مصالح، سد ذرائع، قولِ صحابی اور بعض دلالات کے وزن میں فرق پیدا ہوتا ہے۔"],"definitions":[],"originalNumber":69},{"number":71,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":39,"chapter_title":"منطوق اور مفہوم","question":"دلالاتِ الفاظ میں اختلاف کس طرح فقہی فروع میں اختلاف پیدا کرتا ہے؟","answer":["لفظِ قرء کی تعبیر میں حیض اور طہر کا اختلاف عدت کے حساب کو متاثر کرتا ہے۔ اسی طرح عام کی دلالت اور خبرِ واحد سے تخصیص کی شرائط بدلنے سے حکم کا دائرہ مختلف ہوسکتا ہے۔ اختلاف کی صحیح توضیح میں لفظ، معتبر معنی، ہر موقف کے قرائن اور عملی نتیجہ الگ دکھائے جاتے ہیں۔ صرف دو متضاد فتوے نقل کرنا کافی نہیں؛ مشترک نص کے باوجود استدلال کہاں مختلف ہوا، یہ واضح کرنا اصل علمی کام ہے۔","چونکہ حنفی اور دیگر مکاتب کے مابین مفہومِ مخالف کی حجیت پر بنیادی اختلاف پایا جاتا ہے، اس لیے بہت سے فقہی مسائل، جیسے زکوٰۃ کے مخصوص شرائط یا بعض معاہدات کی تفصیلات، میں دونوں مکاتب مختلف نتائج پر پہنچتے ہیں۔ یہی وجہ ہے کہ منطوق و مفہوم کا مبحث اصولِ فقہ کے سب سے زیادہ عملی اثر رکھنے والے مباحث میں شمار ہوتا ہے۔"],"definitions":[],"originalNumber":70},{"number":72,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":29,"chapter_title":"الفاظ اور دلالات کا تعارف","question":"لفظ کے لغوی، شرعی اور عرفی معنی میں تعارض ہو تو ترجیح کس اصول سے دی جائے گی؟","answer":["معنی کی ترجیح خطاب کے مقام، متکلم کے استعمال اور متعلقہ زمانے کے عرف سے ہوگی۔ شرعی عبادتی خطاب میں ثابت شرعی معنی مقدم ہوتا ہے؛ تجارتی معاہدے میں متعلقہ صحیح عرف اہم ہے۔ اگر خاص قرینہ موجود ہو تو اس کی تحقیق بھی ہوگی۔ بعد میں پیدا ہونے والا عرف خودکار طور پر قدیم نص کے معنی نہیں بدلتا۔ لفظ کی لغوی تاریخ اور نزول یا عقد کے وقت کا استعمال جدید رواج سے الگ پہچاننا ضروری ہے۔","حقیقتِ لغویہ وہ معنی ہے جس کے لیے اہلِ زبان نے لفظ وضع کیا، جیسے «صوم» کا اصل معنی رکنا۔ حقیقتِ شرعیہ وہ خاص معنی ہے جو شارع کے استعمال سے معروف ہوا، جیسے صوم: نیت کے ساتھ صبح صادق سے غروب تک مفطرات سے رکنا۔ حقیقتِ عرفیہ وہ معنی ہے جو عام یا خاص عرف میں غالب ہوجائے۔","«صلاة» لغت میں دعا سے متعلق ہے، مگر شریعت میں تکبیر سے شروع اور سلام پر ختم ہونے والی مخصوص عبادت ہے۔ فقہی نص میں نماز کا ذکر ہو تو شرعی حقیقت مقدم ہوگی۔ کسی معاشرتی عقد میں لفظ کا عرفی معنی متعین ہوسکتا ہے، کیونکہ قاعدہ ہے: «اَلْعَادَةُ مُحَكَّمَةٌ»؛ البتہ عرف نصِ شرعی کو منسوخ نہیں کرسکتا۔","وضعِ لغت سے مراد کسی لفظ کا وہ اصل معنی ہے جو عربی زبان میں اس کے لیے مقرر کیا گیا ہو، جبکہ استعمالِ شرعی سے مراد وہ خاص معنی ہے جو شریعت نے کسی لفظ کو ایک نئی اصطلاحی حیثیت دے کر عطا کیا ہو۔ مثال کے طور پر لفظ 'صلاۃ' کا لغوی معنی 'دعا' ہے، مگر شریعت نے اسے ایک مخصوص عبادت (نماز) کے لیے استعمال کیا۔ فقہاء نے ایسے الفاظ کو 'حقیقتِ شرعیہ' کہا ہے، اور ان کی تعبیر میں لغوی معنی کی بجائے شرعی اصطلاحی معنی کو ترجیح دی جاتی ہے۔"],"definitions":[],"originalNumber":71},{"number":73,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":38,"chapter_title":"احناف کے ہاں دلالات نص","question":"دلالتِ عبارت اور دلالتِ اشارہ میں قوتِ استدلال کے اعتبار سے کیا فرق ہے؟","answer":["عبارت اور اشارہ دونوں معتبر معنی دے سکتے ہیں؛ اشارہ صرف کمزور اندازہ نہیں۔ حنفی بیان میں حقیقی تعارض کے مقام پر مقصود عبارت کو غیر مقصود لازم پر ترجیح حاصل ہوتی ہے، مگر متعلقہ ادلہ اور معنی کی قوت بھی دیکھی جائے گی۔ لفظِ نص یہاں عمومی شرعی متن کے لیے ہے؛ اسے ظاہر کے مقابل مخصوص درجۂ نص ہی سمجھنا غلط ہوگا۔ ایک ہی لفظ مختلف اصولی ابواب میں مختلف اصطلاحی معنی رکھ سکتا ہے۔","اگر دلالتِ عبارت اور دلالتِ اشارہ ایک دوسرے سے متصادم ہو جائیں، جو نادر صورت ہے، تو فقہاء عموماً دلالتِ عبارت کو ترجیح دیتے ہیں، کیونکہ یہ نص کا اصل اور بنیادی مقصود ہے، جبکہ دلالتِ اشارہ ایک ثانوی اور ضمنی نتیجہ ہے۔ تاہم عام طور پر یہ دونوں دلالتیں ایک دوسرے سے متصادم نہیں ہوتیں بلکہ ایک ہی نص سے مختلف سطحوں پر مکمل ہم آہنگ احکام فراہم کرتی ہیں۔","عبارت النص کا معنی کلام کے مقاصد میں داخل ہوتا ہے؛ متکلم اسے براہِ راست بیان کرتا ہے۔ اشارۃ النص کا معنی الفاظ سے لازماً نکلتا ہے، مگر سیاق اسے بیان کرنے کے لیے قائم نہیں ہوتا۔ دونوں حجت ہیں، لیکن تعارض کی واقعی صورت میں عبارت کا مقصود معنی اشارے کے غیر مقصود لازم پر مقدم ہوتا ہے۔","روزے کی رات میں ازدواجی تعلق کی اجازت ﴿أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَى نِسَائِكُمْ﴾ سے عبارتاً ثابت ہے۔ فجر تک اس اجازت کے باقی رہنے سے یہ لازم نکلتا ہے کہ جنابت کی حالت میں صبح ہوجائے تو روزہ درست ہوسکتا ہے؛ یہ اشارۃ النص ہے۔"],"definitions":[],"originalNumber":72},{"number":74,"unit_id":7,"unit_name":"یونٹ ہفتم","unit_title":"دلالات نصوص اور اصولی مناہج","chapter_number":40,"chapter_title":"دلالات میں احناف و متکلمین کا تقابلی منہج","question":"کسی نص کی دلالت متعین کرتے وقت زبان، سیاق، دوسری نصوص اور مقاصد کو کس ترتیب سے دیکھا جانا چاہیے؟","answer":["تعبیر کا آغاز متن کے ثبوت اور متعلقہ عربی معنی سے ہوتا ہے، پھر داخلی سیاق، دوسری نصوص، نبوی تبیین اور معتبر قرائن جمع کیے جاتے ہیں۔ اس کے بعد عمومی و خصوصی حکم، علت اور محلِ اطلاق متعین ہوتے ہیں۔ ثابت مقاصد اس مجموعی فہم میں مدد دیتے ہیں۔ یہ مراحل باہم مربوط ہیں؛ ہر تحقیق میں ایک ہی سخت زمانی ترتیب ضروری نہیں۔ اصل شرط یہ ہے کہ کسی مؤثر دلیل کو منتخب نتیجے کی خاطر چھوڑا نہ جائے۔","چونکہ قرآن و سنت عربی زبان میں نازل ہوئے، اس لیے ان کی تعبیر و تشریح کے لیے عربی زبان کے لغوی، نحوی، صرفی اور بلاغی اصولوں کی گہری واقفیت ضروری ہے۔ کسی لفظ کے حقیقی یا مجازی معنی، اس کے واحد یا جمع ہونے، اس کی صرفی ساخت اور اس کے سیاق میں استعمال کا درست فہم ہی درست حکم کے استنباط کی بنیاد ہے۔ اسی لیے مجتہد کے لیے عربی زبان پر مکمل عبور ایک لازمی شرط قرار دی جاتی ہے۔"],"definitions":[],"originalNumber":74},{"number":75,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":43,"chapter_title":"تعارض ادلہ","question":"تعارضِ ادلہ سے کیا مراد ہے، اور کیا معتبر شرعی دلائل میں حقیقی تعارض ممکن ہے؟","answer":["تعارض کا محل ایک ہی وقت، حالت اور موضوع ہونا چاہیے۔ مختلف افراد یا حالات کے لیے مختلف حکم حقیقی تعارض نہیں۔ اصولی اعتقاد میں ثابت وحی آپس میں حقیقی تناقض نہیں رکھتی؛ ظاہری تعارض مجتہد کے سامنے نقل، دلالت یا اطلاق کے مرحلے میں پیش آتا ہے۔ قطعی دلیل کے مقابل ظنی استدلال کو اسی درجے کا مخالف نہیں بنایا جاسکتا۔ پہلے دلیل کی قوت اور محلِ نسبت معلوم ہوگا، پھر حلِ تعارض کی بحث ہوگی۔","اصولی تحقیق فوراً کسی دلیل کو رد نہیں کرتی۔ پہلے ثبوت، دلالت، محل، وقت اور حالت دیکھی جاتی ہے۔ اکثر معلوم ہوتا ہے کہ ایک نص عام اور دوسری خاص، یا ایک حالتِ اختیار اور دوسری ضرورت سے متعلق ہے۔ تب تعارض حل ہوکر دونوں اپنی جگہ حجت رہتی ہیں۔","تعارضِ ادلہ اکثر حقیقی تناقض نہیں بلکہ بظاہر مختلف دلالات، مختلف حالات یا مختلف محلوں کا نتیجہ ہوتا ہے۔ اصولی تحقیق میں صحیح جمع، معتبر ترجیح اور ثابت تاریخی ترتیب کی بنا پر نسخ زیر بحث آتے ہیں؛ ان کی باہمی ترتیب میں مناہج کی تفصیل سوال 76 میں بیان ہوئی ہے۔","یہ ترتیب اس لیے اہم ہے کہ ہر معتبر دلیل کو حتی الامکان اس کے دائرۂ اطلاق میں محفوظ رکھا جائے اور جلد بازی میں کسی نص کو ساقط نہ کیا جائے۔"],"definitions":[],"originalNumber":75},{"number":76,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":43,"chapter_title":"تعارض ادلہ","question":"دو دلائل بظاہر متعارض ہوں تو جمع، تطبیق، ترجیح اور نسخ کی ترتیب کیا ہوگی؟","answer":["حلِ تعارض کی ترتیب میں تمام اصولی مکاتب کو ایک فارمولا نہیں دیا جاسکتا۔ جمہوری مناہج میں ممکن معتبر جمع کو ترجیح حاصل ہے؛ عدمِ جمع پر تاریخِ نسخ اور مرجحات کی تحقیق کی جاتی ہے۔ معروف حنفی بیان میں نسخ، ترجیح، جمع اور پھر متبادل دلیل کی طرف رجوع کی ترتیب ملتی ہے۔ یہ بحث حقیقی طور پر متقابل اور مناسب درجے کی ادلہ میں ہے؛ محض عام و خاص کی ہر نسبت کو پہلے تعارض نہیں کہا جائے گا۔","جمع سے دونوں معتبر دلائل پر عمل محفوظ رہتا ہے، جبکہ ترجیح ایک دلیل کے مقتضا کو مخصوص مسئلے میں چھوڑ دیتی ہے۔ قاعدہ ہے: «إِعْمَالُ الدَّلِيلَيْنِ أَوْلَى مِنْ إِهْمَالِ أَحَدِهِمَا»۔ البتہ جمع لغت، سیاق اور شرعی اصول کے مطابق ہونا چاہیے۔","«لَا عَدْوَى» بیماری کو اللہ سے مستقل مؤثر ماننے کی نفی کرتی ہے، اور «فِرَّ مِنَ الْمَجْذُومِ كَمَا تَفِرُّ مِنَ الْأَسَدِ» اسباب سے بچنے کی تعلیم دیتی ہے۔ دونوں کو جمع کرنے سے توحید اور احتیاط محفوظ رہتے ہیں؛ ایک روایت کو رد کرنے کی ضرورت نہیں۔","انٹرویو میں پہلے پوچھے گئے منہج کو پہچانیں۔ جمہور کی بہت سی تعبیرات میں صحیح جمع مقدم ہے؛ معروف حنفی بحث میں مساوی متعارض دلیلوں کے لیے معلوم تاریخ سے نسخ، پھر ترجیح، پھر ممکن جمع، اور عجز پر دوسری دلیل کی طرف انتقال کی ترتیب ذکر ہوتی ہے۔ یہ اختلاف ابتدائی طور پر تمام نصوص کو متعلقہ محل میں سمجھنے کی ضرورت ختم نہیں کرتا۔ ہر ظاہری فرق حقیقی تعارض نہیں؛ تعارض کی شرائط پہلے ثابت ہونی چاہییں۔"],"definitions":[],"originalNumber":76},{"number":77,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":44,"chapter_title":"ترجیح","question":"ترجیح کیا ہے، اور سند، متن اور مضمون کے اعتبار سے اس کے اہم معیارات کیا ہیں؟","answer":["ترجیح میں سند کی اتصال و صحت، راوی کا ضبط، متن کی صراحت، واقعے سے تعلق اور دوسری معتبر ادلہ کی تائید دیکھی جاتی ہے۔ زیادہ طرق ہمیشہ خودکار ترجیح نہیں؛ بعض طرق کمزور یا ایک ہی اصل پر قائم ہوتے ہیں۔ حاظر و مبیح اور ناقل و مقرر کے مرجحات میں بھی تفصیل و اختلاف ہے۔ معتبر جمع ممکن ہو تو مرجح کے نام پر دوسری دلیل فوراً ترک نہیں کی جاتی؛ منتخب معیار کا مسئلے سے ربط واضح کرنا ضروری ہے۔","ترجیح اس وقت آتی ہے جب مناسب جمع ممکن نہ ہو اور نسخ کی قابلِ اعتماد تاریخ نہ ملے۔ یہ دلیل کو پسند کے مطابق چننا نہیں؛ مرجح قابلِ بیان، متعلق اور اصولی طور پر معتبر ہونا چاہیے۔ نتیجہ مخصوص مسئلے میں راجح عمل ہے، دوسری دلیل کی بے حرمتی نہیں۔","ترجیح کا مطلب ذاتی پسند سے ایک قول چن لینا نہیں، بلکہ متعارض دلائل یا آرا میں قوتِ ثبوت، قوتِ دلالت، موافقتِ اصول، سیاق اور دیگر معتبر قرائن کے ذریعے ایک جانب کو راجح قرار دینا ہے۔ ترجیح کے قواعد تبھی مفید ہیں جب ان کا اطلاق یکساں اور شفاف معیار سے ہو۔","محدثانہ قوت، دلالت کی صراحت، عموم و خصوص، موافقتِ قیاس اور مقاصدی قرائن مختلف مسائل میں مختلف وزن رکھتے ہیں؛ اس لیے ترجیح ہمیشہ مسئلہ مخصوص علمی عمل ہے۔","سند کے اعتبار سے ترجیح کے کچھ معیارات یہ ہیں: خبرِ متواتر کو خبرِ آحاد پر ترجیح دی جاتی ہے؛ راویوں کی تعداد زیادہ ہونے کو کم تعداد پر ترجیح؛ راویوں کے علم و فقاہت میں زیادہ ہونے کو کم پر ترجیح؛ اور راویوں کی عدالت و ضبط میں زیادہ اعتماد رکھنے والی روایت کو کم اعتماد والی پر ترجیح دی جاتی ہے۔ یہ معیارات علمِ حدیث کے اصولوں سے قریبی تعلق رکھتے ہیں۔","متن کے اعتبار سے ترجیح کے معیارات میں شامل ہیں: صریح دلالت رکھنے والی نص کو غیرصریح پر ترجیح؛ حقیقی معنی رکھنے والی نص کو مجازی پر ترجیح؛ حاظر (ممانعت) کو مبیح (اجازت) پر ترجیح (احتیاط کی بنا پر)؛ اور ناقل عن الاصل (اصل حکم سے ہٹانے والی نص) کو مقرر علی الاصل (اصل حکم کو برقرار رکھنے والی نص) پر ترجیح، کیونکہ ناقل زیادہ تفصیلی علم فراہم کرتی ہے۔"],"definitions":[],"originalNumber":77},{"number":78,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":42,"chapter_title":"نسخ","question":"نسخ کی تعریف کیا ہے، اور اس کے تحقق کے لیے کن بنیادی شرائط کا ہونا ضروری ہے؟","answer":["نسخ عہدِ تشریع میں بعد کی معتبر شرعی دلیل سے سابق حکم کی مدت ختم ہونا ہے۔ ناسخ اور منسوخ کا ثبوت، محل کا اتحاد اور معتبر زمانی ترتیب ضروری ہیں۔ پہلے حکم کا وقتی ہونا بعد کی دلیل سے ظاہر ہوتا ہے؛ لازم نہیں کہ پہلی نص ہی میں اس کی مدت لکھی ہو۔ مقرر مدت پوری ہونے سے حکم کا ختم ہونا الگ صورت ہے۔ قیاس، عرف یا مصلحت رسول اللہ ﷺ کے بعد نئی تنسیخ نہیں کرسکتے۔","ابتدا میں مسلمان بیت المقدس کی طرف نماز پڑھتے تھے۔ پھر حکم آیا: ﴿فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾۔ قبلہ بدلنے سے پہلا عمل غلط نہیں ہوا؛ اس کا مقرر زمانہ پورا ہوا۔ یہی تصور نسخ کو انسانی غلطی کی اصلاح سے ممتاز کرتا ہے۔","نسخ دراصل تشریع کے زمانی مراحل کو سمجھنے کا منضبط اصول ہے، نہ کہ نصوص میں بے قاعدہ تناقض فرض کرنے کا طریقہ۔ نسخ ثابت کرنے کے لیے حقیقی تعارض، دونوں دلائل کے جمع نہ ہونے اور متقدم و متأخر کی معتبر معرفت ضروری ہے؛ محض اختلافِ ظاہر نسخ کے لیے کافی نہیں۔","اصولی احتیاط یہ ہے کہ جہاں جمع یا تخصیص ممکن ہو وہاں بلا ضرورت نسخ کا دعویٰ نہ کیا جائے، کیونکہ نسخ ایک ثابت شرعی حکم کے اٹھنے کا دعویٰ ہے اور مضبوط دلیل چاہتا ہے۔","دونوں احکام شرعی ہوں؛ ایک ہی محل اور حالت میں واقعی جمع ممکن نہ ہو؛ ناسخ دلیل منسوخ کے بعد آئی ہو؛ پہلا حکم اپنی ذات میں دائمی ہونے کی قطعی خبر نہ دیتا ہو؛ اور تقدم و تاخر معتبر ذریعے سے ثابت ہو۔ صرف فقہی دشواری یا کمزور روایت نسخ ثابت نہیں کرتی۔","قبلہ کی تبدیلی میں پہلا اور دوسرا رخ ایک نماز میں ایک ہی وقت مستقل حکم نہیں بن سکتے، اور بعد کا حکم تاریخی طور پر معلوم ہے۔ اس کے برخلاف عام و خاص، مطلق و مقید یا مختلف حالات کے احکام جمع ہوسکتے ہیں؛ انہیں فوراً ناسخ و منسوخ کہنا درست نہیں۔"],"definitions":[{"studyQuestion":78,"term":"النسخ","arabic":"وهو أن يرد دليل شرعي متراخيا عن دليل شرعي مقتضيا خلاف حكمه","translation":"نسخ یہ ہے کہ ایک شرعی دلیل بعد میں آ کر پہلی شرعی دلیل کے حکم کے برخلاف تقاضا کرے۔","explanation":"تلویح میں نسخ لغت میں ازالہ اور نقل کے معنی میں ہے۔ ہمارے نزدیک نسخ جائز ہے، یہود اس کے منکر ہیں۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"بحث النسخ","url":"https://shamela.ws/book/9508/492"},"kind":"definition","originalStudyQuestion":78}],"originalNumber":78},{"number":79,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":42,"chapter_title":"نسخ","question":"نسخ اور تخصیص میں بنیادی فرق کیا ہے؟","answer":["نسخ بعد کے وقت کے لیے حکم اٹھاتا ہے، تخصیص عام خطاب کے بعض افراد کو اس کی مراد سے خارج دکھاتی ہے۔ دونوں میں اثر اور زمانے کا فرق اہم ہے۔ حنفی اصول میں منفصل دلیل کے متصل یا متراخی ہونے سے تخصیص و نسخ کی فنی تعبیر متاثر ہوسکتی ہے، اس لیے جمہور کی تعریف کو ہر جگہ حنفی اصطلاح کے برابر نہ سمجھیں۔ کسی خاص نص کا وجود کافی نہیں؛ اس کی تاریخ اور عام سے نسبت بھی معلوم ہونی چاہیے۔","نسخ حکم کی زمانی مدت ختم کرتا ہے، جبکہ تخصیص عام لفظ کے بعض افراد کو ابتدا ہی سے اس حکم کے دائرے سے باہر ظاہر کرتی ہے۔ نسخ میں ناسخ دلیل بعد میں آتی ہے؛ تخصیص میں مخصص متصل بھی ہوسکتا ہے اور منفصل بھی۔ نسخ قطعی طور پر حکم کے ثبوت کے بعد ہوتا ہے، تخصیص مراد کی حد واضح کرتی ہے۔","﴿وَأَحَلَّ اللَّهُ الْبَيْعَ﴾ سے ممنوع بیوع کا اخراج تخصیص ہے؛ وہ معاملات ابتدا ہی سے مطلوب حلت میں داخل نہیں۔ قبلۂ بیت المقدس کا حکم بعد کی آیت سے ختم ہونا نسخ ہے۔ فرق نہ رکھا جائے تو ہر خاص نص کو ناسخ کہنے سے منسوخ آیات کی تعداد بلا ضرورت بڑھ جائے گی۔"],"definitions":[{"studyQuestion":79,"term":"نسخ بطور بیانِ مدت","arabic":"الدَّلِيلُ الثَّانِي بَيَانٌ لِمُدَّةِ الْحُكْمِ الْأَوَّلِ","translation":"بعد کی دلیل پہلے حکم کی اُس مدت کا بیان ہوتی ہے۔","explanation":"نسخ کی بحث میں اس کا مطلب یہ ہے کہ ناسخ اور منسوخ کے درمیان حقیقی تعارض نہیں؛ ناسخ دراصل سابق حکم کی مدت بیان کرتا ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"بحث النسخ","url":"https://shamela.ws/book/9508/494"},"kind":"definition","originalStudyQuestion":79}],"originalNumber":79},{"number":80,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":42,"chapter_title":"نسخ","question":"ناسخ و منسوخ کی معرفت فقہی استنباط میں کیوں اہم ہے، اور زمانی ترتیب کا کیا کردار ہے؟","answer":["ناسخ و منسوخ کی تحقیق سے معلوم ہوتا ہے کہ متعلقہ حکم اب واجب العمل ہے یا عہدِ تشریع میں اس کی مدت ختم ہوچکی تھی۔ تاریخ نبوی تصریح، صحابی کی معتبر خبر یا ثابت واقعے سے معلوم ہوسکتی ہے۔ صرف مصحف میں آیت کا بعد میں ہونا نزول کی تاریخ نہیں۔ حدیث کی کتاب میں ترتیب بھی زمانۂ صدور کی دلیل نہیں۔ تاریخ نامعلوم ہو تو نسخ کا یقینی دعویٰ کرنے کے بجائے جمع، ترجیح اور ثبوت کی مزید تحقیق ہوگی۔","نسخ کے وقوع کی شرائط یہ ہیں: ناسخ اور منسوخ دونوں شرعی احکام ہوں، منسوخ حکم عارضی نوعیت کا ہو نہ کہ ابدی، ناسخ منسوخ کے بعد نازل ہوا ہو، اور دونوں کے مابین حقیقی تضاد پایا جائے جسے جمع کے ذریعے حل نہ کیا جا سکے۔ اگر ان شرائط میں سے کوئی ایک بھی مفقود ہو، تو اسے نسخ نہیں بلکہ تخصیص یا تقیید سمجھا جاتا ہے۔"],"definitions":[],"originalNumber":80},{"number":81,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":43,"chapter_title":"تعارض ادلہ","question":"جمع و تطبیق کو ترجیح یا نسخ پر کیوں مقدم رکھا جاتا ہے؟","answer":["معتبر جمع دونوں دلیلوں کے ممکن درست اطلاق کو محفوظ رکھتا ہے، اس لیے بہت سے اصولیین اسے مقدم کرتے ہیں۔ لیکن ایسا جمع قبول نہیں جو لفظ برداشت نہ کرے یا ثابت سیاق توڑ دے۔ عام کو خاص یا مختلف حالات کو الگ رکھنا مناسب جمع ہوسکتا ہے۔ سوال میں مذکور تقدیم ہر مکتب کی یکساں رسمی ترتیب نہیں؛ حنفی تعارض کے ابواب میں مختلف ترتیب بھی ملتی ہے۔ فائدہ تمام معتبر ادلہ کا درست استعمال ہے، محض مصنوعی ہم آہنگی نہیں۔","صحیح جمع دونوں معتبر دلائل کو ان کے محل میں قابلِ عمل رکھتی ہے۔ مثلاً ایک حکم عام حالت اور دوسرا خاص ضرورت سے متعلق ہو تو ان میں تناقض لازم نہیں آتا۔ لیکن ایسی جمع جو کسی لفظ کو بے دلیل معنی دے یا ثابت تاریخ کو نظرانداز کرے معتبر نہیں۔ اس سوال میں جمع کی تقدیم جمہور کی معروف تعبیر کے لحاظ سے ہے؛ حنفی تعارض کی مخصوص ترتیب سوال 76 میں الگ بیان ہوئی ہے۔ ثابت ناسخ موجود ہو تو محض دونوں پر عمل کے عنوان سے منسوخ حکم برقرار نہیں رکھا جاتا۔"],"definitions":[],"originalNumber":81},{"number":82,"unit_id":8,"unit_name":"یونٹ ہشتم","unit_title":"بیان، نسخ، تعارض اور ترجیح","chapter_number":44,"chapter_title":"ترجیح","question":"اگر جمع اور ترجیح دونوں ممکن نہ ہوں تو مجتہد کے لیے توقف یا دیگر اصولی راستوں کی کیا گنجائش رہتی ہے؟","answer":["توقف کا مطلب کافی دلیل ملنے تک قطعی نسبت سے گریز ہے؛ یہ تحقیق چھوڑنا نہیں۔ عملی ضرورت میں متعلقہ شرعی اصل، براءتِ ذمہ، سابق حالت یا معتبر احتیاط سے کام لیا جاسکتا ہے، مگر ان کا محل بھی ثابت ہونا چاہیے۔ تساقط کا فنی مفہوم خاص استدلال میں متقابل ادلہ سے نتیجہ نہ ملنا ہے، وحی کو غیر معتبر کہنا نہیں۔ بعض اصولیین تخییر کی صورت بھی بیان کرتے ہیں؛ اسے ہر اختلاف میں من مانی انتخاب کی اجازت نہیں سمجھنا چاہیے۔","جب دو نصوص میں ظاہری تعارض نظر آئے، تو مجتہد چار مراحل سے گزرتا ہے: پہلا، جمع و تطبیق (دونوں نصوص کو ایسے سمجھنے کی کوشش کہ ان کے مابین ہم آہنگی پیدا ہو جائے)؛ دوسرا، ناسخ و منسوخ کا تعین (اگر جمع ممکن نہ ہو، تو یہ معلوم کیا جائے کہ کون سی نص بعد میں آئی)؛ تیسرا، ترجیح (اگر ناسخ و منسوخ کا تعین ممکن نہ ہو، تو زیادہ قوی دلیل کو ترجیح دی جائے)؛ اور چوتھا، توقف (اگر مذکورہ تینوں میں سے کوئی طریقہ ممکن نہ ہو، تو فیصلہ مؤخر کر دیا جائے)۔","توقف یہ ہے کہ مجتہد فیصلہ کن دلیل نہ ملنے تک حکم کی نسبت میں رک جائے۔ یہ علمی دیانت ہوسکتی ہے، خصوصاً جب روایت، تاریخ یا محل واضح نہ ہو۔ تساقط کا مطلب دونوں متعارض دلائل کو اس مسئلے میں مؤثر نہ ماننا اور کسی دوسرے اصل کی طرف رجوع کرنا ہے؛ شرعی نصوص میں اسے آخری اور نادر صورت سمجھا جاتا ہے۔","احناف اور جمہور تعارض کے حل کی ترتیب میں تفصیلات رکھتے ہیں، مگر دونوں بلا ضرورت صحیح دلیلیں ساقط نہیں کرتے۔ عملی ضرورت ہو تو سابق یقینی حالت، براءتِ ذمہ یا احتیاط جیسے اصول استعمال ہوسکتے ہیں۔ توقف تحقیق کو روکتا نہیں؛ عارضی فیصلہ محفوظ کرتا ہے۔","جب دلائل واقعی متوازن ہوں، ضروری معلومات یا تاریخ نہ ملے اور حکم کی نسبت میں جلد بازی گمراہ کن ہو تو توقف علمی دیانت ہے۔ اگر معتبر اصول اور کافی شواہد موجود ہوں مگر ذمہ داری یا تنقید کے خوف سے فیصلہ نہ کیا جائے تو یہ غیر ضروری گریز ہے۔","مفتی نئی طبی صورت میں ماہرین کی تحقیق آنے تک رک سکتا ہے۔ لیکن نماز کے معروف حکم میں محض نظری احتمال کی وجہ سے جواب نہ دینا مناسب نہیں۔ توقف کے ساتھ یہ بتانا چاہیے کہ کون سی معلومات مفقود ہیں اور فیصلہ کس معیار پر ممکن ہوگا۔"],"definitions":[],"originalNumber":82},{"number":83,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":45,"chapter_title":"اجتہاد","question":"اجتہاد کی تعریف، مشروعیت اور دائرۂ کار کیا ہے؟","answer":["اجتہاد اہل فقیہ کی شرعی حکم معلوم کرنے کے لیے پوری علمی کوشش ہے۔ اس کی مضبوط نبوی دلیل صحیح بخاری و مسلم کی حدیث ہے کہ اہل حاکم درست اجتہاد پر دو اور خطا پر ایک اجر پاتا ہے۔ حدیثِ معاذ اصولی کتب میں مشہور ہے، مگر اس کی سند پر اہلِ حدیث نے کلام کیا ہے۔ اجتہاد کی مشروعیت کو صرف اسی روایت پر قائم کرنے کی ضرورت نہیں؛ صحیح حدیث اور صحابہ کا ثابت علمی عمل بھی موجود ہے۔","قرآن و سنت میں صریح حکم نہ رکھنے والی نئی صورت، یا موجود نص کے انطباق میں پیچیدگی، اجتہاد کا میدان بنتی ہے۔ مجتہد نصوص، علل، مقاصد اور حقیقتِ واقعہ کو جمع کرتا ہے۔ نتیجہ ظنی ہوسکتا ہے، مگر طریقہ منضبط اور قابلِ جانچ ہونا چاہیے۔","اجتہاد شریعت کے ثابت مصادر اور بدلتے ہوئے واقعات کے درمیان علمی ربط قائم کرتا ہے۔ اس کی صحت اس بات پر منحصر ہے کہ مجتہد نصوص، زبان، اصول، اجماع، علت، مقاصد اور حقیقتِ واقعہ کو مناسب درجے میں سمجھے اور اپنی رائے کو قطعی وحی کے برابر نہ سمجھے۔","اجتہادی نتیجہ ظنی ہوسکتا ہے، لیکن اس تک پہنچنے کا منہج منضبط، قابلِ تنقید اور علمی دیانت پر قائم ہونا چاہیے۔","اجتہاد کی مضبوط حدیثی بنیاد میں صحیح بخاری اور صحیح مسلم کی روایت ہے کہ اہل حاکم اجتہاد کرکے درست پہنچے تو دو اجر اور خطا کرے تو ایک اجر ہے۔ یہ اہلیت اور درست کوشش کے ساتھ متعلق ہے، بے علمی میں فیصلہ کرنے کی اجازت نہیں۔ حدیثِ معاذ مشہور ہے مگر اس کی سند پر کلام ہے؛ اسے بلا توضیح صحیح اور غیر متنازع روایت نہ کہیں۔"],"definitions":[{"studyQuestion":83,"term":"فقیہ راوی (علم و اجتہاد)","arabic":"مَعْرُوف بِالْعلمِ وَالِاجْتِهَاد كالخلفاء الْأَرْبَعَة وَعبد الله بن مَسْعُود وعبد الله بن عَبَّاس وعبد الله بن عمروزيد بن ثَابت ومعاذ بن جبل","translation":"علم و اجتہاد میں مشہور راوی، جیسے چاروں خلفاء، ابن مسعود، ابن عباس، ابن عمر، زید بن ثابت اور معاذ بن جبلؓ۔","explanation":"شاشی کے نزدیک ان کی صحیح روایت قیاس پر عمل سے اولیٰ ہے، جبکہ حفظ و عدالت میں مشہور غیر فقیہ راوی (جیسے ابو ہریرہؓ، انسؓ) کی روایت قیاس کے خلاف ہو تو قیاس کو ترجیح دی جاتی ہے۔","sourceKey":"SHASHI","source":{"book":"أصول الشاشي","section":"تقسيم الراوي","url":"https://shamela.ws/book/6302/113"},"kind":"definition","originalStudyQuestion":83}],"originalNumber":83},{"number":84,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":45,"chapter_title":"اجتہاد","question":"مجتہد کے لیے کن علمی، لسانی اور اخلاقی شرائط کا پایا جانا ضروری ہے؟","answer":["مجتہد کو متعلقہ نصوص، ان کے ثبوت، عربی دلالات، اجماعی مسائل، اصولِ استنباط اور فقہی اختلاف کا کافی علم چاہیے۔ ہر فن کی تمام جزئیات حفظ ہونا لازم نہیں، مگر زیرِ تحقیق مسئلے میں مؤثر دلیل تک رسائی اور اس کی جانچ ضروری ہے۔ اخلاقی دیانت، علمی استقلال اور مفادات سے احتیاط اہم ہیں۔ ماہرین سے تعاون فنی حقیقت واضح کرتا ہے؛ فقیہ کو طب یا معاشیات کی نامکمل سمجھ سے مناط خود فرض نہیں کرنا چاہیے۔","مجتہد بننے کے لیے چند بنیادی شرائط ضروری ہیں: عربی زبان پر مکمل عبور، آیاتِ احکام اور احادیثِ احکام کی گہری معرفت، ناسخ و منسوخ کا علم، اجماعی مسائل کی معرفت (تاکہ اس کے خلاف اجتہاد نہ ہو)، اصولِ فقہ اور قیاس کے قواعد پر عبور، اور مقاصدِ شریعت کی گہری سمجھ۔ ان کے علاوہ تقویٰ، دیانت اور اعتدالِ فکر بھی ضروری سمجھے جاتے ہیں تاکہ مجتہد کی رائے خواہشِ نفس سے متاثر نہ ہو۔","مجتہد کو احکام سے متعلق آیات، ان کے سیاق، عام و خاص، مطلق و مقید، مجمل و مبین، ناسخ و منسوخ اور متعلقہ تفاسیر کا ایسا علم چاہیے جو زیر بحث مسئلے میں تمام مؤثر نصوص جمع کرنے کے قابل بنائے۔ پورا قرآن حفظ ہونا شرط نہیں، مگر متعلقہ مواد تک محققانہ رسائی لازم ہے۔","مثلاً وراثت میں صرف ایک آیت کافی نہیں؛ حصص، کلالہ، وصیت، قرض اور سنتی توضیحات ساتھ دیکھنا ہوں گی۔ جزوی مطالعہ حکم کو ایک آیت سے جوڑ کر دوسرے قطعی اجزا بھلا سکتا ہے۔ علمِ قرآن مقدار سے زیادہ جامع اور اصولی فہم ہے۔","معاصر مجتہد کو قرآن، حدیث، عربی، اصول فقہ، مقاصد، فقہی اختلاف اور قواعد فقہیہ میں مضبوط بنیاد چاہیے۔ اس کے ساتھ مسئلے کے مطابق طب، معاشیات، قانون، سماجیات، ماحولیات یا ٹیکنالوجی کے معتبر ماہرین سے استفادہ ضروری ہے۔ ہر علم میں خود متخصص ہونا لازم نہیں، مگر فنی بیان سمجھنے اور سوال درست رکھنے کی صلاحیت لازم ہے۔","اعضا کی پیوندکاری میں ڈاکٹر جسمانی امکان اور خطرات بتاتا ہے؛ قانون دان رضامندی اور ذمہ داری واضح کرتا ہے؛ فقیہ ان حقائق پر حرمتِ جسم، ضرورت اور دفعِ ضرر کے اصول منطبق کرتا ہے۔ تخصصات شرعی اختیار نہیں لیتے، لیکن صحیح مناط فراہم کرتے ہیں۔","معاصر اجتہاد میں پہلا قدم حکم دینا نہیں بلکہ واقعے کی درست تصویر بنانا ہے۔ نئی ٹیکنالوجی، مالی ساخت یا طبی طریقہ کار کو قدیم نام دے دینا کافی نہیں؛ اس کے مؤثر اوصاف، فریق، خطرات، فوائد، قانونی ماحول اور عملی نتائج سمجھے جاتے ہیں، پھر شرعی اصول منطبق ہوتے ہیں۔","تطبیق کرتے وقت قدیم مثال کی صرف ظاہری مشابہت کافی نہیں؛ مؤثر وصف، علت، حق اور نتیجے کی مماثلت دیکھنا ضروری ہے۔ جدید صورت میں اگر کوئی بنیادی وصف بدل گیا ہو تو پرانے حکم کو خودکار طور پر منتقل کرنے کے بجائے نئی تکییف کی ضرورت ہوگی۔ یہی اصول معاصر فقہ کو جمود اور بے قید تجدد دونوں سے محفوظ رکھتا ہے۔"],"definitions":[],"originalNumber":84},{"number":85,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":46,"chapter_title":"اجتہاد کے مراتب","question":"اجتہادِ مطلق، اجتہاد فی المذہب، اجتہادِ ترجیح اور اجتہادِ جزئی میں کیا فرق ہے؟","answer":["اجتہادِ مطلق وسیع ابواب میں مستقل استنباط کی اہلیت، اجتہاد فی المذہب مذہب کے اصولوں کے اندر تخریج، اور اجتہادِ ترجیح موجود اقوال کے وزن سے متعلق ہے۔ اجتہادِ جزئی کسی خاص باب یا مسئلے میں اہلیت کا عنوان ہے؛ یہ لازماً تقلیدِ مذہب کے اندر ہونا نہیں۔ تجزیۂ اجتہاد کی اجازت و حدود پر اختلاف ہے۔ فردی و اجتماعی تقسیم الگ اعتبار ہے، لہٰذا اجتماعی اجتہاد کو مطلق یا جزئی کا متضاد نہیں کہا جاسکتا۔","تخریج میں مذہب کے اصول یا منقول قول سے غیر مذکور مسئلے کا حکم نکالا جاتا ہے۔ ترجیح میں موجود اقوال و دلائل میں زیادہ قوی موقف متعین کیا جاتا ہے۔ فتویٰ میں راجح یا قابلِ عمل حکم کو سائل کے حقیقی حالات پر منطبق کرکے بتایا جاتا ہے۔","مثلاً قدیم عقد سے جدید مالی صورت کی مماثلت قائم کرنا تخریج، دو منقول حنفی اقوال میں دلیل اور عرف سے ایک کو قوی کہنا ترجیح، اور خاص کاروبار کی مکمل تفصیل سن کر حکم دینا فتویٰ ہے۔ تینوں میں مہارتیں مشترک ہیں، مگر ایک دوسرے کا بدل نہیں۔","اجتہاد کے مراتب یہ واضح کرتے ہیں کہ فقہی اہلیت ایک ہی سطح کا نام نہیں۔ بعض اہل علم مستقل اصولی منہج قائم کرنے کی قدرت رکھتے ہیں، بعض مذہب کے اصولوں کے اندر تخریج و ترجیح کرتے ہیں، اور بعض مخصوص ابواب یا مسائل میں اجتہادی صلاحیت رکھتے ہیں۔","مطلق یا مقید اجتہاد اور کلی یا جزئی اجتہاد الگ نسبتیں ہیں۔ کسی مذہب کے اصولوں میں کام کرنا تقیید کی ایک صورت ہے، جبکہ کسی خاص باب یا مسئلے میں اہلیت جزئی اجتہاد کی بحث ہے۔ مختلف اہلِ علم کی طبقاتی تقسیمیں یکساں نہیں۔ اسی طرح تخریج، ترجیح اور فتویٰ متعلق مگر ممتاز کام ہیں؛ ہر فتوے میں نئے اصول قائم کرنا لازم نہیں۔"],"definitions":[],"originalNumber":85},{"number":86,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":45,"chapter_title":"اجتہاد","question":"کیا بابِ اجتہاد کبھی بند ہوا؟ اس دعوے کو علمی طور پر کیسے سمجھا جانا چاہیے؟","answer":["بابِ اجتہاد کی بندش ایک پیچیدہ تاریخی دعویٰ ہے، کوئی ایسا متفق شرعی حکم نہیں جو بعد کی ہر تحقیق ممنوع کردے۔ بعض ادوار میں مستقل مجتہد کے مرتبے کے دعوے محدود ہوئے، جبکہ تخریج، ترجیح اور نوازل کا اجتہاد جاری رہا۔ قطعی حکم کے خلاف رائے اور ظنی یا نئی تطبیقی صورت میں تحقیق الگ ہیں۔ اجتہاد کی اہلیت بدستور ضروری ہے؛ جدید مسئلے کا نام خود کسی غیر متخصص کو مجتہد نہیں بنادیتا۔","معاصر محقق علماء کی اکثریت اس نظریے کو رد کرتی ہے کہ اجتہاد کا دروازہ ہمیشہ کے لیے بند ہو چکا ہے، اور ان کا موقف ہے کہ اجتہاد ہر دور میں، خصوصاً معاصر نئے مسائل کے لیے، ضروری اور جاری رہنا چاہیے۔ تاہم وہ اس بات پر بھی زور دیتے ہیں کہ اجتہاد کے لیے مطلوبہ شرائط (زبان، نصوص، اصول کی مہارت) بدستور نہایت سخت ہیں، اور آج کل کا اجتہاد زیادہ تر اجتماعی صورت میں انجام دیا جانا چاہیے، انفرادی طور پر نہیں۔","قطعی الثبوت اور قطعی الدلالہ احکام، ضروریاتِ دین اور ثابت اجماع کے خلاف نیا حکم نکالنے کی گنجائش نہیں۔ اجتہاد ظنی دلالت، نئی صورت کے انطباق، تعارضِ ظاہری اور غیر منصوص جزئیات میں ہوتا ہے۔ قاعدہ ہے: «لَا مَسَاغَ لِلِاجْتِهَادِ فِي مَوْرِدِ النَّصِّ الْقَطْعِيِّ»۔","پانچ نمازوں کی فرضیت، زنا اور ربا کی اصل حرمت، اور مقرر قرآنی حصص کو ذاتی مصلحت سے ختم نہیں کیا جاسکتا۔ البتہ نئی مالی مصنوعات میں ربا کی علت، یا نماز کی جدید حالتوں میں استطاعت کا انطباق اجتہادی ہوسکتا ہے۔ نص کی موجودگی اور نص کے اطلاق میں فرق ضروری ہے۔"],"definitions":[],"originalNumber":86},{"number":87,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":47,"chapter_title":"تقلید اور اتباع","question":"تقلید، اتباع اور اجتہاد میں کیا فرق ہے، اور عام مسلمان کے لیے تقلید کی کیا حیثیت ہے؟","answer":["تقلید تفصیلی استنباط کیے بغیر معتبر عالم کی رہنمائی قبول کرنا ہے؛ اتباع کی اصطلاح مختلف اہلِ علم کے ہاں مختلف وسعت رکھتی ہے۔ دلیل سن لینے سے ہر شخص اس کا اہل ناقد نہیں ہوجاتا۔ عامی کی ذمہ داری قابلِ اعتماد اہلِ علم سے رجوع ہے۔ تتبعِ رخص میں محض خواہش سے آسان ترین اقوال جمع کرنے کا خطرہ ہے، جبکہ تلفیق میں مختلف اقوال کے امتزاج کی صحت الگ تحقیق چاہتی ہے؛ ہر انتقالِ مذہب ممنوع نہیں۔","بنیادی فرق دلیل سے واقفیت کا ہے۔ تقلید میں معتبر عالم کا حکم تفصیلی دلیل کے بغیر لیا جاتا ہے؛ اتباع میں دلیل یا کم از کم اس کا اصولی رخ معلوم ہوتا ہے۔ دونوں میں اصل اطاعت اللہ اور رسول ﷺ کی ہے۔","ایک عامی مفتی سے خون نکلنے کے بعد وضو کا حکم پوچھ کر عمل کرے تو یہ تقلید ہے۔ طالب علم احناف کے قیاس و آثار اور جمہور کی احادیث کا مطالعہ کرکے ایک قول اختیار کرے تو اتباع کے قریب ہے۔ صرف ترجمہ پڑھ لینا علمی اہلیت کی ضمانت نہیں۔","تقلید اور اتباع کی بحث عامی، طالب علم اور مجتہد کے علمی مراتب سے جڑی ہے۔ غیر متخصص کا معتبر اہل علم سے مسئلہ پوچھنا علمی تقسیمِ کار کا حصہ ہے، لیکن اندھی جماعتی وابستگی، دلیل کے خلاف تعصب یا اہل علم کے قول کو معصوم سمجھنا الگ چیز ہے۔","عامی پر خود مستقل استنباط لازم نہیں؛ اس کا فرض اہل علم سے پوچھنا ہے۔ قرآن کہتا ہے: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ﴾۔ یہ آیت لاعلم شخص کو اہلِ علم کی طرف رجوع کا اصول دیتی ہے۔","اسے دیانت دار، صاحبِ علم اور مسئلے سے واقف مفتی منتخب کرنا چاہیے۔ صرف آسان جواب تلاش کرنا درست نہیں۔ اگر معتبر علماء میں اختلاف ہو تو عامی زیادہ قابلِ اعتماد عالم، اپنے معروف مذہبی نظام یا احتیاط کے مطابق عمل کرسکتا ہے؛ وہ خود دلائل کا غیر ماہرانہ وزن کرنے کا مکلف نہیں۔"],"definitions":[{"studyQuestion":87,"term":"علمُ المقلِّد","arabic":"وَكَذَا عِلْمُ الْمُقَلِّدِ؛ لِأَنَّهُ لَمْ يَحْصُلْ مِنْ الْأَدِلَّةِ التَّفْصِيلِيَّةِ","translation":"مقلّد کا علم فقہ کی تعریف سے خارج ہے، کیونکہ وہ تفصیلی دلیلوں سے حاصل نہیں ہوا۔","explanation":"یہ شافعی طرز کی تعریفِ فقہ کی شرح میں آیا ہے۔ مطلب یہ ہے کہ تقلید کی پابندی سے علم کا مقام ختم نہیں ہوتا، مگر اصطلاحی فقہ کی تعریف دلیل سے حاصل ہونے پر قائم ہے۔","sourceKey":"TALWIH","source":{"book":"التلويح على التوضيح لمتن التنقيح","section":"تعريف الفقه","url":"https://shamela.ws/book/9508/18"},"kind":"definition","originalStudyQuestion":87}],"originalNumber":87},{"number":88,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":45,"chapter_title":"اجتہاد","question":"اجتماعی اجتہاد کی ضرورت کیوں بڑھی ہے، اور مختلف تخصصات اس میں کیا کردار ادا کرتے ہیں؟","answer":["اجتماعی اجتہاد پیچیدہ مسئلے کے فنی اور فقہی پہلو جمع کرتا ہے۔ اس کی قوت صرف شرکاء کی تعداد نہیں، درست معلومات، واضح منہج، آزاد بحث اور دلیل کی جانچ ہے۔ فقہی اکیڈمی کا فیصلہ اہم علمی وزن رکھتا ہے، مگر بذات خود اجماعِ امت نہیں۔ نئی تحقیق یا بدلے ہوئے حقائق کی بنا پر نظرثانی کی گنجائش رہتی ہے۔ اقلیتی علمی رائے اور فیصلے کی شرائط درج ہونا بعد کی تطبیق کو زیادہ درست بناتا ہے۔","اجتماعی اجتہاد میں فقیہ حکم کے اصول دیکھتا ہے اور متعلقہ ماہر واقعے کی صحیح ساخت واضح کرتا ہے۔ یوں طب، معاشیات، قانون اور ٹیکنالوجی کے پیچیدہ حقائق ایک شخص کی محدود معلومات پر منحصر نہیں رہتے۔ مختلف فقہی مکاتب کی شرکت پوشیدہ اعتراضات بھی سامنے لاتی ہے۔","اعضا کی پیوندکاری میں ڈاکٹر موت اور طبی ضرورت، قانون دان رضامندی اور استحصال، اور فقہاء حرمتِ جسم، ضرورت اور مصلحت کا جائزہ لیتے ہیں۔ اسلامی فقہ اکیڈمیوں کا منظم شورائی عمل اسی فائدے کی مثال ہے۔ تاہم اکثریتی فیصلہ دلیل سے بالاتر یا معصوم نہیں ہوجاتا۔","اجتماعی اجتہاد میں مسئلہ پہلے واضح سوال نامے کی صورت میں مرتب ہوتا ہے۔ فنی ماہرین غیر جانب دار رپورٹ دیتے ہیں۔ فقہاء متعلقہ نصوص، نظائر اور مذاہب کا مطالعہ کرتے ہیں۔ پھر مشترک اجلاس میں سوال، اعتراض اور متبادل آراء زیر بحث آتی ہیں۔ آخر میں دلیل، شرائط اور اختلاف سمیت قرار داد مرتب کی جاتی ہے۔","مجمع الفقہ الاسلامی نے جدید مالی اور طبی مسائل میں اسی طریقے سے ماہرین کی تحقیقات سن کر فیصلے کیے ہیں۔ ادارہ جاتی اکثریت خود اجماع نہیں، مگر وسیع مشاورت انفرادی لغزش کم کرتی ہے۔ مفادات کے ٹکراؤ، اقلیتی رائے اور نئی تحقیق کے بعد نظرثانی کا طریقہ بھی واضح ہونا چاہیے۔","اسی لیے اجتماعی اور بین التخصصی اجتہاد کی اہمیت بڑھی ہے: فنی ماہر حقیقت واضح کرتا ہے اور فقیہ اس حقیقت کو نصوص، قواعد، مقاصد اور مآلات کے ساتھ جوڑ کر حکم تک پہنچتا ہے۔"],"definitions":[],"originalNumber":88},{"number":89,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":48,"chapter_title":"فتویٰ اور افتاء","question":"فتویٰ اور قضاء میں کیا فرق ہے؟","answer":["فتویٰ شرعی رہنمائی ہے، جبکہ قضاء مجاز عدالت کا فریقین کے نزاع میں نافذ فیصلہ ہے۔ دونوں میں حقیقتِ واقعہ کی ضرورت ہے، مگر قضاء میں ثبوت اور قانونی اختیار کے ضابطے خاص اہم ہیں۔ غلط بیان پر لیا گیا فتویٰ ناجائز مال کو حلال نہیں کرتا؛ عدالتی فیصلہ بھی باطن میں معلوم ظلم کو حق نہیں بناتا۔ قضائی الزام اور دیانتی ذمہ داری الگ پہلو ہیں، جنہیں علمی جواب میں ایک دوسرے سے ممتاز رکھنا چاہیے۔","افتاء میں مفتی شرعی حکم بتاتا ہے، جبکہ قضاء میں قاضی فریقین کے نزاع کا لازم فیصلہ کرتا ہے۔ فتویٰ عموماً سائل کی دی ہوئی تفصیل پر قائم ہوتا ہے؛ قضاء میں دعویٰ، جواب، ثبوت، شہادت اور قانونی اختیار بھی دیکھا جاتا ہے۔","ایک شخص قرض کے بارے میں فتویٰ لے سکتا ہے، مگر رقم کی جبری وصولی عدالت کرے گی۔ حدیث «الْبَيِّنَةُ عَلَى الْمُدَّعِي» قضائی ثبوت کی اہمیت دکھاتی ہے۔ ممکن ہے باطن میں حق کسی کے ساتھ ہو، مگر عدالت دستیاب ثبوت کے مطابق فیصلہ کرے۔","فتویٰ محض نظری حکم نہیں بلکہ کسی مخصوص واقعے پر شرعی رہنمائی ہے، اس لیے مفتی کو حکمِ شرعی کے ساتھ سائل کی صورتِ حال، عرف، ضرورت، مآلات اور قانونی ماحول بھی سمجھنا پڑتا ہے۔ ایک ہی فقہی قاعدہ مختلف حقائق کی بنا پر مختلف تطبیق اختیار کرسکتا ہے۔"],"definitions":[],"originalNumber":89},{"number":90,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":48,"chapter_title":"فتویٰ اور افتاء","question":"فتویٰ زمان، مکان، عرف اور حالات کی تبدیلی سے کس حد تک بدل سکتا ہے؟","answer":["زمانہ خود حلال و حرام بدلنے کی علت نہیں۔ تبدیلی عرف، ضرورت، معاشرتی صورت یا وہ وصف بدلنے سے ہوسکتی ہے جس پر اجتہادی فتویٰ قائم تھا۔ کبھی نئی صورت کا الگ حکم اور کبھی پہلے حکم کی نئی تطبیق سامنے آتی ہے؛ اسے صرف موجود اقوال میں آسان قول منتخب کرنا نہیں کہا جاسکتا۔ بدلنے والی بنیاد اور باقی رہنے والی نص کو واضح کیے بغیر تغیرِ فتویٰ کا دعویٰ مبہم رہتا ہے۔","اس اصول کا مطلب یہ ہے کہ فتویٰ اصل شرعی حکم کی نہیں بلکہ اس کے اطلاقی اظہار کی تبدیلی ہے، یعنی جیسے جیسے زمانہ، مقام اور حالات بدلتے ہیں، ویسے ویسے مفتی کو یہ دیکھنا ہوتا ہے کہ کون سی رائے، متعدد جائز رائے میں سے، موجودہ حالات کے مطابق زیادہ مناسب اور مصلحت پر مبنی ہے۔ یہ اصول فتویٰ میں لچک اور موافقت پذیری کی بنیاد فراہم کرتا ہے، بغیر شریعت کے قطعی احکام میں کسی تبدیلی کے۔","جو احکام عرف، مصلحت یا متغیر حالات پر قائم ہوں، ان کا فتویٰ عرف بدلنے سے بدل سکتا ہے؛ قطعی نص کا حکم نہیں بدلتا۔ ابن القیمؒ نے فتویٰ کی تبدیلی میں زمان، مکان، حالات، نیت اور عادات کی اہمیت بیان کی ہے۔","نفقہ کی مناسب مقدار قرآن کے حکم ﴿بِالْمَعْرُوفِ﴾ کے تحت آمدن، قیمتوں اور معاشرتی معیار سے بدلتی ہے۔ پہلے نقد قبضہ ہاتھ سے ہوتا تھا؛ آج معتبر بینک اندراج بعض صورتوں میں حکمی قبضہ شمار ہوسکتا ہے۔ تبدیلی دلیل کے منہج سے ہوگی، فیشن سے نہیں۔"],"definitions":[],"originalNumber":90},{"number":91,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":49,"chapter_title":"اختلاف فقہاء اسباب اور آداب","question":"فقہی اختلاف کے بنیادی اسباب کیا ہیں؟","answer":["اختلاف کے اسباب میں روایت کا پہنچنا یا نہ پہنچنا، اس کی صحت کا اختلاف، الفاظ کی دلالت، جمع و ترجیح، اصولی قواعد اور واقعے کی مختلف تعبیر شامل ہیں۔ ہر اختلاف کو ذاتی پسند یا محض حدیث سے دوری قرار دینا غلط ہے۔ علمی جواب میں پہلے مشترک بنیاد، پھر محلِ نزاع، اور پھر اصل سبب دکھایا جائے۔ کبھی دو فتووں کا فرق اصول کا نہیں بلکہ دو مختلف حالات کا ہوتا ہے۔","اختلافِ فقہاء کے بنیادی اسباب میں شامل ہیں: کسی خبرِ آحاد کا ایک عالم تک پہنچنا اور دوسرے تک نہ پہنچنا، الفاظِ نص کی تعبیر میں اختلاف (حقیقت و مجاز، عام و خاص)، خبرِ آحاد کی حجیت پر مختلف اصولی موقف، قیاس اور ثانوی مصادر (استحسان، مصالحِ مرسلہ) کی حجیت پر اختلاف، اور عرف و مصلحت کے تعین میں فرق۔","اختلاف فقہاء سے مراد اہل اجتہاد کا کسی ظنی یا تطبیقی مسئلے میں مختلف شرعی نتائج تک پہنچنا ہے۔ یہ اختلاف روایت کے ثبوت، لفظ کی دلالت، اصولی قاعدے، عرف یا واقعے کی تشخیص سے پیدا ہوسکتا ہے۔","نماز میں رفع الیدین، بسم اللہ کی قراءت اور بعض معاملات کی شرائط میں معروف اختلاف اسی دائرے سے ہے۔ اختلاف کا وجود یہ نہیں بتاتا کہ حق غیر اہم ہے؛ یہ بتاتا ہے کہ انسانی فہم قطعی وحی نہیں۔ ہر اختلاف معتبر بھی نہیں؛ اہلیت اور دلیل لازم ہیں۔","فقہی اختلاف کے اسباب میں نص کے ثبوت یا دلالت کا فرق، لغوی احتمال، اصولی قاعدے کی ترجیح، حدیث تک رسائی، عرف اور واقعے کی مختلف تکییف شامل ہوسکتے ہیں۔ اس لیے ہر اختلاف کو خواہش یا کم علمی پر محمول کرنا تاریخی اور اصولی طور پر درست نہیں۔","آدابِ اختلاف علمی انصاف، مخالف قول کی درست نمائندگی، دلیل پر گفتگو، شخصی تنقیص سے اجتناب اور قطعی و اجتہادی مسائل میں فرق قائم رکھنے کا نام ہے۔","عرف الفاظ، قیمت، قبضہ، نفقہ اور معاملات کی عملی صورت متعین کرتا ہے۔ جب عرف بدلتا ہے تو عرف پر مبنی فتویٰ بدل سکتا ہے، بشرطیکہ قطعی نص متاثر نہ ہو۔ اسی لیے ایک خطے کا عملی حکم دوسرے میں مختلف ہوسکتا ہے۔","مہرِ مثل، مناسب نفقہ اور عیبِ تجارت کی تعیین مقامی معیار سے ہوتی ہے۔ آج الیکٹرانک بینک اندراج بعض معاملات میں حکمی قبضہ مانا جاتا ہے، جبکہ قدیم صورت ہاتھ سے قبضہ تھی۔ اختلاف شریعت کی تبدیلی نہیں؛ متغیر محل پر ثابت اصول کا نیا انطباق ہے۔"],"definitions":[],"originalNumber":91},{"number":92,"unit_id":9,"unit_name":"یونٹ نہم","unit_title":"اجتہاد، تقلید، افتاء اور اختلاف","chapter_number":49,"chapter_title":"اختلاف فقہاء اسباب اور آداب","question":"اختلافی مسئلے میں علمی ادب کیا ہونا چاہیے، اور اختلاف کو مسلکی تعصب بننے سے کیسے روکا جا سکتا ہے؟","answer":["آدابِ اختلاف میں مخالف کی بات درست نقل کرنا، معتبر دلیل کا احترام اور تنقید کو مسئلے تک محدود رکھنا بنیادی ہیں۔ اختلاف کا معتبر ہونا ہر قول کو برابر مضبوط نہیں بناتا؛ ترجیح دلیل سے ہوسکتی ہے۔ واضح نص کے مقابل بے دلیل دعویٰ اور اہلِ اجتہاد کا قابلِ فہم اختلاف ایک درجہ نہیں رکھتے۔ عامی کو اختلاف سن کر خود مجتہد بننے کے بجائے معتبر رہنمائی اختیار کرنی چاہیے۔","مخالف موقف کو اس کے مستند ماخذ اور مضبوط دلیل سے بیان کیا جائے، کمزور عبارت سے نہیں۔ نیت پر حملہ، تحقیر اور قطعی زبان سے اجتناب ہو۔ ساتھ ہی اپنی ترجیح کی دلیل صاف پیش کی جائے۔","ائمہ نے ایک دوسرے سے اختلاف کے باوجود روایت اور فقہ سے فائدہ اٹھایا۔ امام شافعیؒ سے منقول علمی رویہ ہے کہ مناظرہ حق کے ظاہر ہونے کے لیے ہو۔ ادب کا مطلب سب اقوال برابر کہنا نہیں؛ ترجیح کے ساتھ صاحبِ علم کی عزت محفوظ رکھنا ہے۔","اختلافِ تنوع سے مراد وہ اختلاف ہے جس میں مختلف آراء میں سے ہر ایک، اپنی جگہ، ایک مخصوص حالت یا صورت میں درست ہو سکتی ہے، جیسے نماز میں تشہد کی مختلف مسنون صورتیں، جو سب نبی کریم ﷺ سے ثابت ہیں۔ اختلافِ تضاد سے مراد وہ اختلاف ہے جس میں دو آراء ایک دوسرے سے حقیقی طور پر متصادم ہوں، اور دونوں بیک وقت درست نہیں ہو سکتیں، جیسے کسی چیز کے حلال یا حرام ہونے پر اختلاف۔"],"definitions":[],"originalNumber":92},{"number":93,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"فقہی مذاہب کے وجود میں آنے، منظم ہونے اور مختلف علاقوں میں پھیلنے کے بنیادی اسباب کیا تھے؟","answer":["فقہی مذاہب صرف بانی امام کی ذاتی آراء کا مجموعہ نہیں؛ ان میں شاگردوں کی روایت، تدوین، تخریج، ترجیح اور بعد کے مفتیان کی تحقیق بھی شامل ہے۔ کسی امام کی ایک منقول رائے کو پورے مذہب کا مفتیٰ بہ موقف کہنے سے پہلے اس کی نسبت اور درجۂ اعتماد دیکھنا ضروری ہے۔ تاریخی تعارف میں زمانہ، علمی ماحول، اہم شاگرد اور بنیادی کتابیں الگ پہچاننے سے مذہب کی تشکیل واضح ہوتی ہے۔","فقہی مذہب سے مراد کسی مجتہد کا وہ مکمل اور مربوط اصولی و فروعی نظام ہے جو اس کے اپنے مخصوص طریقہائے استنباط اور فقہی آراء پر مشتمل ہو، اور جسے اس کے شاگردوں اور پیروکاروں نے مدون اور محفوظ کیا ہو۔ ایک مکمل فقہی مذہب میں نہ صرف فروعی مسائل بلکہ ان کے پیچھے کارفرما اصولی منہج بھی شامل ہوتا ہے، جو اسے محض چند متفرق آراء سے ممتاز کرتا ہے۔","سب سے پہلے امام ابوحنیفہ (م ۱۵۰ھ) کی قیادت میں حنفی مذہب کوفہ میں پروان چڑھا، پھر امام مالک (م ۱۷۹ھ) نے مدینہ میں مالکی مذہب کی بنیاد رکھی، اس کے بعد امام شافعی (م ۲۰۴ھ) نے دونوں مکاتب (رائے اور حدیث) کے امتزاج سے شافعی مذہب مرتب کیا اور اصولِ فقہ کو باقاعدہ مستقل علم کی شکل دی، اور آخر میں امام احمد بن حنبل (م ۲۴۱ھ) نے حنبلی مذہب کی بنیاد رکھی جو حدیث پر زیادہ انحصار کرتا ہے۔ ان چاروں ائمہ کے مذاہب آج تک اہلِ سنت میں رائج ہیں۔"],"definitions":[],"originalNumber":93},{"number":94,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":50,"chapter_title":"حنفی منہج اصول فقہ","question":"حنفی اصولی منہج کی نمایاں خصوصیات کیا ہیں؟","answer":["حنفی منہج میں قرآن و سنت بنیادی حجت ہیں، اور اجماع، قیاس و استحسان کو ان کے متعلق اصولی ضابطوں کے ساتھ برتا جاتا ہے۔ اسے محض عقل کا مذہب کہنا درست نہیں۔ ظاہر الروایہ، تخریج اور ترجیح کے درجات سے مذہب کا معتمد قول معلوم ہوتا ہے۔ خبرِ واحد اور عام کے تعلق جیسے مباحث میں حنفی اصول کی خصوصیت سمجھنا زیادہ مفید ہے بنسبت اس عمومی دعوے کے کہ ہر مسئلہ قیاس سے حل ہوتا ہے۔","حنفی منہج نصوص کی دلالت، فروع کے استقراء، قیاس، استحسان، عرف اور عملی فقہی نتائج کے مضبوط ربط سے پہچانا جاتا ہے۔ احناف نے فرض و واجب، فاسد و باطل، اور عام و خاص کی دلالت میں دقیق درجات قائم کیے۔","اس منہج میں قرآن، سنت اور اجماع بنیادی حجت ہیں؛ قیاس نص کے تابع ہے۔ استحسان قاعدے سے خواہش پر خروج نہیں، بلکہ قوی تر دلیل سے ظاہر قیاس ترک کرنا ہے۔ دبوسیؒ، بزدویؒ اور سرخسیؒ نے اس روایت کو منظم اصطلاحات اور فروعی مثالوں کے ساتھ واضح کیا۔","حنفی اصول کی صحیح تفہیم کے لیے اصول السرخسی، اصول البزدوی اور کشف الأسرار جیسے متون کو فقہی فروع کے ساتھ پڑھنا مفید ہے، کیونکہ اس روایت میں اصول اور فروع کا باہمی تعلق بہت نمایاں ہے۔"],"definitions":[],"originalNumber":94},{"number":95,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":51,"chapter_title":"مالکی منہج اصول فقہ","question":"مالکی اصولی منہج کی نمایاں خصوصیات کیا ہیں؟","answer":["مالکی فقہ میں نصوص کے ساتھ عملِ اہلِ مدینہ، مصالح اور سدِ ذرائع کی بحث نمایاں ہے۔ عملِ مدینہ کی ہر صورت برابر درجۂ حجت نہیں؛ منقول عملی روایت اور اجتہادی عمل کا فرق اہم ہے۔ مصلحت بھی ہر پسندیدہ فائدے کا نام نہیں بلکہ شرعی ضابطوں میں قابلِ اعتبار فائدہ ہے۔ امام مالک اور بعد کے مالکی محققین کے اقوال میں تفصیل ہوسکتی ہے، اس لیے ایک مختصر تعارف کو ہر مسئلے کا حتمی ضابطہ نہ بنائیں۔","مالکی منہج قرآن و سنت کو اصل بناتا ہے اور اجماع، قیاس، عملِ اہلِ مدینہ، مصالحِ مرسلہ، سدِّ ذرائع، عرف اور قولِ صحابی سے منضبط استفادہ کرتا ہے۔ اس کی نمایاں خوبی یہ ہے کہ نص، عملی سنت، انسانی مصلحت اور نتائجِ اعمال کو ایک مربوط نظام میں دیکھتا ہے۔","مثلاً کسی مباح معاملے سے غالب طور پر حرام نتیجہ پیدا ہو تو سدِّ ذرائع زیرِ بحث آتا ہے۔ اور کوئی نئی اجتماعی ضرورت نص سے نہ ٹکراتی ہو تو مصلحتِ مرسلہ رہنمائی دے سکتی ہے۔ تاہم ہر دلیل کی اپنی شرط ہے؛ مالکی منہج بے قید مصلحت پسندی نہیں۔","مالکی منہج نصوص کے ساتھ عملِ اہلِ مدینہ، مصالحِ مرسلہ، سدِّ ذرائع اور عرف جیسے اصولوں کو منضبط طور پر استعمال کرتا ہے۔ اس سے یہ منہج عملی توارث، اجتماعی مصلحت اور افعال کے نتائج کو فقہی استدلال میں نمایاں جگہ دیتا ہے۔","الموطأ، المدونة اور بعد کے مالکی اصولی متون کے ساتھ امام شاطبی کی الموافقات اس منہج کی مقاصدی و مصلحتی جہت کو سمجھنے میں خاص اہمیت رکھتی ہے۔"],"definitions":[],"originalNumber":95},{"number":96,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":52,"chapter_title":"شافعی منہج اصول فقہ","question":"شافعی اصولی منہج کی نمایاں خصوصیات کیا ہیں؟","answer":["شافعی منہج میں نص کی دلالت، سنت کی حجیت اور منضبط قیاس مرکزی اہمیت رکھتے ہیں۔ استحسان پر نقد کا مطلب ہر مصلحت یا ہر غیر لفظی استدلال کا انکار نہیں بلکہ بے ضابطہ ترجیح پر اعتراض ہے۔ امام شافعی کے قولِ قدیم و جدید کا فرق تاریخی اور علمی پس منظر رکھتا ہے۔ معتمد مذہبی موقف معلوم کرتے وقت امام کی منفرد عبارت، اصحاب کی تخریج اور متاخرین کی ترجیح کو جدا رکھنا چاہیے۔","شافعی منہج قرآن و سنت کی حجیت، عربی دلالات، اجماع کی محتاط تعریف اور منضبط قیاس پر قائم ہے۔ امام شافعیؒ نے دلیل کے مراتب واضح کیے اور شخصی پسند کو استدلال کا بدل بنانے کی مخالفت کی۔","اس منہج میں صحیح سنت قرآن کی توضیح اور مستقل حجت دونوں ہے۔ خبرِ واحد شرائط کے ساتھ قبول ہوتی ہے، اور غیر منصوص مسئلے میں معتبر علت کے ذریعے قیاس کیا جاتا ہے۔ «استحسان» پر نقد کا مقصد بے دلیل ترجیح روکنا تھا۔ اس لیے شافعی منہج نص پسندی اور عقلی استنباط کو باقاعدہ علمی قواعد میں جمع کرتا ہے۔","شافعی منہج نے اصول فقہ کی باقاعدہ تدوین میں فیصلہ کن کردار ادا کیا۔ قرآن، سنت، اجماع اور قیاس کی حجیت اور باہمی نسبت کو منظم انداز میں بیان کرکے امام شافعی نے استدلال کو لسانی و نصی اصولوں سے مضبوط کیا اور غیر منضبط استحسان پر تنقید کی۔","الرسالہ اس روایت کی بنیاد ہے، جبکہ بعد میں الجوینی، الغزالی اور دیگر متکلم اصولیین نے اسی علمی سمت کو زیادہ تجریدی اور منظم صورت دی۔"],"definitions":[],"originalNumber":96},{"number":97,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":53,"chapter_title":"حنبلی منہج اصول فقہ","question":"حنبلی اصولی منہج کی نمایاں خصوصیات کیا ہیں؟","answer":["حنبلی منہج میں آثار اور نصوص کو نمایاں وزن دیا جاتا ہے، مگر ضعیف روایت کی بحث کو یوں نہ سمجھیں کہ ہر غیر موضوع حدیث لازماً حجت ہے۔ ضعف کے درجات، دیگر قرائن، تعارض اور امام احمد کی اصطلاح کا لحاظ ضروری ہے۔ بعض قدیم استعمالات میں ضعیف کا مفہوم بعد کی اصطلاح سے یکساں نہیں۔ قیاس بھی معتبر شرائط کے ساتھ استعمال ہوتا ہے؛ مذہب کو صرف ظاہری الفاظ تک محدود کہنا ناقص تعارف ہے۔","بعد کی حنبلی روایت میں سدِّ ذرائع، مصلحت، عرف، مقاصد اور مآلات بھی نمایاں ہوئے، خاص طور پر ابن تیمیہؒ اور ابن قیمؒ کے ہاں۔ اس لیے اسے محض لفظی جمود کہنا درست نہیں۔ اس کی اصل قوت نص کے احترام اور عملی حالات میں صحیح معنی کی تلاش کا امتزاج ہے۔","حنبلی منہج نصوص و آثار سے گہری وابستگی، صحابہ کے فتاویٰ کی قدر، قیاس کے محتاط استعمال اور ضرورت کے مقام پر مصالح و ذرائع جیسے اصولوں کی گنجائش سے پہچانا جاتا ہے۔ اسے محض ظاہریت کہنا درست نہیں، کیونکہ حنبلی فقہ میں علت، مصلحت اور عرف کی عملی بحث بھی موجود ہے۔","امام احمد کے فقہی آثار، ابن قدامہ کی روضۃ الناظر اور بعد میں ابن تیمیہ و ابن القیم کی اصولی و مقاصدی تحریریں اس منہج کے مختلف پہلو واضح کرتی ہیں۔"],"definitions":[],"originalNumber":97},{"number":98,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"مذاہبِ اربعہ کے ہاں مصادرِ شرعیہ کی ترتیب اور ثانوی دلائل کے استعمال میں کیا اہم فرق پایا جاتا ہے؟","answer":["مذاہب کا تقابل صرف مصادر کی فہرست سے مکمل نہیں ہوتا؛ کسی دلیل کی حجیت، اس کے استعمال کی شرائط، اور دوسری دلیل سے تعارض کا طریقہ بھی دیکھنا پڑتا ہے۔ چاروں مذاہب قرآن و سنت کو اصل مانتے ہیں، مگر خبرِ واحد، عام، مفہومِ مخالفت اور مصالح کی بعض تطبیقات میں فرق ہوسکتا ہے۔ ایک جدول ابتدائی نقشہ ہے؛ جزوی مسئلے میں متعلقہ امام یا معتمد مذہبی ماخذ کی تحقیق ضروری رہتی ہے۔","چاروں مذاہب قرآن، سنت، اجماع اور قیاس کی اصل حجیت تسلیم کرتے ہیں۔ اختلاف زیادہ تر ثبوت، دلالت، ترجیح اور اضافی اصولوں کے وزن میں ہے۔ احناف استحسان و عرف، مالکیہ عملِ اہلِ مدینہ و مصلحت، شافعیہ منضبط قیاس، اور حنابلہ آثار و سدِّ ذرائع کو نمایاں طور پر برتتے ہیں۔","یہ خلاصہ مطلق تقسیم نہیں۔ ہر مذہب میں نص مقدم ہے اور دوسرے اصول شرطوں کے تابع ہیں۔ مثلاً مالکیہ قیاس بھی کرتے ہیں اور احناف حدیث بھی قبول کرتے ہیں۔ تقابل کا صحیح طریقہ یہ ہے کہ مشترک بنیاد کے اندر ترجیحی فرق دیکھا جائے، نہ کہ ہر مذہب کو صرف ایک دلیل تک محدود کردیا جائے۔","یہ اختلاف فقہی تنوع کی علمی بنیاد سمجھاتا ہے اور یہ بھی دکھاتا ہے کہ مختلف نتائج ہمیشہ مختلف نصوص کی وجہ سے نہیں بلکہ کبھی ایک ہی نص کے اصولی فہم کے فرق سے پیدا ہوتے ہیں۔"],"definitions":[],"originalNumber":98},{"number":99,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"فقہی اختلاف کو صرف نتائج سے نہیں بلکہ اصولی مقدمات سے سمجھنا کیوں ضروری ہے؟","answer":["کسی فقہی نتیجے کے پیچھے اصول پہچاننے کے لیے پہلے اصل دلیل، پھر اس کی دلالت، پھر مخالف دلیل کا جواب معلوم کریں۔ ایک فرع سے پورے مذہب کا مستقل اصول اخذ کرنا جلدبازی ہے؛ دوسری فروع اور صریح اصولی عبارت بھی دیکھیں۔ مثال کے طور پر حکم میں فرق کبھی لفظ کی عمومیت سے، کبھی روایت کی قبولیت سے اور کبھی علت کے اثبات سے پیدا ہوتا ہے؛ یہ الگ نوعیت کے اختلافات ہیں۔","لفظ قرء کی تعبیر میں ایک فقیہ حیض اور دوسرا طہر مراد لیتا ہے۔ اختلاف صرف آخری عدت کے حساب میں نہیں؛ لغت، سیاق اور متعلقہ قرائن کی ترجیح میں بھی ہے۔ اسی لیے پہلے مشترک لفظ کا اصول سمجھیں، پھر اس مسئلے میں پیش کردہ خاص دلیل جانچیں۔ اس طریقے سے مخالف قول کی علمی بنیاد سامنے آتی ہے۔ ہر اختلاف کو اسی ایک مثال کے اصول پر قیاس نہ کریں؛ روایت کے ثبوت یا واقعے کی صورت میں فرق ہو تو تحقیق کا راستہ بھی بدل جاتا ہے۔"],"definitions":[],"originalNumber":99},{"number":100,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"تقابلی فقہ کے مطالعے کا صحیح منہج کیا ہے، اور ترجیح میں کن اصولوں کا لحاظ کیا جاتا ہے؟","answer":["فقہِ مقارن میں اقوال کی درست نسبت، محلِ نزاع کی تحدید، دلائل کا منصفانہ بیان اور اصولی بنیادوں کا تقابل مطلوب ہے۔ صرف آسان یا جدید محسوس ہونے والے قول کو منتخب کرنا علمی ترجیح نہیں۔ راجح قرار دینے کے لیے دلیل، دلالت اور معارض کا جواب واضح ہونا چاہیے۔ طالب علم تحقیق اور عملی فتویٰ کے درجے الگ رکھے؛ موازنہ سیکھ لینے سے ہر شخص حساس عملی فیصلوں میں مستقل مفتی نہیں بن جاتا۔","تقابلی فقہ کا بنیادی طریقہ کار یہ ہے: پہلے مسئلے کو واضح طور پر بیان کیا جاتا ہے، پھر مختلف مذاہب کی آراء کو الگ الگ جمع کیا جاتا ہے، ہر مذہب کے دلائل کو تفصیل سے پیش کیا جاتا ہے، ان دلائل پر ممکنہ اعتراضات اور ان کے جوابات بیان کیے جاتے ہیں، اور آخر میں دلائل کی قوت کی روشنی میں راجح رائے کا تعین کیا جاتا ہے، یا کم از کم ہر مذہب کی رائے کی علمی بنیاد کو واضح کیا جاتا ہے۔","الترجیح تقابلی فقہ کا حتمی اور اہم ترین مرحلہ ہے، جس میں محقق مختلف مذاہب کے دلائل کا موازنہ کر کے یہ فیصلہ کرتا ہے کہ کون سی رائے زیادہ مضبوط دلیل پر مبنی، مقاصدِ شریعت سے زیادہ ہم آہنگ، اور موجودہ حالات کے لیے زیادہ موزوں ہے۔ یہ عمل خالص علمی دیانتداری کا تقاضا کرتا ہے، تاکہ محقق کسی مذہب کی طرفداری کی بجائے، حقیقی دلائل کی بنیاد پر فیصلہ کرے۔"],"definitions":[],"originalNumber":100},{"number":101,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"فقہ مقارن یونیورسٹی کی تدریس میں کیوں اہم ہے، اور یہ طالب علم کی علمی صلاحیت کو کیسے مضبوط کرتا ہے؟","answer":["تدریس میں پہلے ایک منضبط فقہی و اصولی بنیاد قائم کرنا، پھر منتخب مسائل میں تقابلی مطالعہ کرانا مفید ہے۔ ایک مذہب کے ذریعے بنیادی تربیت علمی کمزوری نہیں؛ تعصب اور دوسرے معتبر مناہج سے بے خبری الگ مسئلے ہیں۔ تقابل میں طلبہ کو ہر قول کی دلیل اور داخلی منطق سمجھائیں۔ ابتدا ہی میں بہت سے اقوال بلا ضابطہ جمع کرنے سے الجھن پیدا ہوسکتی ہے، جبکہ تدریجی تقابل فہم کو مضبوط کرتا ہے۔","تقابلی فقہ کا مسلسل مطالعہ طالب علم کو ایک ایسی صلاحیت عطا کرتا ہے جس سے وہ کسی بھی مسئلے کو صرف ایک زاویے سے نہیں بلکہ متعدد زاویوں سے دیکھ سکتا ہے، ہر رائے کی مضبوطی اور کمزوری کو پہچان سکتا ہے، اور دلائل کی بنیاد پر اپنا آزادانہ اور متوازن فیصلہ قائم کر سکتا ہے۔ یہ صلاحیت خصوصی طور پر ان طلبہ کے لیے قیمتی ہے جو مستقبل میں افتاء، عدالتی یا تحقیقی خدمات انجام دینا چاہتے ہوں۔","معاصر دور میں تقابلی فقہ کی اہمیت اس لیے بڑھ گئی ہے کیونکہ نئے پیچیدہ مسائل، جیسے اسلامی بینکاری، طبی اخلاقیات، اور عائلی قوانین کی جدید تشکیل، اکثر کسی ایک مذہب کی محدود آراء سے مکمل طور پر حل نہیں ہوتے۔ مختلف مذاہب کی متنوع آراء کا وسیع تقابلی مطالعہ، معاصر مجتہدین کو ایک زیادہ جامع اور لچکدار حل تلاش کرنے کی صلاحیت عطا کرتا ہے، جو ایک ہی مذہب کی محدود نظر سے ممکن نہیں۔"],"definitions":[],"originalNumber":101},{"number":102,"unit_id":10,"unit_name":"یونٹ دہم","unit_title":"فقہی مذاہب اور اصولی مناہج","chapter_number":54,"chapter_title":"مذاہب اربعہ کے اصولی مناہج کا تقابل","question":"المبسوط، بدائع الصنائع، بدایۃ المجتہد، المغنی اور المجموع جیسی کتب کا تقابلی فقہی مطالعے میں کیا مقام ہے؟","answer":["کتاب کا انتخاب مقصد کے مطابق ہو: اصول الشاشی اور نور الانوار حنفی اصول کی بنیادی تربیت کے لیے، الرسالہ شافعی استدلال کی ابتدائی کلاسیکی صورت کے لیے، اور بدایۃ المجتہد فقہی اختلاف کے اسباب کے لیے اہم ہیں۔ اصولی متن، اس کی شرح، فروع کی کتاب اور فتویٰ کی کتاب ایک نوع نہیں۔ کسی کتاب کی عبارت سمجھنے میں مصنف کا منہج، اصطلاحات، نسخے کی صحت اور شرح سے متن کا امتیاز پہلے دیکھیں۔","المبسوط امام سرخسی کی مفصل حنفی فقہی کتاب ہے، جس میں دلائل اور دیگر اقوال سے بحث ملتی ہے۔ بدائع الصنائع امام کاسانی کی منظم حنفی تصنیف ہے جو ابواب، شرائط اور علتوں کی ترتیب سمجھاتی ہے۔ یہ دونوں فقہی کتابیں ہیں؛ اصول السرخسی مستقل اصولی تصنیف ہے۔ ان کا تقابل بدایۃ المجتہد، المغنی اور المجموع سے کرتے وقت ہر مصنف کے مذہب، مقصد اور اصطلاحات کو ملحوظ رکھیں۔","ابن رشد (حفید) کی بدایۃ المجتہد ونہایۃ المقتصد تقابلی فقہ کی نمایاں ترین کلاسیکی تصنیف ہے، جس میں انہوں نے مختلف مذاہب کی آراء کا دلائل کے ساتھ منظم موازنہ پیش کیا، اور اختلاف کے بنیادی اصولی اسباب کا بھی تجزیہ کیا۔ یہ کتاب آج بھی تقابلی فقہ کے طالب علموں کے لیے ایک بنیادی اور نہایت مفید حوالہ سمجھی جاتی ہے۔","ابن قیم جوزیہ کی اعلام الموقعین عن رب العالمین فتویٰ، اجتہاد اور فقہی منہج پر ایک تفصیلی اور عملی حوالہ ہے۔ اس کتاب کی خصوصیت یہ ہے کہ یہ خشک نظریاتی مباحث کی بجائے عملی مسائل، مفتی کی ذمہ داریوں اور احکام کے تغیر پذیر ہونے پر گہرا اور عملی زور دیتی ہے، جو معاصر فقہاء کے لیے بھی رہنما حیثیت رکھتی ہے۔","المغنی ابن قدامہ کی فقہی کتاب ہے جس میں حنبلی مسائل کے ساتھ دیگر اقوال اور دلائل کی بحث ملتی ہے۔ المجموع شرح المهذب امام نووی کی شافعی فقہی شرح ہے، جس میں حدیثی اور تقابلی تحقیق نمایاں ہے۔ بدایۃ المجتہد اختلاف کے اسباب پر خاص توجہ دیتی ہے۔ ان کتابوں کو ایک ہی مذہب یا محض اصولی متن کی حیثیت سے پیش کرنا درست نہیں؛ مطالعے کا مقصد پہلے متعین کریں۔"],"definitions":[],"originalNumber":102},{"number":103,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":55,"chapter_title":"اصول فقہ اور قواعد فقہیہ","question":"قواعدِ فقہیہ اور قواعدِ اصولیہ میں بنیادی فرق کیا ہے؟","answer":["اصولی قاعدہ دلائل سے حکم اخذ کرنے کے طریقے سے متعلق ہوتا ہے، جبکہ فقہی قاعدہ متعدد عملی احکام میں مشترک معنی بیان کرتا ہے۔ فقہی ضابطہ عموماً ایک باب کی فروع جمع کرتا ہے۔ ان کی حدود ہمیشہ صرف نام سے طے نہیں ہوتیں، اس لیے مثال اور استعمال دیکھنا چاہیے۔ قواعد فہم و ترتیب میں مدد دیتے ہیں، مگر خاص نص، مستثنیٰ صورت یا شرط کو نظرانداز کرکے خودکار فیصلہ نہیں دے سکتے۔","اصول فقہ کا موضوع ادلۂ شرعیہ، ان کی دلالت اور استنباط کا طریقہ ہے۔ قواعد فقہیہ کا موضوع پہلے سے مستنبط فقہی احکام اور ان میں پائے جانے والے مشترک عملی معانی ہیں۔ ایک علم دلیل سے حکم تک جاتا ہے؛ دوسرا متعدد احکام کو ایک کلی نظم میں جمع کرتا ہے۔","«نہی تحریم پر دلالت کرتی ہے» اصولی قاعدہ ہے، کیونکہ یہ نص کو پڑھنے کا طریقہ بتاتا ہے۔ «ضرر دور کیا جائے گا» فقہی قاعدہ ہے، کیونکہ عیب، پڑوسی کے ضرر، طبی علاج اور معاملات کی بہت سی فروع کو منظم کرتا ہے۔","اصول فقہ اور قواعد فقہیہ دونوں فقہی فکر کو منظم کرتے ہیں مگر ان کا کام مختلف ہے۔ اصول فقہ بنیادی طور پر ادلہ سے حکم اخذ کرنے کے قواعد دیتا ہے، جبکہ قواعد فقہیہ بڑی تعداد میں فروعات کے مشترک فقہی معنی کو جامع کلی یا اکثری قاعدے میں سمیٹتے ہیں۔","اصولی قاعدے میں غلطی نص کی تعبیر اور ابتدائی حکم دونوں کو متاثر کرسکتی ہے۔ فقہی قاعدے میں غلطی عموماً فروع کی درجہ بندی یا نئی صورت کے انطباق میں ظاہر ہوتی ہے۔ اسی لیے اصولی قاعدہ مجتہد کے استنباطی آلے اور فقہی قاعدہ مفتی و قاضی کے تطبیقی نقشے کا کام کرتا ہے۔","اگر امر کو بلا قرینہ ندب سمجھ لیا جائے تو واجب حکم کمزور ہوسکتا ہے۔ اگر «ضرر دور ہوگا» کو بے حد لگایا جائے تو ایک معمولی ضرر دور کرنے کے لیے بڑا ضرر پیدا کیا جاسکتا ہے۔ دونوں علوم کی غلطی مختلف مقام پر اثر ڈالتی ہے۔"],"definitions":[],"originalNumber":103},{"number":104,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قواعدِ فقہیہ خمسہ کون سے ہیں، اور ان کی جامعیت کی وجہ کیا ہے؟","answer":["پانچ بڑے فقہی قواعد نیت، یقین، مشقت، ضرر اور عرف سے متعلق ہیں۔ انہیں حفظ کرنے کے ساتھ ہر قاعدے کی شرط اور استثناء بھی سمجھیں؛ مثلاً مشقت ہر معمولی تکلیف نہیں، اور عرف نص کے خلاف معتبر نہیں۔ یہ قواعد فقہی احکام کی تنظیم میں مدد دیتے ہیں، لیکن ہر ایک مسئلے میں ثبوت اور تطبیق الگ تحقیق مانگتے ہیں۔ ذیلی قاعدے کبھی اصل قاعدے کو واضح اور کبھی اس کی حد متعین کرتے ہیں۔","قواعدِ خمسہ پانچ عظیم کلی قواعد ہیں جن کے تحت فقہ کے بہت سے ابواب اور ذیلی قواعد آتے ہیں: «اَلْأُمُورُ بِمَقَاصِدِهَا»، «اَلْيَقِينُ لَا يَزُولُ بِالشَّكِّ»، «اَلْمَشَقَّةُ تَجْلِبُ التَّيْسِيرَ»، «اَلضَّرَرُ يُزَالُ» اور «اَلْعَادَةُ مُحَكَّمَةٌ»۔","یہ پوری فقہ کا بدل نہیں، بلکہ اس کے بڑے عملی معانی کا نقشہ ہیں۔ نیت، یقین، مشقت، ضرر اور عرف وہ بنیادی عناصر ہیں جو عبادات، معاملات، خاندان اور قضاء کے بے شمار مسائل میں حکم کی تطبیق کو متاثر کرتے ہیں۔","قواعد خمسہ فقہ کے وسیع ابواب میں بار بار ظاہر ہونے والے بنیادی تصورات کو سمیٹتے ہیں: قصد، یقین، مشقت، ضرر اور عرف۔ یہ قواعد نصوص کے متبادل نہیں بلکہ نصوص، فروع اور فقہی استقراء سے اخذ شدہ رہنما اصول ہیں۔","ان کا درست استعمال استثناؤں، شرائط اور دوسرے قواعد کو ساتھ دیکھنے سے ہوتا ہے؛ کسی ایک قاعدے کو مطلق نعرے کی طرح استعمال کرنا غلط نتائج پیدا کرسکتا ہے۔","پانچ بنیادی قواعد جنہیں 'القواعد الکبریٰ' یا 'الکلیات الخمس' کہا جاتا ہے، یہ ہیں: 'الامور بمقاصدھا' (اعمال کا اعتبار نیتوں سے ہے)، 'الیقین لا یزول بالشک' (یقین شک سے زائل نہیں ہوتا)، 'المشقۃ تجلب التیسیر' (مشقت آسانی کو جنم دیتی ہے)، 'الضرر یزال' (نقصان کو دور کیا جائے گا)، اور 'العادۃ محکمۃ' (رواج فیصلہ کن حیثیت رکھتا ہے)۔ یہ پانچوں قواعد پورے فقہی نظام کی بنیاد سمجھے جاتے ہیں۔"],"definitions":[],"originalNumber":104},{"number":105,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قاعدہ «الأمور بمقاصدها» کا مفہوم اور اہم فقہی تطبیقات کیا ہیں؟","answer":["نیت عبادت کی پہچان، عبادات کے باہمی امتیاز اور اجر میں بنیادی کردار رکھتی ہے، مگر ہر عقد کا ظاہری اثر صرف باطنی نیت سے ختم نہیں ہوتا۔ وضو و غسل میں نیت کی شرط پر فقہی اختلاف ہے: حنفیہ کے ہاں طہارت کی صحت اور ثواب کے پہلو الگ ہوسکتے ہیں، جبکہ دوسرے مذاہب میں نیت شرط ہوتی ہے۔ اس مثال کو تمام مذاہب کے لیے ایک ہی حکم بناکر پیش نہ کریں۔","«اَلْأُمُورُ بِمَقَاصِدِهَا» کا مطلب ہے کہ اعمال اور تصرفات کے احکام میں معتبر قصد و مقصد کا اثر ہوتا ہے۔ اس کی اصل حدیث ہے: «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ»۔ نیت عبادت کو عادت سے اور ایک ہی ظاہری عمل کی مختلف قانونی نوعیتوں کو الگ کرتی ہے۔","عملی مثالوں میں زکوٰۃ اور ہبہ کا امتیاز، امانت اور قرض کی نوعیت، اور قسم میں معتبر قصد شامل ہیں۔ نیت کا اثر ہر باب کے اپنے ضابطے کے مطابق ہوتا ہے: مالی عقد میں الفاظ، رضامندی اور قرائن بھی معتبر ہیں، جبکہ عبادت میں نیت کی شرط اور وقت کی تفصیل اہم ہے۔ دھوکے یا ناجائز فائدے کا قصد بعض مباح صورتوں کی دیانتی حیثیت پر اثر ڈال سکتا ہے؛ تاہم باطنی نیت کا علم اور عدالت میں قابلِ ثبوت ظاہری اثر الگ مباحث ہیں۔"],"definitions":[],"originalNumber":105},{"number":106,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قاعدہ «اليقين لا يزول بالشك» فقہی استدلال میں کیسے کام کرتا ہے؟","answer":["یقین شک سے زائل نہیں ہوتا؛ ثابت حالت اس وقت تک برقرار سمجھی جاتی ہے جب تک معتبر تبدیلی ثابت نہ ہو۔ طہارت یقینی ہو اور حدث کا محض شک ہو تو اصل طہارت ہے؛ حدث یقینی ہو اور طہارت مشکوک ہو تو نتیجہ الٹ ہوگا۔ شک، غالب گمان اور معتبر ثبوت ایک درجہ نہیں رکھتے۔ یہ قاعدہ ذمہ داری سے فرار کا راستہ نہیں بلکہ بے بنیاد احتمال اور ثابت امر کے تعلق کا ضابطہ ہے۔","اس قاعدے کو استصحاب سے تعلق ہے، مگر کسی سابق حالت کا وجود معتبر طور پر معلوم ہونا چاہیے۔ محض خواہش سے اصل فرض کرنا کافی نہیں۔ قرض یقینی ہو تو ادائیگی کا محض شک ذمہ داری ختم نہیں کرتا؛ براءتِ ذمہ اصل ہو تو بے ثبوت دعویٰ مالی ذمہ داری ثابت نہیں کرتا۔ یوں ایک ہی قاعدہ معلوم سابق حالت کے بدلنے سے مختلف نتیجہ دیتا ہے۔"],"definitions":[],"originalNumber":106},{"number":107,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قاعدہ «المشقة تجلب التيسير» کی حدود کیا ہیں، اور ہر مشقت رخصت کا سبب کیوں نہیں بنتی؟","answer":["رخصت کا سبب معتبر مشقت ہے، ہر ذاتی ناپسندیدگی نہیں۔ کبھی شریعت نے سفر جیسا منضبط سبب مقرر کیا ہے، اس لیے صرف محسوس تکلیف سے اس کا حکم بدل نہیں جاتا۔ تخفیف کی مقدار، مدت اور صورت بھی متعلقہ دلیل سے طے ہوتی ہے۔ ضرورت اور حاجت کے فرق کو سمجھنا مفید ہے، مگر ان کے نام پر ہر ممنوع معاملہ جائز قرار دینا درست تطبیق نہیں۔","اس قاعدے سے مراد یہ ہے کہ جب کسی مکلف کو کسی حکم کی ادائیگی میں غیرمعمولی مشقت پیش آئے، تو شریعت اس میں تخفیف یا رخصت فراہم کرتی ہے۔ اس کی مثال مریض اور مسافر کے لیے روزے میں رخصت، تیمم کی اجازت پانی نہ ملنے کی صورت میں، اور نمازِ قصر ہے۔ یہ قاعدہ شریعت کی اسی بنیادی روح کو ظاہر کرتا ہے جس کے مطابق 'یرید اللہ بکم الیسر ولا یرید بکم العسر'۔","قرآنی اصول: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ (البقرۃ: 185)","اللہ تمہارے لیے آسانی چاہتا ہے، تنگی نہیں چاہتا۔"],"definitions":[],"originalNumber":107},{"number":108,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قاعدہ «الضرر يزال» کی اہمیت کیا ہے، اور ضرر دور کرنے کی حدود کیا ہیں؟","answer":["ضرر دور کیا جاتا ہے، لیکن ایک ضرر دور کرنے کے لیے مساوی یا زیادہ ضرر پیدا نہیں کیا جاتا۔ معتبر ضرر، اس کا امکان، متاثرہ اشخاص اور متبادل صورتیں دیکھنا ضروری ہے۔ معمول کے جائز کاروباری مقابلے میں ہونے والا نقصان اور ظلم سے پیدا نقصان یکساں نہیں۔ ضرر کا عمومی اصول خاص نصوص اور حقوق کے ساتھ پڑھا جائے؛ محض فائدے کے دعوے پر کسی کا ثابت حق ساقط نہیں ہوتا۔","«اَلضَّرَرُ يُزَالُ» کا مرکزی تقاضا یہ ہے کہ ناجائز ضرر کو روکا یا ممکن حد تک دور کیا جائے۔ اصل نبوی قاعدہ ہے: «لَا ضَرَرَ وَلَا ضِرَارَ»؛ نہ ابتدا سے نقصان پہنچانا جائز ہے، نہ بدلے میں غیر قانونی نقصان۔","عیب دار مال واپس کرنے کا حق، پڑوسی کو نقصان دینے والی تعمیر روکنا اور خطرناک چیز بازار سے ہٹانا اسی معنی سے متعلق ہیں۔ مگر ضرر دور کرنے کا طریقہ متناسب ہوگا؛ کسی چھوٹے ضرر کو دور کرنے کے لیے اس سے بڑا ضرر پیدا نہیں کیا جاسکتا۔"],"definitions":[],"originalNumber":108},{"number":109,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":56,"chapter_title":"قواعد فقہیہ خمسہ کا تعارف","question":"قاعدہ «العادة محكمة» عرف اور زمان و مکان کی تبدیلی کو فقہی فیصلے سے کیسے جوڑتا ہے؟","answer":["معتبر عرف عام یا غالب، متعلقہ معاملے کے وقت موجود اور نص یا صریح شرط کے خلاف نہ ہو۔ عرف لفظ کی مراد، اجرت یا معاملے کی معروف ذمہ داری سمجھانے میں مدد دے سکتا ہے۔ فاسد عرف کثرت سے رائج ہونے پر شرعی حجت نہیں بن جاتا۔ عرف بدلنے سے بعض تطبیقی احکام بدل سکتے ہیں، مگر اس سے عبادات کی مقرر صورت یا قطعی ممانعت خودبخود تبدیل نہیں ہوتی۔","اس قاعدے سے مراد یہ ہے کہ کسی معاشرے کا معروف اور مسلسل رواج، جب تک شرعی نص سے متصادم نہ ہو، فقہی معاملات کی تفصیلات کے تعین میں معتبر اور فیصلہ کن حیثیت رکھتا ہے۔ اس کی مثال یہ ہے کہ نکاح میں مہرِ مثل کا تعین علاقے کے رائج معیار کے مطابق کیا جاتا ہے، یا کسی معاہدے میں غیرمذکور تفصیلات کو مقامی تجارتی رواج کے مطابق سمجھا جاتا ہے۔","عرف بدلنے سے وہ اجتہادی فتویٰ یا عملی تطبیق بدل سکتی ہے جو اسی عرف، مصلحت یا حالات پر قائم تھی۔ اصل شرعی حکم نہیں بدلتا؛ اکثر اس کا موضوع، صورت یا خارجی محل بدلتا ہے۔","مشہور قاعدہ ہے: «لَا يُنْكَرُ تَغَيُّرُ الْأَحْكَامِ بِتَغَيُّرِ الْأَزْمَانِ»","درست مفہوم: زمانے اور عرف کے بدلنے سے عرف پر مبنی اجتہادی احکام و فتاویٰ کی تطبیق بدل سکتی ہے۔ اس سے قطعی حلال و حرام یا مقرر عبادات کے بدلنے کا جواز مراد نہیں۔","مثلاً نفقے کی مناسب مقدار، عیب سمجھی جانے والی تجارتی حالت، مکان کے استعمال کی متعارف حدود، یا قبضے کا طریقہ زمان و مکان کے ساتھ بدل سکتا ہے۔ نقد رقم کی دستی وصولی کبھی اصل طریقہ تھی؛ آج معتبر بینک اندراج یا محفوظ ڈیجیٹل منتقلی بعض معاملات میں قبضے کا قائم مقام ہوسکتی ہے۔","امام قرافی اور ابن عابدین نے متنبہ کیا کہ عرف پر قائم جواب کو بدلے ہوئے عرف میں بلا تحقیق دہرانا لوگوں کے حقوق خراب کرسکتا ہے۔","مجتہد یا مفتی کو پہلے حکم کی بنیاد معلوم کرنی چاہیے۔ اگر بنیاد نص ثابت ہے تو عرف اسے نہیں بدلتا۔ اگر بنیاد متغیر عرف ہے تو نئے عرف کی صحت، غلبہ اور نتائج جانچ کر تطبیق نئی ہوسکتی ہے۔"],"definitions":[],"originalNumber":109},{"number":110,"unit_id":11,"unit_name":"یونٹ یازدہم","unit_title":"اصول، فروع اور قواعد فقہیہ","chapter_number":57,"chapter_title":"تخریج الفروع علی الاصول","question":"تخریج الفروع علی الاصول کیا ہے، اور اس کے ذریعے اختلافِ فروع کی اصولی بنیاد کیسے سمجھی جاتی ہے؟","answer":["تخریج میں نئے مسئلے کو مذہب کے منقول اصول یا نظیر سے جوڑا جاتا ہے، مگر تخریج شدہ قول اور امام کا صریح منقول قول الگ ہیں۔ تخریجِ مناط علت کی شناخت کا کام ہے، جبکہ تخریجِ فروع اصول پر عملی حکم قائم کرنے کا عمل ہے۔ ناموں کی مشابہت سے انہیں خلط نہ کریں۔ درست تخریج کے لیے اصل کی نسبت، مشترک وصف، مؤثر فرق اور مذہب کے دوسرے متعلقہ قواعد کی جانچ ضروری ہے۔","مثلاً خبرِ واحد سے غیر مخصوص عام کی تخصیص میں دو اصولی مناہج مختلف ہوں تو متعلقہ فرعی احکام میں فرق کی ایک بنیاد سامنے آسکتی ہے۔ تحقیق کرنے والا اصل فرع، اس کی دلیل اور اصولی عبارت جمع کرکے تعلق دکھائے گا۔ لیکن جہاں ایک اور حدیث، خاص قرینہ یا باب کا استثناء نتیجہ بدل دے وہاں صرف عمومی اصول کافی نہیں۔ تخریج کا حاصل یہ بتانا ہے کہ نتیجہ کیسے بنا؛ صریح نسبت کے بغیر یہ کہنا نہیں کہ امام نے بعینہٖ یہی اصول اسی عبارت سے لکھا تھا۔"],"definitions":[],"originalNumber":110},{"number":111,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":58,"chapter_title":"معاصر اجتہاد","question":"معاصر اجتہاد سے کیا مراد ہے، اور نئے مسائل میں نص، مقاصد اور واقعہ شناسی کو کس طرح جمع کیا جاتا ہے؟","answer":["معاصر مسئلہ حل کرنے میں سب سے پہلے اس کی حقیقی صورت اور فنی ساخت سمجھنا ضروری ہے۔ نیا نام لازماً نیا حکم نہیں بناتا، اور ظاہری مشابہت لازماً پرانے حکم کی پوری تطبیق نہیں ہوتی۔ حقوق، خطرات، ملکیت اور عملی نتائج معلوم کرنے کے بعد متعلقہ نصوص، نظائر اور اصول دیکھیں۔ تحقیق میں مشروط نتیجہ زیادہ درست ہوسکتا ہے؛ نامعلوم حقیقت پر قطعی فتویٰ علمی احتیاط کے خلاف ہے۔","معاصر اجتہاد سے مراد موجودہ دور کے نئے یا بدلے ہوئے مسائل کا حکم معتبر شرعی دلائل اور اصولوں سے پوری علمی کوشش کے ساتھ اخذ کرنا ہے۔ یہ شریعت کو زمانے کے تابع کرنا نہیں، بلکہ ثابت نصوص کو صحیح طور پر نئے واقعے پر منطبق کرنا ہے۔","مثلاً ڈیجیٹل کرنسی، اعضا کی پیوندکاری اور مصنوعی ذہانت قدیم ناموں سے موجود نہ تھے۔ ان پر حکم لگانے سے پہلے حقیقت سمجھی جاتی ہے، پھر نصوص، فقہی نظائر، قیاس، مقاصد اور مآلات دیکھے جاتے ہیں۔ قطعی حکم اجتہاد سے تبدیل نہیں ہوتا؛ اجتہاد نئی صورت کی تکییف اور حکم کے انطباق میں ہوتا ہے۔","مقاصد جزوی دلیل کو شریعت کے عدل، رحمت، حفظِ دین، جان، عقل، نسل اور مال کے نظام میں رکھتے ہیں۔ واقعہ شناسی بتاتی ہے کہ نئی صورت حقیقت میں کیا ہے، کس پر اثر ڈالتی ہے اور اس کے نتائج کیا ہیں۔ مقصد نص کو منسوخ نہیں کرتا؛ اس کی صحیح علت اور انطباق سمجھنے میں مدد دیتا ہے۔","اعضا کی پیوندکاری میں جان بچانے، انسانی حرمت، رضامندی، ضرر اور تجارتِ اعضا سب دیکھے جاتے ہیں۔ صرف «علاج مفید ہے» کافی نہیں اور صرف قدیم صورت کا نام بھی کافی نہیں۔ معاصر فقہی مجالس نے طبی ماہرین کے تعاون سے انہی پہلوؤں پر اجتماعی غور کیا ہے۔"],"definitions":[],"originalNumber":111},{"number":112,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":63,"chapter_title":"اصولی تطبیق کا عملی منہج","question":"اگر آپ کو کسی بالکل نئے فقہی مسئلے پر تحقیق کرنا ہو تو آپ کن مرحلہ وار اصولوں سے آغاز کریں گے؟","answer":["تحقیق کی ترتیب یہ ہو: واقعہ کی تحدید، متعلقہ حقائق کی تصدیق، محلِ نزاع، نصوص و سابقہ فتاویٰ، اصولی تحلیل، متبادل صورتیں، پھر شرائط کے ساتھ نتیجہ۔ صرف آخری حکم نقل کرنے سے دوسرے حالات میں غلط اطلاق ہوسکتا ہے۔ تحقیقی تحریر میں معلوم حقیقت، مفروضہ اور غیر ثابت اطلاع کو جدا درج کریں۔ ماخذ کی عبارت اور اپنی استنباطی رائے کا امتیاز بھی ضروری ہے تاکہ نتیجے کا علمی وزن واضح رہے۔","صورت بندی ایک واضح، غیر جانب دار سوال میں فریق، عمل، محل، وقت اور مطلوب فیصلہ متعین کرتی ہے۔ جذباتی نام اور پیشگی حکم الگ رکھے جاتے ہیں۔ ایک پیچیدہ واقعے کو ضرورت کے مطابق ذیلی سوالات میں تقسیم کیا جاتا ہے۔","مالی ٹیکنالوجی کا عمومی عنوان بہت مبہم ہے۔ بہتر سوال یہ ہے کہ کسی خاص اطلاقیے میں نقد رقم کی پیشگی ادائیگی، خدمت کی مقرر فیس اور تاخیر کا اضافی معاوضہ کس عقد کا حصہ ہیں؟ سوال کو یوں واضح کرنے سے قرض، اجرت اور مرکب معاملے کے متعلق دلائل سامنے آتے ہیں اور غیر متعلق بحث کم ہوتی ہے۔","عملی اصولی تطبیق ایک مرحلہ وار علمی عمل ہے: مسئلے کی درست صورت بندی، معتبر حقائق کی جمع، فقہی تکییف، متعلقہ نصوص و آثار، دلالت و ثبوت کی جانچ، اصول و قواعد کا انتخاب، مختلف آرا کا تقابل، مقاصد و مآلات کا وزن، اور آخر میں حدود و درجۂ اعتماد کے ساتھ نتیجہ۔","اچھا اصولی جواب صرف حتمی حکم نہیں دیتا بلکہ یہ بھی دکھاتا ہے کہ کن حقائق، مفروضات اور دلائل پر وہ حکم قائم ہے، کون سا اعتراض سب سے مضبوط ہے، اور نئی معلومات آنے پر کہاں نظرثانی ممکن ہوگی۔","فقہی تحقیق کا پہلا مرحلہ مسئلے کا واضح اور دقیق تعین ہے، یعنی محقق کو یہ طے کرنا ہوتا ہے کہ اصل سوال کیا ہے، اس کے کیا کیا پہلو ہیں، اور کیا اس پر پہلے سے کوئی نص یا فقہی رائے موجود ہے۔ یہ مرحلہ نہایت اہم ہے کیونکہ غیرواضح یا مبہم مسئلے پر تحقیق کرنا وقت اور محنت کے ضیاع کا باعث بن سکتا ہے، اور نامناسب نتیجے کی طرف لے جا سکتا ہے۔","تحریرِ محلِ نزاع سے مراد یہ ہے کہ محقق واضح طور پر بیان کرے کہ اختلاف کا اصل نکتہ کیا ہے، اور کن پہلوؤں پر تمام فقہاء متفق ہیں اور کن پہلوؤں پر اختلاف پایا جاتا ہے۔ یہ مرحلہ نہایت اہم ہے کیونکہ بعض اوقات بظاہر مختلف نظر آنے والی آراء دراصل ایک ہی نتیجے پر پہنچتی ہیں، محض الفاظ کا فرق ہوتا ہے، اور صحیح تحریرِ محلِ نزاع اس طرح کی غلط فہمیوں سے بچاتی ہے۔"],"definitions":[],"originalNumber":112},{"number":113,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":58,"chapter_title":"معاصر اجتہاد","question":"معاصر اجتماعی اجتہاد میں فقہاء، ماہرینِ قانون، معاشیات، طب اور دیگر تخصصات کا اشتراک کیوں ضروری ہے؟","answer":["ماہرِ فن واقعے کی حقیقت بتاتا ہے اور فقیہ اس حقیقت پر شرعی ضابطے لاگو کرتا ہے؛ بعض مسائل میں دونوں کے باہمی سوالات ناگزیر ہیں۔ ماہر کی رائے بھی تخصص، شواہد اور ممکنہ مفاد کے لحاظ سے جانچی جائے۔ مختلف آراء ہوں تو اختلاف کی وجہ معلوم کریں۔ طبی خطرہ، مالی ملکیت یا نظام کی عملی کارکردگی کی غلط معلومات پر درست اصول بھی غلط نتیجہ دے سکتے ہیں۔","مشترک تحقیق میں فقیہ پہلے ماہر سے یہ پوچھے کہ کون سی حقیقت قطعی، کون سی اندازاً معلوم اور کون سی ابھی غیر ثابت ہے۔ معاشی معاملے میں ملکیت اور نقصان کی ذمہ داری، طبی مسئلے میں خطرے اور متبادل، اور برقی نظام میں اختیار و نگرانی معلوم کرنا اہم ہے۔ ماہرین ایک دوسرے کی اصطلاحات واضح کریں، پھر شرعی سوال درست صورت میں مرتب ہو۔ اختلاف باقی ہو تو نتیجے میں مفروضات اور شرائط درج ہوں؛ غیر ثابت فنی دعوے کو قطعی شرعی حکم کی بنیاد نہ بنایا جائے۔"],"definitions":[],"originalNumber":113},{"number":114,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":59,"chapter_title":"معاصر مالی مسائل میں اصولی تطبیق","question":"کسی جدید مالی مصنوع کی فقہی تکییف کرتے وقت اس کے نام کے بجائے حقیقی ساخت، ملکیت، ضمان اور خطرے کو کیوں دیکھا جاتا ہے؟","answer":["جدید مالی معاملے میں نام کے بجائے اصل حقوق و ذمہ داریاں دیکھیں: مال کس کی ملکیت ہے، قبضہ کیسے ہوتا ہے، نفع کس بنیاد پر اور نقصان کس پر ہے؟ سود، غرر، قمار اور ناجائز شرط کے امکانات الگ جانچیں۔ صرف اسلامی عنوان یا دستاویز کے چند الفاظ کافی نہیں؛ عملی نفاذ بھی معتبر ہونا چاہیے۔ ایک خاص مالی مصنوع کا حکم اس کے مکمل معاہدے اور طریقۂ کار کے بغیر عمومی طور پر نہیں دیا جاسکتا۔","شریعت معاملات میں نام سے زیادہ حقیقت اور اثر دیکھتی ہے۔ معروف قاعدہ ہے: «اَلْعِبْرَةُ فِي الْعُقُودِ لِلْمَقَاصِدِ وَالْمَعَانِي لَا لِلْأَلْفَاظِ وَالْمَبَانِي»۔ ظاہری دستاویز جائز عقد کی ہو، مگر معاشی حقیقت سودی قرض ہو تو نام حکم نہیں بدلتا۔","معاصر مالی مسائل میں ظاہری نام کے بجائے حقیقی معاشی ساخت اور حقوق و ذمہ داریوں کو دیکھنا اصولی ضرورت ہے۔ قرض، بیع، اجارہ، ضمان، وکالت یا مشارکت میں فرق صرف دستاویزی عنوان سے نہیں بلکہ ملکیت، خطرے، عوض اور التزام کی حقیقت سے متعین ہوتا ہے۔","جامع کیس اسٹڈی میں مقصد کسی ایک قاعدے کو فوری طور پر لاگو کرنا نہیں بلکہ پیچیدہ واقعے کو قابلِ تحلیل اکائیوں میں تقسیم کرنا ہے۔ فریق، حقوق، عقود، افعال، اسباب، ضرر، عرف اور زمانی ترتیب واضح کی جاتی ہے، پھر ہر ذیلی مسئلے کی الگ تکییف اور دلیل دیکھی جاتی ہے۔","برقی بٹوے میں جمع رقم کی تکییف معاہدے اور عملی انتظام پر منحصر ہے۔ رقم الگ محفوظ ہو اور منتظم استعمال نہ کرسکتا ہو تو امانت یا وکالت کے پہلو ہوسکتے ہیں؛ استعمال اور واپسی کی ضمانت ہو تو قرض کا پہلو نمایاں ہوسکتا ہے۔ اس ایک علامت سے پوری مصنوع کا حکم نہیں نکلتا؛ فیس، سرمایہ کاری، قبضہ، متعلقہ حقوق اور دوسرے عقود بھی دیکھنے ہوں گے۔"],"definitions":[],"originalNumber":114},{"number":115,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":60,"chapter_title":"طبی اور حیاتیاتی مسائل میں اصولی تطبیق","question":"اعضاء کی پیوندکاری، مصنوعی بارآوری یا دوسرے طبی مسائل میں اصولی فیصلہ سازی کے بنیادی مراحل کیا ہوں گے؟","answer":["اعضاء کی پیوندکاری میں علاج کی ضرورت، متبادل، عطیہ دہندہ کو ضرر، معتبر رضامندی اور اعضاء کی فروخت کے مسائل اہم ہیں۔ رضامندی اکیلی ہر صورت کو جائز نہیں بناتی۔ تولیدی علاج میں زوجین کے اپنے نطفے اور بیضے، اسی بیوی کے رحم اور قائم نکاح کی شرائط اہم ہیں؛ تیسرے فریق کے نطفے، بیضے یا رحم سے نسب کے مسائل پیدا ہوتے ہیں۔ ان مسائل کا عملی حکم ماہرِ طب اور معتبر فقہی رہنمائی کے ساتھ مخصوص صورت پر دیا جائے۔","بالغ اہل مریض کی باخبر رضامندی اصل ہے۔ اسے علاج کی نوعیت، نمایاں خطرات، متبادل اور ترکِ علاج کے اثرات سمجھائے جائیں۔ رضامندی دھوکے، دباؤ یا ناقص معلومات سے معتبر نہیں رہتی۔ ساتھ ہی «لَا ضَرَرَ وَلَا ضِرَارَ» کے تحت معالج غیر متناسب ضرر نہیں پہنچا سکتا۔","ہنگامی حالت میں بے ہوش مریض کی جان بچانے والا فوری علاج، جب نمائندہ دستیاب نہ ہو، مفروض اجازت اور ضرورت پر کیا جاسکتا ہے۔ مگر غیر ضروری تجربہ نہیں۔ نابالغ کے ولی کی اجازت بھی بچے کی مصلحت کے تابع ہے؛ ولی کو واضح نقصان کی اجازت کا مطلق اختیار نہیں۔","طبی و حیاتیاتی نوازل میں شرعی حکم سے پہلے طبی حقیقت، خطرے کا درجہ، متبادل علاج، مریض کی حالت اور ماہرین کے اعتماد کی سطح واضح ہونا ضروری ہے۔ حفظِ نفس اہم مقصد ہے، مگر جسم کی حرمت، نسب، رضامندی، ضرر اور حقوقِ اشخاص بھی ساتھ چلتے ہیں۔","بین الاقوامی اسلامی فقہ اکیڈمی کی قرارداد 26 (1/4)، اعضاء کی پیوندکاری، اور قرارداد 16 (4/3)، مصنوعی تولید، متعلقہ معاصر اجتماعی مراجع ہیں۔ یہاں صرف بنیادی اصول بیان ہوئے ہیں؛ تمام صورتوں کو ایک ہی حکم نہیں دیا گیا۔ ماخذ میں درج مخصوص شرائط کو متعلقہ علاج کی حقیقی صورت کے ساتھ پڑھنا ضروری ہے۔"],"definitions":[],"originalNumber":115},{"number":116,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":61,"chapter_title":"ٹیکنالوجی اور ڈیجیٹل مسائل میں اصولی تطبیق","question":"مصنوعی ذہانت، ڈیجیٹل عقود اور خودکار فیصلوں کے فقہی جائزے میں کن اصولی سوالات کو مقدم رکھا جائے گا؟","answer":["مصنوعی ذہانت اور برقی معاہدوں میں انتساب، رضامندی، اختیار، رازداری، غلطی کی ذمہ داری اور ثبوت کی جانچ بنیادی ہے۔ کمپیوٹر کا جواب بذات خود شرعی حجت نہیں؛ اس کی نقل کردہ عبارت اصل ماخذ سے ملائی جائے۔ خودکار نظام کس کے مجاز عمل کی نمائندگی کرتا ہے، یہ طے کیے بغیر ذمہ داری نہیں باندھی جاسکتی۔ برقی رضامندی معتبر ہوسکتی ہے، مگر شناخت اور متعلقہ معاملے کی شرائط کی تصدیق ضروری ہے۔","ڈیجیٹل مسائل میں فقہی تکییف اس وقت درست ہوتی ہے جب نظام کی تکنیکی ساخت واقعی سمجھی جائے۔ الگورتھم، ڈیٹا، خودکار فیصلہ، ڈیجیٹل ملکیت یا آن لائن عقد کے شرعی آثار محض نئے ناموں سے نہیں بلکہ فاعل، اختیار، رضامندی، ملکیت، ضرر اور جواب دہی کے تعلق سے متعین ہوتے ہیں۔","مثلاً علاج کے خودکار نظام میں غلطی ہو تو معلومات کا نقص، نظام کی جانچ، ادارے کی نگرانی اور معالج کی مناسب تحقیق الگ دیکھی جائیں۔ محض مشین کے جواب سے انسان کی ہر ذمہ داری ختم نہیں ہوتی، اور ہر غیر متوقع خرابی بھی لازماً ایک ہی شخص پر نہیں آتی۔ ضمان یا قانونی جواب دہی کا عملی فیصلہ سبب، اختیار، تقصیر، معاہدے اور متعلقہ قانون کی تحقیق چاہتا ہے۔"],"definitions":[],"originalNumber":116},{"number":117,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":62,"chapter_title":"سماجی اور عالمی مسائل میں اصولی تطبیق","question":"فقہ الاقلیات کو آپ ایک الگ شریعت کے بجائے اصولی تطبیق کے ایک خاص سیاق کے طور پر کیسے سمجھائیں گے؟","answer":["اقلیتوں کے مسائل میں عام شرعی اصول برقرار رہتے ہیں، مگر مقامی قانون، دینی آزادی، حقیقی ضرورت اور عملی متبادل کی تحقیق خاص اہم ہے۔ مسلمان اقلیت ہونا ہر ممنوع صورت کی اجازت کا مستقل سبب نہیں۔ حاجت کی وسعت، حکم کے اثرات اور جائز راستے معلوم کیے جائیں۔ فتویٰ متعلقہ معاشرے کے حقیقی حالات پر قائم ہو؛ دوسرے ملک کے جواب کو حالات دیکھے بغیر منتقل کرنا غلط نتیجہ دے سکتا ہے۔","فقہ الاقلیات سے مراد غیر مسلم اکثریتی معاشروں میں رہنے والے مسلمانوں کے ان مسائل کا فقہی مطالعہ ہے جن میں کلاسیکی احکام کو ایک مختلف قانونی، سماجی اور شہری سیاق میں سمجھنے اور منطبق کرنے کی ضرورت پیش آتی ہے۔ اس تصور کو معاصر دور میں طہٰ جابر العلوانی، یوسف القرضاوی اور دیگر اہلِ علم نے نمایاں طور پر منظم کیا۔ اس کا مطلب یہ نہیں کہ اقلیتوں کے لیے کوئی الگ شریعت ہے؛ اصل نصوص اور بنیادی احکام وہی رہتے ہیں، البتہ واقعہ، عرف، قانونی ماحول اور مناطِ حکم کی تبدیلی سے تطبیق کی صورت بدل سکتی ہے۔","اس پر ایک اہم علمی اعتراض یہ ہے کہ الگ عنوان کہیں شریعت کی وحدت کو کمزور نہ کردے یا جغرافیے کی بنیاد پر بے ضابطہ رعایتوں کا دروازہ نہ کھول دے۔ اس اعتراض کا اصولی جواب یہ ہے کہ کلاسیکی فقہ خود حکم اور محلِ اطلاق میں فرق کرتی ہے۔ فقہ النوازل، عرف، ضرورت، مصلحت اور تحقیقِ مناط کے مباحث اسی بات کی مثال ہیں کہ ایک ہی شرعی اصول مختلف حالات میں مختلف عملی صورت اختیار کرسکتا ہے۔","اس لیے فقہ الاقلیات کو بہتر طور پر اصولی تطبیق کے ایک خاص میدان کے طور پر سمجھنا چاہیے: پہلے مسئلے کی صحیح صورت بندی کی جائے، پھر متعلقہ نصوص، مقاصد، عرف، مصلحت، معاہداتی ذمہ داریوں اور مآلات کو دیکھا جائے، اور آخر میں ایسا حکم متعین کیا جائے جو شریعت کے ثابت اصولوں سے وفادار بھی ہو اور حقیقی صورتِ حال کو بھی درست طور پر سمجھے۔"],"definitions":[],"originalNumber":117},{"number":118,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":62,"chapter_title":"سماجی اور عالمی مسائل میں اصولی تطبیق","question":"فقہ الاقلیات میں مقاصد، مصلحت، عرف، ضرورت اور مآلات جیسے اصول کس طرح کام کرتے ہیں؟","answer":["مقاصد اقلیتی حالات میں دین، جان، خاندان، عقل اور مال کے تحفظ کی متوازن تحقیق میں مدد دیتے ہیں۔ صرف معاشرتی آسانی یا صرف ایک منفعت کو فیصلہ کن بنانا کافی نہیں۔ ایک ضرورت کے جواب میں دوسرے بنیادی حق پر کیا اثر پڑتا ہے، یہ دیکھیں۔ قانونی تعمیل، عہد کی پابندی اور اجتماعی تعلقات بھی متعلق ہوسکتے ہیں؛ مگر مقاصد کی زبان کسی واضح حکم کو بلا دلیل معطل کرنے کا جواز نہیں بنتی۔","جزوی نص پہلے اپنے معنی اور حد میں قائم رہتی ہے۔ مقاصد اس کے شرعی محل اور مجموعی حکمت کو واضح کرتے ہیں؛ مصالح نئی صورت کی حقیقی خیر و ضرر بتاتی ہیں؛ مآلات متوقع نتائج کا جائزہ لیتے ہیں۔ یہ سب نص کے تابع اور باہمی درجہ بندی میں ہوتے ہیں۔","قرض میں مہلت کی آیت تنگ دست کی حفاظت کرتی ہے، مگر مال دار کا جان بوجھ کر تاخیر حدیث کے مطابق ظلم ہے۔ مقصدِ رحمت دونوں کو مٹا نہیں دیتا؛ حقیقی تنگ دستی اور سوء نیت میں فرق قائم کرتا ہے۔"],"definitions":[],"originalNumber":118},{"number":119,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":63,"chapter_title":"اصولی تطبیق کا عملی منہج","question":"معاصر فقہی تحقیق میں کلاسیکی مصادر، مقاصدِ شریعت اور بین التخصصی علوم کے درمیان توازن کیسے قائم کیا جائے؟","answer":["کلاسیکی اصول فہمِ دلیل کا منہج دیتے ہیں اور جدید تخصص واقعے کی نئی تفصیل سمجھاتا ہے؛ مضبوط تحقیق دونوں کی متعلقہ حدود پہچانتی ہے۔ پرانی مثال کا حکم جدید صورت پر لگانے سے پہلے مشترک علت اور فرق جانچیں۔ کسی روایت کی سند کمزور ہو تو اس سے متعلق ہر فقہی حکم فوراً باطل نہیں ہوتا؛ دیگر شواہد اور مستقل دلائل ہوسکتے ہیں۔ اسی طرح قدیم فتویٰ کا وجود نئی صورت کی پوری تحقیق کا بدل نہیں۔","استقراءِ نصوص سے مراد قرآن، سنت اور دیگر متعلقہ مصادر کا وسیع اور مکمل مطالعہ کرنا ہے، تاکہ زیرِ تحقیق مسئلے سے متعلق تمام موجود نصوص کو جمع کیا جا سکے۔ اس مرحلے میں محقق کو یہ خاص خیال رکھنا ہوتا ہے کہ کوئی متعلقہ نص چھوٹ نہ جائے، کیونکہ نامکمل استقراء سے غلط یا نامکمل نتیجہ نکل سکتا ہے۔","محقق کو ہر رائے (قول) کے حاملین کے دلائل کو مکمل طور پر، ان کے اپنے الفاظ اور استدلال کے ساتھ، جمع کرنا چاہیے، بغیر کسی جانبداری کے۔ اس مرحلے میں امانتداری بنیادی اصول ہے: محقق کو ہر رائے کو اس کی مضبوط ترین صورت میں پیش کرنا چاہیے، تاکہ آخری فیصلہ منصفانہ اور جامع بنیاد پر ہو سکے، نہ کہ کسی رائے کو کمزور کر کے دوسری کو ترجیح دینا۔","الترجیح کے مرحلے میں محقق تمام جمع کردہ دلائل، ان پر ہونے والے مناقشے، اور ان کے جوابات کا مکمل جائزہ لینے کے بعد، یہ فیصلہ کرتا ہے کہ کون سی رائے سب سے زیادہ مضبوط دلیل، مقاصدِ شریعت سے ہم آہنگی، اور موجودہ حالات کے لیے موزونیت رکھتی ہے۔ یہ فیصلہ خالص علمی دیانتداری اور تمام دلائل کے متوازن جائزے کا نتیجہ ہونا چاہیے، ذاتی خواہش یا تعصب کا نہیں۔"],"definitions":[],"originalNumber":119},{"number":120,"unit_id":12,"unit_name":"یونٹ دوازدہم","unit_title":"معاصر اصول فقہ اور عملی تطبیقات","chapter_number":64,"chapter_title":"جامع اصولی مطالعات اور کیس اسٹڈیز","question":"اگر آپ کو بی ایس یا ایم فل کی کلاس میں فقہی اختلاف پڑھانا ہو تو آپ اسے علمی، غیر جانب دار اور دلچسپ انداز میں کیسے پیش کریں گے؟","answer":["بہتر تدریس میں تعریف، امتیاز، معتبر مثال، اعتراض اور جواب یکجا ہوں۔ طالب علم پہلے مختصر درست جواب دے، پھر دلیل اور شرط بتائے، اور آخر میں مثال پر تطبیق کرے۔ نامعلوم جزئیہ میں عدمِ علم کا اعتراف علمی صلاحیت کا حصہ ہے۔ صرف اصطلاحات یاد کرانے کے بجائے ایک نص یا معاملے پر مرحلہ وار مشق کرائیں؛ اس سے اصولی بنیاد انٹرویو کے علاوہ مطالعے، تدریس اور عملی تحقیق میں بھی کام آتی ہے۔","ایک تدریسی نشست میں لفظ قرء کی مثال لیں: پہلے آیت اور محلِ اختلاف متعین کریں، پھر حنفی اور شافعی توضیح ان کے مستند ماخذ سے پیش کریں، پھر طلبہ سے پوچھیں کہ کون سا قرینہ کس معنی کو مضبوط کرتا ہے۔ بی ایس میں اصطلاح اور مثال پر، جبکہ ایم فل میں مصادر، اعتراضات اور اصولی ترجیح پر زیادہ توجہ دیں۔ جانچ کا معیار مخالف موقف کی درست ترجمانی، دلیل کی شناخت اور مربوط استدلال ہو؛ محض استاد کے پسندیدہ قول کی تکرار کو علمی کامیابی نہ سمجھیں۔"],"definitions":[],"originalNumber":120}],"content_revision":"4.0 — revised teaching MCQs and Shashi/Talwih-sourced definition cards","source_catalog":{"TALWIH":{"book":"التلويح على التوضيح لمتن التنقيح","section":"متعدد ابواب (ہر سوال کے ساتھ مخصوص باب درج ہے)","url":"https://shamela.ws/book/9508"},"SHASHI":{"book":"أصول الشاشي","section":"متعدد ابواب (ہر سوال کے ساتھ مخصوص باب درج ہے)","url":"https://shamela.ws/book/6302"},"READ":{"book":"کلاسیکی اصولِ فقہ کی عام تعلیمی تلخیص","section":"متعدد ابواب (ہر سوال کے ساتھ مخصوص باب درج ہے)","url":""}}};
